-- jargon B+1.46 — literacy-pack reconciliation (363 terms) — 2026-06-14
-- https://supabase.com/dashboard/project/jargon-local/sql/new
--
-- Brings the live DB in line with the reconciled seed: the 16 previously-empty
-- coding paths get their elevated, deduped content. Apply-order-independent and
-- idempotent — works whether or not 059..085 were applied:
--   * re-asserts the 29-path CHECK so the new path values are accepted standalone
--   * UPSERTs 363 curated rows (insert fresh, or update an existing weak
--     row to the elevated wording + final path)
--   * deletes the 18 exact-duplicate concept rows from the merged packs
--     (their prerequisites were repointed onto the surviving id in the upsert)
--
-- Pairs with cloud-migration-086 (ease_factor/lapse_count). Safe to re-run.

begin;

-- 1. Ensure the path CHECK allows the full 29-path taxonomy (mirror of 085).
alter table terms drop constraint if exists terms_path_check;
alter table terms add constraint terms_path_check check (path in (
  'git-cli','dev-concepts','enterprise','claude-code','ai-engineering','agile','systems',
  'programming','dev-tooling','dev-workflow','web-api','databases','computing','networking',
  'security','architecture','systems-engineering','cloud-devops','qa-reliability','math-logic',
  'tech-stack','enterprise-platforms','data-analytics',
  'ai-foundations','ai-tools','ai-prompting','ai-products','ai-evaluation','ai-policy'
));

-- 2. Upsert the elevated, deduped corpus.
insert into terms (
  id, term, pronunciation, path, domain, difficulty,
  one_line_definition, long_definition, example_in_sentence, why_it_matters,
  related_terms, prerequisites, stretch_term,
  multiple_choice_distractors, fill_in_blank_sentence, use_in_sentence_prompt,
  source, reviewed_by, reviewed_at
) values
('agile-acceptance-criteria', 'acceptance criteria', null, 'agile', 'coding', 2, 'The specific conditions that must be true before a piece of work counts as done.', 'Acceptance criteria turn "make it better" into checkable facts. They might say the sign-in screen has 24px between sections, OAuth and magic link both work, the version pill opens, and mobile has no clipped buttons. Good criteria remove guesswork from review without killing judgment.', 'the acceptance criteria say the mobile sign-in view needs screenshot proof before we merge it.', '"make it better" is unreviewable; acceptance criteria turn it into checkable facts. when you write down what has to be true — both login methods work, no clipped buttons on mobile, screenshot proof attached — review stops being a vibe and becomes a finish line everyone shares.', ARRAY['agile-ticket','agile-regression-test','agile-visual-qa']::text[], ARRAY['agile-ticket']::text[], 'agile-regression-test', ARRAY['a quick first pass checking the main flow still loads','a one-sentence user story describing the behavior wanted','an estimate of how much effort the work will take']::text[], 'the ___ say the mobile sign-in view needs screenshot proof before we merge it.', 'Use ''acceptance criteria'' in a sentence about what must be true for work to count as done.', 'curated', 'curator', '2026-05-25'),
('agile-regression-test', 'regression test', null, 'agile', 'coding', 2, 'A test that checks whether something that used to work has broken after a change.', 'A regression test protects old behavior. When a bug is fixed, you add a test that would fail if the bug ever comes back. When a feature is polished, you run tests that prove the polish did not break login, lesson flow, mobile layout, or other already-working pieces.', 'add a regression test for the mobile sign-in spacing so it can''t collapse on us again.', '"we already fixed this, why is it back?" is the exact pain a regression test prevents. when you fix a bug, you add a test that fails if it ever returns — so a future change can''t quietly resurrect it.', ARRAY['agile-smoke-test','agile-visual-qa']::text[], ARRAY[]::text[], 'agile-acceptance-criteria', ARRAY['a quick first-pass check that the core flow still loads','eyeballing the rendered layout across phone and desktop widths','the specific conditions that mark a piece of work as done']::text[], 'add a ___ for the mobile sign-in spacing so it can''t collapse on us again.', 'Use ''regression test'' in a sentence about preventing an old bug from returning.', 'curated', 'curator', '2026-05-25'),
('agile-smoke-test', 'smoke test', null, 'agile', 'coding', 1, 'A quick check that the most important thing still works before deeper testing begins.', 'A smoke test is the first sniff test after a build or deploy. Open the app, make sure it loads, click the main button, confirm the core flow is not obviously broken. It does not prove everything works; it proves the build is not on fire before you spend time on finer QA.', 'let me run a quick smoke test on the preview: load it, sign in, start one lesson, and make sure nothing obvious is broken.', 'before you spend an hour on careful qa, you want to know the build isn''t already on fire. a smoke test is the quick "does it load, does the main flow work" pass that saves you from testing details on something fundamentally broken.', ARRAY['agile-regression-test','agile-visual-qa','dev-build']::text[], ARRAY['dev-build']::text[], 'agile-regression-test', ARRAY['a rerun guarding that old behavior didn''t break after a change','eyeballing the layout across phone and desktop widths','the conditions that mark a piece of work as finished']::text[], 'let me run a quick ___ on the preview: load it, sign in, start one lesson, and make sure nothing obvious is broken.', 'Use ''smoke test'' in a sentence about a quick first-pass app check.', 'curated', 'curator', '2026-05-25'),
('agile-visual-qa', 'visual QA', null, 'agile', 'coding', 1, 'Looking at the real rendered app across viewports to catch spacing, alignment, wrapping, and polish problems.', 'Visual QA means judging the rendered interface, not just the code. You open the app, capture screenshots, resize to mobile and desktop, check spacing, overlap, text wrapping, empty space, color contrast, and whether the screen feels usable. Automated tests can pass while visual QA still says "this hurts to look at."', 'do some visual QA on mobile first — the gap between the sign-in card and the room card is way too tight.', 'automated tests can all pass while the screen still hurts to look at. visual qa is how you catch the tight spacing, the wrapped text, the overlap that only shows up when you actually open the rendered app and resize it to mobile and desktop.', ARRAY['agile-smoke-test','agile-regression-test','ent-preview-deployment']::text[], ARRAY['ent-preview-deployment']::text[], 'agile-acceptance-criteria', ARRAY['a quick sniff check that the main flow still loads after a build','a test that guards against an old bug sneaking back in','a check that one pure function returns the right value']::text[], 'do some ___ on mobile first — the gap between the sign-in card and the room card is way too tight.', 'Use ''visual QA'' in a sentence about checking the rendered app by sight.', 'curated', 'curator', '2026-05-25'),
('ai-agent-loop', 'agent loop', null, 'ai-engineering', 'coding', 2, 'The repeated cycle where an AI plans, acts, reads the result, and decides the next move.', 'An agent loop is what turns a model from "answerer" into "doer." The model chooses an action, the runtime performs it, the result comes back, and the model decides what to do next. Coding agents live in this loop: inspect files, edit, test, read failure, edit again.', 'we let the agent loop run for ten minutes and it fixed the bug on its own, but it took three tries.', 'when a coding assistant keeps editing, running the test, reading the failure, and editing again without you re-prompting, that''s the agent loop running. once you can name it, you can tell whether it''s making progress or just spinning, and step in at the right moment.', ARRAY['ai-agent','ai-function-calling','cc-tool-use']::text[], ARRAY['ai-agent','ai-function-calling']::text[], 'cc-subagent', ARRAY['a single prompt-and-reply exchange with no follow-up action','the system message that sets an assistant''s persona','fine-tuning a model on examples of good behavior']::text[], 'we let the ___ run for ten minutes and it fixed the bug on its own, but it took three tries.', 'Use ''agent loop'' in a sentence about an AI repeatedly acting and checking results.', 'curated', 'curator', '2026-05-25'),
('ai-evals', 'evals', 'EE-valz', 'ai-engineering', 'coding', 2, 'Tests that measure whether an AI system behaves well enough for the task.', 'Evals means evaluations. An eval is a repeatable test for model behavior: give the system inputs, compare the outputs to expected behavior, and score whether a prompt, model, tool, or agent change made things better or worse. Evals can be simple unit-test-like checks or larger judged datasets.', 'the rewrite read nicer to me, but the evals showed it got worse at citing the right source.', 'a new prompt almost always feels better when you eyeball a couple of replies. evals are how you find out if it actually is. run the same set of inputs before and after a change and you can prove the win instead of trusting the vibe, which is the only way to ship model changes with a straight face.', ARRAY['ai-eval','ai-benchmark','ai-hallucination','aid-evals']::text[], ARRAY['ai-model','ai-prompt']::text[], 'ai-guardrails', ARRAY['rules that block a model''s unsafe output before it ships','the public score a model gets on a shared benchmark','the prompt text you tune to improve responses']::text[], 'the rewrite read nicer to me, but the ___ showed it got worse at citing the right source.', 'Use ''evals'' in a sentence about testing AI behavior with repeatable examples.', 'curated', 'curator', '2026-05-26'),
('ai-guardrails', 'guardrails', null, 'ai-engineering', 'coding', 2, 'Rules, checks, and limits that keep an AI system inside acceptable behavior.', 'Guardrails are the constraints around an AI system. They can block unsafe requests, require citations, validate structured output, stop tool calls that violate policy, or route risky cases to a human. Guardrails do not make a model perfect; they reduce known failure modes around safety, correctness, and control.', 'we added guardrails so the bot can draft the email but a person has to approve it before anything sends.', 'the day you let an agent run real commands, you want something standing between it and a mistake it can''t take back. guardrails are the checks and approval gates that block the dangerous stuff, require a citation, or kick a risky call to a human before it does damage.', ARRAY['ai-evals','ai-hallucination','ai-grounding','aid-guardrails']::text[], ARRAY['ai-agent','ai-evals']::text[], 'ai-grounding', ARRAY['tests that measure whether the model behaves well enough','the documents retrieved to ground an answer','the structured request a model makes to run a tool']::text[], 'we added ___ so the bot can draft the email but a person has to approve it before anything sends.', 'Use ''guardrails'' in a sentence about rules that constrain AI behavior.', 'curated', 'curator', '2026-05-26'),
('ai-model-routing', 'model routing', null, 'ai-engineering', 'coding', 2, 'Choosing which model should handle a request based on cost, speed, risk, or task type.', 'Model routing is the traffic-cop layer for AI calls. Easy requests can go to a cheaper or faster model; hard reasoning, coding, or high-risk requests can go to a stronger one. Routing can be rule-based, learned from evals, or controlled by the user. The goal is not "always use the biggest model"; it is "send each job to the model that fits."', 'our model routing sends autocomplete to the cheap model and only escalates the tricky refactors to the big one.', 'you don''t need your most expensive model answering "what''s the capital of france." model routing sends the cheap quick questions to a small fast model and saves the strong one for the hard reasoning, which is how teams keep both the bill and the latency down.', ARRAY['ai-model','ai-eval','ai-inference']::text[], ARRAY['ai-model','ai-eval']::text[], 'ai-agent-loop', ARRAY['sending one model''s outputs to train a second model','caching repeated answers so you skip the model entirely','splitting a long prompt across several smaller calls']::text[], 'our ___ sends autocomplete to the cheap model and only escalates the tricky refactors to the big one.', 'Use ''model routing'' in a sentence about choosing a model for each request.', 'curated', 'curator', '2026-05-25'),
('ai-structured-output', 'structured output', null, 'ai-engineering', 'coding', 2, 'AI output constrained to a predictable shape, like JSON with required fields, instead of loose prose.', 'Structured output means the model has to answer in a format software can reliably parse: a JSON object, a typed schema, a list with exact keys. It is useful when the answer feeds another system. Free prose is nicer to read; structured output is safer to automate.', 'i switched the call to structured output so the importer gets clean json instead of a paragraph it has to scrape.', 'the moment a model''s answer has to feed another piece of code instead of a human reading it, loose prose breaks everything. ask for structured output and you get back a shape your parser can trust every time, so the next step doesn''t choke on a stray sentence.', ARRAY['ai-prompt','ai-function-calling','ai-eval']::text[], ARRAY['ai-prompt']::text[], 'ai-function-calling', ARRAY['a prompt rewritten in a warmer, more conversational tone','few-shot examples added to steer the model''s style','streaming the response token by token as it generates']::text[], 'i switched the call to ___ so the importer gets clean json instead of a paragraph it has to scrape.', 'Use ''structured output'' in a sentence about making an AI response parseable by code.', 'curated', 'curator', '2026-05-25'),
('ai-tool-call', 'tool call', null, 'ai-engineering', 'coding', 2, 'A structured request from an AI model to run a real tool outside the model.', 'A tool call happens when the model stops producing ordinary text and asks the runtime to run a named tool with specific arguments. The tool might search files, query a database, call an API, send a message, or run a test. The tool result comes back into the conversation, and the model uses that result to decide the next step.', 'the assistant made a tool call to query the database, then used the rows it got back to write the summary.', 'a model on its own can only produce text. the tool call is the moment it actually reaches out and does something real, like reading a file or hitting an api, then folds the result back in. knowing the term lets you tell the model''s thinking apart from the actions that change the outside world.', ARRAY['ai-agent','ai-function-calling','ai-structured-output','aid-tool-call']::text[], ARRAY['ai-agent','ai-function-calling']::text[], 'ai-agent-loop', ARRAY['the model''s plain-text reasoning before it acts','a numeric representation of text used for search','a benchmark run that scores model behavior']::text[], 'the assistant made a ___ to query the database, then used the rows it got back to write the summary.', 'Use ''tool call'' in a sentence about an AI asking software to perform an action.', 'curated', 'curator', '2026-05-26'),
('ai-vector-store', 'vector store', null, 'ai-engineering', 'coding', 2, 'A database-like system that stores embeddings so similar meanings can be searched.', 'A vector store keeps embeddings and lets software search by meaning instead of exact words. In a RAG system, documents are split into chunks, turned into embeddings, saved in a vector store, and retrieved when a question is semantically close to those chunks.', 'we dropped all the handbook chunks into a vector store so the assistant can pull the closest match per question.', 'once you''ve turned your documents into embeddings, they need somewhere to live that can search by meaning fast. the vector store is that shelf. when a RAG answer feels like it''s pulling the right passage, this is where it found it.', ARRAY['ai-embedding','ai-rag','ai-vector-db','aid-vector-database']::text[], ARRAY['ai-embedding']::text[], 'ai-rag', ARRAY['the step that turns text into numbers in the first place','the retrieved chunks pasted into the prompt as context','a cache that stores finished model answers by query']::text[], 'we dropped all the handbook chunks into a ___ so the assistant can pull the closest match per question.', 'Use ''vector store'' in a sentence about searching stored embeddings by meaning.', 'curated', 'curator', '2026-05-26'),
('arch-abstraction', 'abstraction', null, 'architecture', 'coding', 2, 'A simplified layer that hides lower-level details.', 'An abstraction gives callers a simpler idea to work with while hiding the messy details underneath. A payment abstraction might expose chargeCustomer() while hiding Stripe, retries, logging, and database writes. Good abstractions remove irrelevant complexity; bad abstractions hide important behavior.', 'the auth helper is a nice abstraction because nobody calling it has to think about the token refresh flow.', 'every abstraction is a bet that the details underneath don''t matter to you right now. it''s worth being able to name one, because the question "does this layer make the work simpler or just bury the mess somewhere you can''t see it?" shows up in almost every design review.', ARRAY['arch-interface','arch-coupling','arch-service-boundary']::text[], ARRAY['arch-interface']::text[], 'arch-coupling', ARRAY['a queue that holds work until a worker picks it up','a cached copy kept close to speed up reads','a flag that turns a feature on or off at runtime']::text[], 'the auth helper is a nice ___ because nobody calling it has to think about the token refresh flow.', 'Use ''abstraction'' in a sentence about hiding lower-level details behind a simpler layer.', 'curated', 'curator', '2026-05-25'),
('arch-api', 'API', 'A-P-I', 'architecture', 'coding', 1, 'Application Programming Interface: a contract for how software talks to software.', 'API stands for Application Programming Interface. An API is the exposed contract one piece of software offers to another: which actions exist, what input shape they expect, and what output or error they return. APIs can be HTTP endpoints, library functions, SDK methods, or internal service contracts.', 'the mobile app talks to our billing API to pull a customer''s invoices.', 'when someone says "just hit the API," they mean call the contract, not the server or the database sitting behind it. knowing that lets you read integration docs and figure out what you''re allowed to ask for without guessing at internals you''ll never touch.', ARRAY['dev-api','sys-http-request','sys-http-response','arch-interface']::text[], ARRAY['dev-api']::text[], 'arch-interface', ARRAY['the running server process that answers each call','the data store the answers are read from','the screen that renders the returned data for a person']::text[], 'the mobile app talks to our billing ___ to pull a customer''s invoices.', 'Use ''API'' in a sentence about one system calling another.', 'curated', 'curator', '2026-05-25'),
('arch-cohesion', 'cohesion', null, 'architecture', 'coding', 2, 'How tightly a module groups related responsibilities.', 'Cohesion describes whether a module, service, or component is focused on one related job. High cohesion means the pieces inside belong together. Low cohesion means unrelated behavior is bundled together, making the system harder to name, test, and change.', 'the profile service got much better cohesion once we moved the billing logic out of it.', 'cohesion is the flip side of coupling: it asks whether the stuff inside one module actually belongs together. when you can''t name what a service does in one short sentence, low cohesion is usually why, and that''s your cue to move something out.', ARRAY['arch-coupling','arch-service-boundary','arch-abstraction']::text[], ARRAY['arch-service','arch-coupling']::text[], 'arch-service-boundary', ARRAY['how many other modules import this one','how fast a function returns under load','how many lines of code a file contains']::text[], 'the profile service got much better ___ once we moved the billing logic out of it.', 'Use ''cohesion'' in a sentence about related responsibilities belonging together.', 'curated', 'curator', '2026-05-25'),
('arch-consistency', 'consistency', null, 'architecture', 'coding', 2, 'Whether different reads agree about the same data state.', 'Consistency is about whether parts of a system agree on what is true right now. In one architecture, every read immediately sees the latest write. In another, replicas, caches, or downstream services may lag. Stronger consistency is simpler for users but can cost speed or availability.', 'the profile page needed strong consistency so the new name showed up the instant you saved it.', 'consistency is whether two screens agree on what''s true right now. it''s worth knowing because it explains those moments where you save something, refresh, and the old value is still sitting there staring at you.', ARRAY['arch-eventual-consistency','sys-cache-invalidation','data-transaction']::text[], ARRAY['sys-cache-invalidation','data-transaction']::text[], 'arch-eventual-consistency', ARRAY['whether the system keeps answering when a node dies','how long a single request takes to come back','how many requests the system handles per second']::text[], 'the profile page needed strong ___ so the new name showed up the instant you saved it.', 'Use ''consistency'' in a sentence about whether different reads agree.', 'curated', 'curator', '2026-05-25'),
('arch-coupling', 'coupling', null, 'architecture', 'coding', 2, 'How strongly one part of a system depends on another.', 'Coupling measures how tightly pieces are tied together. If changing billing breaks search, those areas are coupled. Some coupling is unavoidable, but high coupling makes systems harder to change because one local edit has distant consequences.', 'the checkout page had way too much coupling to the exact shape of the inventory table.', 'coupling is why a one-line change in billing somehow breaks search. once you can name it, you can explain why a tiny edit turned into a risky one, and start pulling the tangled parts apart.', ARRAY['arch-cohesion','arch-abstraction','arch-service-boundary']::text[], ARRAY['arch-service','arch-interface']::text[], 'arch-cohesion', ARRAY['how often a piece of code gets reused elsewhere','how many layers a call passes through before returning','how much memory a running process holds at once']::text[], 'the checkout page had way too much ___ to the exact shape of the inventory table.', 'Use ''coupling'' in a sentence about one part depending too strongly on another.', 'curated', 'curator', '2026-05-25'),
('arch-dependency-injection', 'dependency injection', null, 'architecture', 'coding', 2, 'Passing dependencies in instead of creating them inside.', 'Dependency injection means a module receives the things it depends on instead of constructing them itself. A component might receive an API client, clock, logger, or database adapter. That makes behavior easier to test and swap because the dependency is explicit.', 'in the test we passed a fake email client in through dependency injection so nothing actually got sent.', 'it sounds fancy but it''s just "hand the code what it needs instead of letting it build its own." that one move is what lets you pass a fake email client in a test, which is why it comes up constantly in conversations about testing and seams.', ARRAY['arch-interface','dev-mock','dev-test-harness']::text[], ARRAY['arch-interface','dev-mock']::text[], 'arch-abstraction', ARRAY['wrapping a call so failures trip a circuit breaker','loading config from environment variables at startup','registering a callback to fire when an event lands']::text[], 'in the test we passed a fake email client in through ___ so nothing actually got sent.', 'Use ''dependency injection'' in a sentence about passing a dependency into code.', 'curated', 'curator', '2026-05-25'),
('arch-event-driven', 'event-driven architecture', null, 'architecture', 'coding', 2, 'A design where components react to emitted events.', 'Event-driven architecture means parts of a system publish facts that happened and other parts react. Instead of checkout directly calling every downstream workflow, it might publish OrderPlaced. Email, analytics, fulfillment, and fraud checks can subscribe to that event.', 'the team went with event-driven architecture once checkout started publishing OrderPlaced and the other services just reacted to it.', 'in an event-driven system, checkout just announces "OrderPlaced" and walks away — email, fulfillment, and fraud checks all react on their own. it''s the reason work can keep happening long after the original request already returned, which is confusing until you have the word for it.', ARRAY['arch-message-bus','arch-microservice','sys-queue']::text[], ARRAY['arch-service','arch-microservice']::text[], 'arch-message-bus', ARRAY['callers invoking each downstream step directly in order','polling a table on a timer to find new rows','batching nightly jobs that run on a fixed schedule']::text[], 'the team went with ___ once checkout started publishing OrderPlaced and the other services just reacted to it.', 'Use ''event-driven architecture'' in a sentence about services reacting to events.', 'curated', 'curator', '2026-05-25'),
('arch-eventual-consistency', 'eventual consistency', null, 'architecture', 'coding', 3, 'A state where replicas may lag but converge later.', 'Eventual consistency means the system may show old data for a short time, but if no new writes happen, every copy should eventually agree. This often appears with caches, replicas, queues, search indexes, analytics pipelines, and event-driven systems.', 'the search index runs on eventual consistency, so a new record shows up there a few seconds after you save it.', 'eventual consistency is the answer to half the "why isn''t it there yet?" moments — the data isn''t broken, it just hasn''t finished propagating. having the term lets you tell a real bug apart from a search index that''s a couple seconds behind.', ARRAY['arch-consistency','arch-event-driven','arch-message-bus','sys-cache-invalidation']::text[], ARRAY['arch-consistency','arch-event-driven']::text[], 'arch-message-bus', ARRAY['every reader seeing the newest write the instant it lands','a write that either fully lands or fully rolls back','a lock that blocks others until one writer finishes']::text[], 'the search index runs on ___, so a new record shows up there a few seconds after you save it.', 'Use ''eventual consistency'' in a sentence about delayed agreement across copies.', 'curated', 'curator', '2026-05-25'),
('arch-idempotency-key', 'idempotency key', null, 'architecture', 'coding', 2, 'A unique key that lets repeated writes be treated as one attempt.', 'An idempotency key lets a server recognize that two write requests are the same intended operation. If checkout retries after a timeout, the key helps the server avoid charging the card twice while still returning a useful response.', 'we attached an idempotency key to the checkout request so retrying it never created a duplicate charge.', 'this is the thing that stops a card from getting charged twice when checkout times out and retries. the moment you''re dealing with payments or webhooks, the idempotency key is how you make a retry safe instead of scary.', ARRAY['sys-idempotent','sys-retry','arch-api']::text[], ARRAY['sys-idempotent','sys-retry']::text[], 'arch-consistency', ARRAY['a token in the header proving who is calling','a version stamp used to detect a stale update','a correlation id that ties logs to one request']::text[], 'we attached an ___ to the checkout request so retrying it never created a duplicate charge.', 'Use ''idempotency key'' in a sentence about safe retrying of writes.', 'curated', 'curator', '2026-05-25'),
('arch-interface', 'interface', null, 'architecture', 'coding', 1, 'A boundary that describes how code or a system can be used.', 'An interface says what another piece of code or software can rely on without exposing every internal detail. It might be a TypeScript interface, a class method list, a public API shape, or a service contract. The point is the same: callers know how to use the thing from the outside.', 'we hid the storage details behind an interface so swapping local files for cloud storage didn''t break any callers.', 'an interface is the promise; the code behind it is how that promise gets kept. once you hear the difference, you can swap one implementation for another without touching every caller, which is the whole reason teams argue about getting the boundary right.', ARRAY['arch-api','arch-abstraction','arch-service-boundary']::text[], ARRAY['arch-api']::text[], 'arch-abstraction', ARRAY['the actual code body that carries out the promised behavior','a stand-in object swapped in during a test','a wrapper that translates one call shape into another']::text[], 'we hid the storage details behind an ___ so swapping local files for cloud storage didn''t break any callers.', 'Use ''interface'' in a sentence about a boundary callers can rely on.', 'curated', 'curator', '2026-05-25'),
('arch-message-bus', 'message bus', null, 'architecture', 'coding', 2, 'Shared infrastructure for publishing and consuming events or messages.', 'A message bus carries events or messages between producers and consumers. Producers publish a message; consumers subscribe, process, and sometimes retry later. It helps services communicate without every service directly calling every other service.', 'the message bus carried the password-reset event over to both the email and audit services.', 'the message bus is the plumbing that carries events from whoever publishes them to whoever''s listening. knowing it''s there explains where async work actually goes and why a failed message can quietly get retried minutes later.', ARRAY['arch-event-driven','sys-queue','arch-microservice']::text[], ARRAY['arch-event-driven']::text[], 'arch-eventual-consistency', ARRAY['a connection pool that reuses open database links','a content delivery network caching files near users','a rate limiter that caps requests per client']::text[], 'the ___ carried the password-reset event over to both the email and audit services.', 'Use ''message bus'' in a sentence about publishing and consuming events.', 'curated', 'curator', '2026-05-25'),
('arch-microservice', 'microservice', null, 'architecture', 'coding', 2, 'A small independently deployed service with a narrow responsibility.', 'A microservice is a service split out so it can be built, deployed, scaled, and owned more independently. Microservices can help teams move separately, but they also add network calls, monitoring, versioning, and distributed-system failure modes.', 'we pulled search out into its own microservice so that team could deploy and scale it on its own.', 'splitting something into a microservice buys you independent deploys and scaling, and charges you network calls, monitoring, and a pile of new failure modes. hearing the word should make you ask whether the independence is worth the coordination cost.', ARRAY['arch-service','arch-monolith','arch-message-bus','arch-consistency']::text[], ARRAY['arch-service','arch-api']::text[], 'arch-event-driven', ARRAY['a scheduled cron job that runs once a night','a sidecar process attached to a main container','a feature branch holding work split off from the trunk']::text[], 'we pulled search out into its own ___ so that team could deploy and scale it on its own.', 'Use ''microservice'' in a sentence about a small independently deployed service.', 'curated', 'curator', '2026-05-25'),
('arch-monolith', 'monolith', null, 'architecture', 'coding', 1, 'An application where many capabilities ship as one unit.', 'A monolith is one application that contains many parts: login, billing, admin, search, reporting, and more. It often has one codebase, one build, and one deploy. Monoliths can be simple and productive; the tradeoff is that one change can require shipping the whole application.', 'we kept the whole thing as a monolith until we actually understood where the service boundaries were.', '"monolith" gets thrown around like an insult, but it''s just a tradeoff: one app you can hold in your head versus many you can deploy separately. knowing that keeps you from splitting things up before you actually need to.', ARRAY['arch-microservice','arch-service','arch-service-boundary']::text[], ARRAY['arch-service']::text[], 'arch-microservice', ARRAY['a container image bundling one app for deployment','a shared library imported by many separate apps','a gateway that routes calls to the right backend']::text[], 'we kept the whole thing as a ___ until we actually understood where the service boundaries were.', 'Use ''monolith'' in a sentence about one application that ships many capabilities together.', 'curated', 'curator', '2026-05-25'),
('arch-service', 'service', null, 'architecture', 'coding', 1, 'A deployable unit that owns a capability or business area.', 'A service is a running piece of software that owns a job: auth, billing, search, notifications, image processing, or recommendations. A service usually has its own code, runtime, API, logs, and operational responsibilities.', 'the billing service owns invoice creation and all the payment retries.', 'when something breaks in a backend, the first useful question is "which service owns this?" — the code, the data, and the failure. having the word lets you locate responsibility instead of staring at the whole system at once.', ARRAY['arch-api','arch-microservice','arch-service-boundary']::text[], ARRAY['arch-api']::text[], 'arch-service-boundary', ARRAY['a single helper function exported from a shared package','a background worker that only drains a job queue','a load balancer that spreads traffic across machines']::text[], 'the billing ___ owns invoice creation and all the payment retries.', 'Use ''service'' in a sentence about a running software unit that owns a capability.', 'curated', 'curator', '2026-05-25'),
('arch-service-boundary', 'service boundary', null, 'architecture', 'coding', 2, 'The line that decides what a service owns and exposes.', 'A service boundary defines which data, behavior, and decisions belong inside a service and what other services may ask from it. Good boundaries keep ownership clear. Bad boundaries create duplicate logic, hidden coupling, and arguments about which team owns a bug.', 'we moved invoice status to live behind the billing service boundary so it was clearly theirs to own.', 'a service boundary is the line that settles which team owns a bug. draw it well and ownership is obvious; draw it badly and you get duplicate logic and arguments about whose problem it is, which is why so much architecture talk is really about where this line goes.', ARRAY['arch-service','arch-microservice','arch-coupling','arch-cohesion']::text[], ARRAY['arch-service','arch-coupling','arch-cohesion']::text[], 'arch-event-driven', ARRAY['the rolling deploy that replaces instances one at a time','the schema describing the shape of a stored row','the retry policy a caller uses when a call fails']::text[], 'we moved invoice status to live behind the billing ___ so it was clearly theirs to own.', 'Use ''service boundary'' in a sentence about what a service owns.', 'curated', 'curator', '2026-05-25'),
('cc-compaction', 'compaction', null, 'claude-code', 'coding', 2, 'The moment a long session gets summarized so the agent can keep going with less context.', 'Compaction happens when a conversation gets too large to carry in full. The system writes a summary of what matters, drops bulky older detail, and continues from that compressed state. A good compaction preserves branch names, file paths, commands, failures, and the user''s latest direction. A bad one loses the plot.', 'after compaction, reread the handoff and double-check the branch before you touch any files.', 'if an agent suddenly knows the summary but not the whole path, compaction is usually why. knowing the word lets you tell the difference between normal context management and the agent actually losing the plot — so you reread the handoff instead of assuming it''s broken.', ARRAY['cc-context-window','cc-handoff','cc-transcript']::text[], ARRAY['cc-context-window']::text[], 'cc-handoff', ARRAY['the full written record of the session up to this point','the limits that keep an agent inside its safe lane','minifying javascript so it ships in a smaller bundle']::text[], 'after ___, reread the handoff and double-check the branch before you touch any files.', 'Use ''compaction'' in a sentence about a long agent session being summarized.', 'curated', 'curator', '2026-05-25'),
('cc-guardrails', 'guardrails', null, 'claude-code', 'coding', 2, 'Rules and checks that keep an agent inside the safe lane while it works.', 'Guardrails are the constraints around an agent session: do not read secrets, do not deploy live, use small PRs, run pre-deploy before pushing, preserve user changes. Some guardrails are instructions, some are automated checks, and some are review habits. They do not remove judgment; they make the risky edges visible.', 'keep the same guardrails we use on the other repos: small branch, no live deploy, real validation before merge.', 'fast agent work only stays reversible if there are limits around it — no reading secrets, no live deploys, small branches, real validation before pushing. naming those as guardrails makes them feel like part of the workflow instead of a mood you''re in that day.', ARRAY['cc-permissions','cc-plan-mode','agile-acceptance-criteria']::text[], ARRAY['cc-claude-code']::text[], 'cc-handoff', ARRAY['the short note handed to the next session about what''s left','the summary written when the conversation runs out of room','the written log of every prompt, reply, and command run']::text[], 'keep the same ___ we use on the other repos: small branch, no live deploy, real validation before merge.', 'Use ''guardrails'' in a sentence about rules that keep agent work safe.', 'curated', 'curator', '2026-05-25'),
('cc-handoff', 'handoff', null, 'claude-code', 'coding', 2, 'A concise state transfer that tells the next agent or session what changed, what passed, and what remains.', 'A handoff is the note you leave when work moves from one session, agent, or person to another. A good handoff names the branch, changed files, validation commands, open risks, and the next safe move. It prevents the next agent from re-discovering the whole repo like it just woke up in a storage closet.', 'before you close out, write a handoff so the next session knows the branch, what passed, and what''s still open.', 'long agent sessions die when the next session wakes up knowing nothing. when you can ask for a handoff by name, you get continuity instead of an agent re-reading the whole repo to figure out where it left off.', ARRAY['cc-transcript','cc-compaction','git-branch']::text[], ARRAY['cc-transcript']::text[], 'cc-compaction', ARRAY['the full session log of every prompt and tool result','the moment a long session gets summarized to free up room','the rules that keep an agent from reading secrets or deploying live']::text[], 'before you close out, write a ___ so the next session knows the branch, what passed, and what''s still open.', 'Use ''handoff'' in a sentence about passing work to the next agent or session.', 'curated', 'curator', '2026-05-25'),
('cc-transcript', 'transcript', null, 'claude-code', 'coding', 1, 'The written record of a session: prompts, replies, tool results, errors, and decisions.', 'A transcript is the session log. In agent work it is more than chat history; it includes commands, file reads, browser checks, screenshots, failures, and recovery steps. Reading the transcript is how you reconstruct why a branch looks the way it does.', 'scroll back through the transcript — the error first showed up right after the migration command ran.', 'when you''re trying to figure out why a branch looks the way it does, the transcript is your reconstruction. it''s not just chat history — it''s every command, file read, screenshot, and failure, which is what lets you retrace a long session instead of guessing.', ARRAY['cc-handoff','cc-tool-use','agile-visual-qa']::text[], ARRAY['cc-claude-code']::text[], 'cc-handoff', ARRAY['the short note telling the next session what changed and what''s left','the summary made when a session gets too long to carry','the runnable bundle a build step spits out at the end']::text[], 'scroll back through the ___ — the error first showed up right after the migration command ran.', 'Use ''transcript'' in a sentence about learning from an agent session log.', 'curated', 'curator', '2026-05-25'),
('cloud-alert', 'alert', null, 'cloud-devops', 'coding', 1, 'A notification that a threshold or failure condition happened.', 'An alert is a notification sent when a system crosses a threshold or detects a failure condition. Good alerts point to something actionable. Bad alerts create noise and teach people to ignore them.', 'the alert went off when the checkout error rate stayed above five percent for ten straight minutes.', 'the difference between a dashboard someone might glance at and a signal that actually wakes a person up is an alert. tuning them matters: too many noisy ones and people start ignoring the one that''s real.', ARRAY['cloud-metric','cloud-observability','qa-mttr','qa-postmortem']::text[], ARRAY['cloud-metric','cloud-observability']::text[], 'qa-postmortem', ARRAY['a number tracked over time on a dashboard','a recorded event message written while running','a threshold value a measurement is compared against']::text[], 'the ___ went off when the checkout error rate stayed above five percent for ten straight minutes.', 'Use ''alert'' in a sentence about a notification triggered by a failure signal.', 'curated', 'curator', '2026-05-26'),
('cloud-autoscaling', 'autoscaling', null, 'cloud-devops', 'coding', 2, 'Adding or removing compute capacity based on demand.', 'Autoscaling changes the number of running instances, containers, or workers when demand changes. It usually reacts to metrics such as CPU, memory, queue depth, or request volume. It helps absorb spikes without permanently paying for peak capacity.', 'when the queue started backing up during the launch, autoscaling spun up extra workers to catch up.', 'this is how a system survives a traffic spike without you paying for peak capacity 24/7. it also explains the lag you sometimes feel under sudden load: new instances take a moment to spin up before they can help.', ARRAY['cloud-metric','cloud-load-balancer','cloud-kubernetes','net-throughput']::text[], ARRAY['cloud-metric','cloud-container']::text[], 'cloud-metric', ARRAY['a router that spreads traffic across existing servers','a number tracked over time, like cpu or queue depth','running code on demand without managing servers']::text[], 'when the queue started backing up during the launch, ___ spun up extra workers to catch up.', 'Use ''autoscaling'' in a sentence about adding or removing runtime capacity.', 'curated', 'curator', '2026-05-26'),
('cloud-cache', 'cache', null, 'cloud-devops', 'coding', 1, 'Stored results reused to avoid doing the same work again.', 'A cache keeps a copy of something expensive to compute or fetch so the next request can be faster. Caches can live in the browser, CDN, server memory, database layer, or a service such as Redis. The hard part is invalidation: knowing when the cached answer is stale.', 'the dashboard felt instant because we put a cache in front of the charts instead of recomputing them on every refresh.', 'a cache is behind a lot of "why is this so fast" wins and a lot of "why is this showing old data" bugs. the word lets you ask the right question: are we reading the real value, or a saved copy that''s gone stale?', ARRAY['sys-cache-invalidation','cloud-cdn','arch-eventual-consistency','net-latency']::text[], ARRAY['sys-http-request']::text[], 'sys-cache-invalidation', ARRAY['the original source the saved copy was taken from','a network of edge locations serving static assets','the act of clearing a saved copy when it goes stale']::text[], 'the dashboard felt instant because we put a ___ in front of the charts instead of recomputing them on every refresh.', 'Use ''cache'' in a sentence about reusing stored results for speed.', 'curated', 'curator', '2026-05-26'),
('cloud-cdn', 'CDN', 'C-D-N', 'cloud-devops', 'coding', 1, 'Content delivery network: a network that caches assets near users.', 'CDN stands for content delivery network. A CDN stores copies of static assets such as images, JavaScript, CSS, downloads, and sometimes cached responses in many geographic locations. Users fetch from a nearby edge location instead of the origin server every time.', 'the screenshots on our landing page got way snappier once we served them through a cdn.', 'when images and scripts suddenly load faster after a launch, a cdn is usually why. it also explains a confusing bug: you updated a file but old visitors still see the old version, because a cached copy is sitting at an edge location near them.', ARRAY['cloud-cache','cloud-edge','net-latency','net-bandwidth']::text[], ARRAY['net-latency','sys-http-request']::text[], 'cloud-cache', ARRAY['the single origin server that holds the real files','a stored copy of expensive work reused for speed','code running on demand without a managed server']::text[], 'the screenshots on our landing page got way snappier once we served them through a ___.', 'Use ''CDN'' in a sentence about serving cached assets near users.', 'curated', 'curator', '2026-05-26'),
('cloud-container', 'container', null, 'cloud-devops', 'coding', 2, 'A packaged runtime with app code and its dependencies isolated together.', 'A container bundles an application with the files, libraries, and runtime it needs so it can run consistently on different machines. Containers are usually built from images and run as isolated processes with controlled access to the host.', 'we run the api in a container so the same build works on my laptop and in the cloud.', 'when someone says "just run it in a container" they mean the app ships with its whole runtime, so it behaves the same on your laptop and on the server. that''s the answer to half the "but it ran fine locally" surprises.', ARRAY['cloud-image','cloud-kubernetes','os-process','cloud-deploy']::text[], ARRAY['os-process','flow-build']::text[], 'cloud-image', ARRAY['the immutable template a running instance starts from','a system that coordinates many running instances','a virtual machine emulating full hardware']::text[], 'we run the api in a ___ so the same build works on my laptop and in the cloud.', 'Use ''container'' in a sentence about packaging code with its runtime dependencies.', 'curated', 'curator', '2026-05-26'),
('cloud-deploy', 'deploy', null, 'cloud-devops', 'coding', 1, 'Putting a version of software into an environment where it can run.', 'A deploy takes code that has been built and puts it somewhere runnable: preview, staging, production, an edge function, a server, or a container service. A deploy is not just saving files; it changes which version a real runtime can execute.', 'i pushed the fix an hour ago, but it won''t show up until we deploy to production.', 'writing code and getting that code onto a live runtime are two different events, and the gap between them is where a lot of confusion hides. once you can say "it''s committed but not deployed yet," you stop wondering why your change isn''t showing up on the real site.', ARRAY['flow-build','flow-artifact','cloud-environment','flow-ci']::text[], ARRAY['flow-build','flow-commit']::text[], 'cloud-environment', ARRAY['merging a branch into the main line of code','building source code into a runnable artifact','rolling a live version back to a previous one']::text[], 'i pushed the fix an hour ago, but it won''t show up until we ___ to production.', 'Use ''deploy'' in a sentence about putting a version of software into a runtime.', 'curated', 'curator', '2026-05-26'),
('cloud-edge', 'edge runtime', null, 'cloud-devops', 'coding', 2, 'Code running geographically closer to users.', 'An edge runtime runs code at locations closer to the user instead of sending every request to one far-away region. Edge code can reduce latency for lightweight work, but it often has stricter runtime limits than a full server environment.', 'we pushed the redirect logic to the edge runtime so users near asia aren''t waiting on a server in virginia.', 'some code paths are fast because they run near the user instead of in one far-off region, but that speed comes with tighter limits. knowing this helps you understand why a redirect can live at the edge while your heavy database work can''t.', ARRAY['cloud-cdn','net-latency','cloud-serverless','sys-http-request']::text[], ARRAY['net-latency','cloud-serverless']::text[], 'cloud-cdn', ARRAY['a network that caches static assets near users','a single backend region handling every request','the delay a request takes traveling over the network']::text[], 'we pushed the redirect logic to the ___ so users near asia aren''t waiting on a server in virginia.', 'Use ''edge runtime'' in a sentence about running code closer to users.', 'curated', 'curator', '2026-05-26'),
('cloud-environment', 'environment', null, 'cloud-devops', 'coding', 1, 'A separate runtime such as local, preview, staging, or production.', 'An environment is one place where the app runs with its own URL, configuration, database, secrets, and safety expectations. Local is for development, preview is for review, staging is production-like testing, and production is what real users see.', 'the bug only shows up in the staging environment because that''s the only place pointed at the real payment provider.', '"it works on my machine" almost always means it works in one environment and not another. knowing the word lets you ask the useful question: which environment, with which config and which data, did it break in?', ARRAY['cloud-deploy','os-environment-variable','sec-secret','flow-localhost']::text[], ARRAY['cloud-deploy','os-environment-variable']::text[], 'cloud-serverless', ARRAY['a deploy that puts a version onto a runtime','an environment variable holding one config value','a secret credential injected at runtime']::text[], 'the bug only shows up in the staging ___ because that''s the only place pointed at the real payment provider.', 'Use ''environment'' in a sentence about local, preview, staging, or production runtimes.', 'curated', 'curator', '2026-05-26'),
('cloud-image', 'image', null, 'cloud-devops', 'coding', 2, 'The template used to start a container.', 'A container image is an immutable template containing the application, runtime, libraries, and startup instructions. Running containers are created from images. If the image changes, the next deploy starts a new container from the new template.', 'the deploy builds a fresh image first, then starts new containers from it.', 'in container talk the template and the thing actually running have different names, and mixing them up makes deploy conversations confusing. once you hear "build a new image, then start fresh containers from it," the workflow clicks.', ARRAY['cloud-container','flow-artifact','cloud-deploy']::text[], ARRAY['cloud-container']::text[], 'cloud-kubernetes', ARRAY['the running, isolated process started from the template','the build step that produces a runnable artifact','a registry that stores and serves templates']::text[], 'the deploy builds a fresh ___ first, then starts new containers from it.', 'Use ''image'' in a sentence about the template used to start a container.', 'curated', 'curator', '2026-05-26'),
('cloud-kubernetes', 'Kubernetes', null, 'cloud-devops', 'coding', 3, 'A system for running and coordinating containers across machines.', 'Kubernetes manages containers across a cluster of machines. It schedules work, restarts failed containers, rolls out new versions, exposes services, and keeps desired state aligned with actual state. It is powerful, but it adds operational complexity.', 'when that pod crashed overnight, kubernetes restarted it and kept the api up without anyone paging in.', 'when a team says they''re "on kubernetes," they''re telling you their container operations are a whole discipline, not a one-click upload. that explains why something as simple as a restart can involve schedulers, clusters, and desired state.', ARRAY['cloud-container','cloud-image','cloud-load-balancer','cloud-autoscaling']::text[], ARRAY['cloud-container','cloud-image']::text[], 'cloud-autoscaling', ARRAY['the template a single container starts from','a load balancer that spreads incoming traffic','a model that runs one application in isolation']::text[], 'when that pod crashed overnight, ___ restarted it and kept the api up without anyone paging in.', 'Use ''Kubernetes'' in a sentence about coordinating containers across machines.', 'curated', 'curator', '2026-05-26'),
('cloud-load-balancer', 'load balancer', null, 'cloud-devops', 'coding', 2, 'A traffic router that spreads requests across healthy servers.', 'A load balancer receives incoming traffic and sends each request to one of several healthy backends. It can use health checks, routing rules, and capacity signals so one server is not overloaded and failed servers stop receiving traffic.', 'once that instance started returning errors, the load balancer quietly stopped sending it traffic.', 'this is how one url can actually sit in front of a whole fleet of servers. it explains why a single instance dying usually doesn''t take the site down: the balancer just stops routing traffic to the sick one.', ARRAY['cloud-autoscaling','cloud-kubernetes','net-router','cloud-observability']::text[], ARRAY['net-router','cloud-environment']::text[], 'cloud-autoscaling', ARRAY['a service that adds or removes servers by demand','a coordinator that schedules containers on a cluster','a health check that pings a backend for a response']::text[], 'once that instance started returning errors, the ___ quietly stopped sending it traffic.', 'Use ''load balancer'' in a sentence about spreading traffic across healthy servers.', 'curated', 'curator', '2026-05-26'),
('cloud-log', 'log', null, 'cloud-devops', 'coding', 1, 'A recorded event or message emitted by software.', 'A log is a timestamped record that software writes while running: request received, job started, payment failed, retry scheduled, user authenticated. Logs are useful when they include enough context to explain what happened without exposing secrets.', 'the error log showed the webhook came in missing a required field, which is why it kept failing.', 'when something breaks, the log is usually the first place that tells you what the system actually did, instead of what you assumed it did. learning to read it means you stop guessing from the ui and start reading the receipts.', ARRAY['cloud-observability','cloud-alert','qa-root-cause','sys-http-request']::text[], ARRAY['cloud-observability']::text[], 'cloud-metric', ARRAY['a number tracked over time to show trends','an alert sent when a failure condition is met','the request path traced across multiple services']::text[], 'the error ___ showed the webhook came in missing a required field, which is why it kept failing.', 'Use ''log'' in a sentence about a recorded event from running software.', 'curated', 'curator', '2026-05-26'),
('cloud-metric', 'metric', null, 'cloud-devops', 'coding', 1, 'A numeric measurement tracked over time.', 'A metric is a number collected repeatedly so teams can see trends, thresholds, and changes. Common metrics include request rate, error rate, latency, CPU, memory, queue depth, and sign-up conversions.', 'our latency metric doubled right after the deploy, so we knew exactly where to look.', 'one slow page load is an anecdote; a metric is the same number tracked over time so you can tell a real trend from a fluke. it''s how you say "latency actually doubled after the deploy" instead of "it feels slower lately."', ARRAY['cloud-observability','cloud-alert','net-latency','prod-kpi']::text[], ARRAY['cloud-observability']::text[], 'cloud-alert', ARRAY['a single timestamped event message from software','an alert that fires when a number crosses a line','a saved copy of expensive work reused for speed']::text[], 'our latency ___ doubled right after the deploy, so we knew exactly where to look.', 'Use ''metric'' in a sentence about a number tracked over time.', 'curated', 'curator', '2026-05-26'),
('cloud-observability', 'observability', null, 'cloud-devops', 'coding', 2, 'The ability to understand system health from logs, metrics, and traces.', 'Observability is how teams understand what a system is doing from the outside. Logs show events, metrics show numbers over time, traces show request paths, and dashboards or alerts help operators see failures before users report them.', 'diagnosing the outage went way faster after we''d added real observability around the checkout flow.', 'this is the "can we actually see what happened?" capability, and it''s why teams add logs and metrics before things are obviously broken. when an incident hits, the difference between a five-minute diagnosis and a two-hour one is usually whether you set this up first.', ARRAY['cloud-log','cloud-metric','cloud-alert','qa-mttr']::text[], ARRAY['cloud-log','cloud-metric']::text[], 'cloud-alert', ARRAY['a single recorded event message from running software','a notification fired when a threshold is crossed','the trace showing one request''s path through services']::text[], 'diagnosing the outage went way faster after we''d added real ___ around the checkout flow.', 'Use ''observability'' in a sentence about understanding system behavior from evidence.', 'curated', 'curator', '2026-05-26'),
('cloud-serverless', 'serverless', null, 'cloud-devops', 'coding', 2, 'Running code on demand without managing long-lived servers directly.', 'Serverless does not mean there are no servers. It means the cloud provider manages the servers and starts your code when events or requests arrive. Functions, edge handlers, and scheduled jobs often use this model.', 'we moved the image-resize job to a serverless function since it only needs to run when someone uploads a photo.', 'the name is a little misleading: there are still servers, you just don''t manage them. it pays off when a job only needs to run on an event, like resizing an image after an upload, instead of paying for an always-on box that mostly sits idle.', ARRAY['cloud-edge','cloud-deploy','sys-http-request','cloud-environment']::text[], ARRAY['cloud-deploy','sys-http-request']::text[], 'cloud-edge', ARRAY['code running geographically close to the user','a long-lived server the team provisions and patches','a container coordinator scheduling work across machines']::text[], 'we moved the image-resize job to a ___ function since it only needs to run when someone uploads a photo.', 'Use ''serverless'' in a sentence about code that runs on demand without managing a server.', 'curated', 'curator', '2026-05-26'),
('hw-arm', 'ARM', 'arm', 'computing', 'coding', 1, 'A processor architecture used in phones, tablets, servers, and modern Macs.', 'ARM is an instruction-set architecture. Apple silicon Macs, iPhones, many Android phones, and some cloud servers use ARM-based chips. ARM chips are often designed for strong performance per watt, which is why they show up in mobile and battery-sensitive devices.', 'the dependency only shipped an x86 binary, so we needed an ARM build for the new macs.', '''works on my intel machine'' stops being enough once arm chips are in the room, which they are: every recent mac, iphone, and a lot of cloud servers. it''s the word that explains why a docker image or native module suddenly won''t run.', ARRAY['hw-instruction-set','hw-soc','dev-build-artifact','dev-node-modules']::text[], ARRAY['hw-instruction-set']::text[], 'hw-soc', ARRAY['the list of operations a processor architecture supports','a chip fusing processor, graphics, and memory into one piece','the firmware that starts hardware before the os loads']::text[], 'the dependency only shipped an x86 binary, so we needed an ___ build for the new macs.', 'Use ''ARM'' in a sentence about processor architecture.', 'curated', 'curator', '2026-05-25'),
('hw-bios-uefi', 'BIOS/UEFI', 'BYE-oss / U-E-F-I', 'computing', 'coding', 2, 'Startup firmware that initializes hardware before the OS loads.', 'BIOS and UEFI are firmware interfaces involved at boot. They initialize hardware, expose settings, choose boot devices, and hand control to the OS loader. UEFI is the modern replacement for legacy BIOS, but people often say BIOS casually for the firmware setup screen.', 'i went into BIOS/UEFI and changed the boot order so the installer drive came first.', 'everything that happens before the operating system even loads lives in bios/uefi: boot order, secure boot, the setup screen you tap a key to reach. it''s the right layer to blame when a machine won''t start from the drive you want.', ARRAY['hw-firmware','hw-motherboard','os-kernel','os-filesystem']::text[], ARRAY['hw-firmware']::text[], 'os-kernel', ARRAY['low-level software baked into an ongoing device like a router','the core os layer scheduling processes and memory','the connector standard that high-speed cards plug into']::text[], 'i went into ___ and changed the boot order so the installer drive came first.', 'Use ''BIOS/UEFI'' in a sentence about boot firmware.', 'curated', 'curator', '2026-05-25'),
('hw-bus', 'bus', null, 'computing', 'coding', 2, 'A communication pathway that lets hardware components move data between each other.', 'A hardware bus is how parts of a computer talk: CPU to memory, storage to chipset, expansion cards to motherboard. Different buses have different speed, latency, and physical constraints. PCIe is a common modern bus for high-speed components.', 'the card was fast, but the data had to crawl across a slower bus to reach the cpu.', 'a blazing-fast chip can still stall if data can''t reach it quickly enough, and the bus is that pathway. knowing the word is how you spot a bottleneck that lives in the plumbing rather than the processor.', ARRAY['hw-pcie','hw-motherboard','hw-cpu','hw-gpu']::text[], ARRAY['hw-cpu','hw-motherboard']::text[], 'hw-pcie', ARRAY['the high-speed connector standard expansion cards plug into','the board that physically holds every component','the channel a program uses to ask the kernel for work']::text[], 'the card was fast, but the data had to crawl across a slower ___ to reach the cpu.', 'Use ''bus'' in a sentence about components moving data.', 'curated', 'curator', '2026-05-25'),
('hw-cache', 'CPU cache', null, 'computing', 'coding', 2, 'Small fast memory near the processor used to avoid slower RAM reads.', 'CPU cache stores recently used data close to the processor. It is much smaller than RAM but much faster. Code that repeatedly touches nearby data can be faster because the CPU can reuse cached values instead of waiting on main memory.', 'the loop sped up once the hot array fit entirely in CPU cache.', 'ever wonder why looping over data in the right order runs noticeably faster? that''s the cpu cache rewarding you for reusing nearby values instead of making the chip wait on slower main memory every time.', ARRAY['hw-cpu','hw-ram','sys-cache','math-complexity']::text[], ARRAY['hw-cpu','hw-ram']::text[], 'sys-cache-invalidation', ARRAY['the larger temporary memory holding a program''s working data','persistent flash storage that survives a power-off','a saved copy of an already-computed web response']::text[], 'the loop sped up once the hot array fit entirely in ___.', 'Use ''CPU cache'' in a sentence about fast nearby processor memory.', 'curated', 'curator', '2026-05-25'),
('hw-clock-speed', 'clock speed', null, 'computing', 'coding', 1, 'How many processor cycles a chip can attempt per second.', 'Clock speed is usually shown in GHz. It is one ingredient in performance, but not the whole story: architecture, number of cores, cache, memory bandwidth, thermal limits, and the workload shape all matter too.', 'this older chip has a higher clock speed but loses on anything that can spread across many cores.', 'the next time a spec sheet brags about ghz, you''ll know it''s only one ingredient. clock speed helps a single slow task finish quicker, but it won''t save work that''s really limited by core count, cache, or memory.', ARRAY['hw-cpu','hw-core','hw-cache','os-thread']::text[], ARRAY['hw-cpu']::text[], 'hw-cache', ARRAY['the count of independent execution units on the chip','the amount of fast memory sitting beside the processor','the width of the channel moving data into the processor']::text[], 'this older chip has a higher ___ but loses on anything that can spread across many cores.', 'Use ''clock speed'' in a sentence about processor cycles.', 'curated', 'curator', '2026-05-25'),
('hw-core', 'core', null, 'computing', 'coding', 1, 'One independent execution unit inside a CPU or GPU.', 'A core is a processing unit that can work on instructions independently. More CPU cores let a computer run more work at the same time, assuming the software can split the work safely. A GPU has many smaller cores optimized for parallel math.', 'i pinned the build to one CPU core so the rest of the laptop stayed usable.', 'when someone asks why your 8-core machine ran the tests way faster in parallel, this is the answer. it''s the word for how many separate things a chip can truly do at the same moment, not just feel like it''s doing.', ARRAY['hw-cpu','hw-gpu','os-thread','hw-clock-speed']::text[], ARRAY['hw-cpu']::text[], 'os-thread', ARRAY['how many cycles per second the processor attempts','the entire processor package sold as one purchased unit','the wide pathway that carries data toward the processor']::text[], 'i pinned the build to one CPU ___ so the rest of the laptop stayed usable.', 'Use ''core'' in a sentence about a processor running work in parallel.', 'curated', 'curator', '2026-05-25'),
('hw-cpu', 'CPU', 'C-P-U', 'computing', 'coding', 1, 'The main processor that executes general-purpose instructions.', 'CPU stands for central processing unit. It runs the ordinary instruction stream of a program: branching, arithmetic, function calls, OS work, and coordination with memory. A machine can have one CPU package with several cores inside it.', 'my CPU was pinned at 100% the whole time the test suite ran, so the laptop got hot.', 'when your laptop fan roars during a compile and the browser still scrolls fine, you''re watching the cpu get pegged. knowing this word is how you tell ''the work is just heavy computation'' apart from a storage, graphics, or network bottleneck.', ARRAY['hw-core','hw-clock-speed','hw-cache','os-process']::text[], ARRAY['code-algorithm']::text[], 'hw-gpu', ARRAY['a processor built for many parallel math operations at once','fast temporary memory that running programs work out of','one independent execution unit sitting inside the chip']::text[], 'my ___ was pinned at 100% the whole time the test suite ran, so the laptop got hot.', 'Use ''CPU'' in a sentence about general-purpose computer work.', 'curated', 'curator', '2026-05-25'),
('hw-firmware', 'firmware', null, 'computing', 'coding', 2, 'Low-level software stored on a device that controls the hardware itself.', 'Firmware lives closer to hardware than normal app software. It can initialize a motherboard, run a keyboard controller, manage a router, or update a device. Firmware updates can fix bugs or security issues, but bad firmware can make hardware fail to boot.', 'the wifi kept dropping until i flashed newer firmware onto the router.', 'when a router or keyboard ''needs an update'' even though it isn''t really a computer, that''s firmware, the software baked into the device. it''s why hardware can be patched, and occasionally bricked.', ARRAY['hw-bios-uefi','hw-motherboard','os-kernel','sec-vulnerability']::text[], ARRAY['hw-motherboard']::text[], 'hw-bios-uefi', ARRAY['the startup interface that hands control to the operating system','the core os layer that manages running programs','the circuit board wiring every component together']::text[], 'the wifi kept dropping until i flashed newer ___ onto the router.', 'Use ''firmware'' in a sentence about software stored on hardware devices.', 'curated', 'curator', '2026-05-25'),
('hw-gpu', 'GPU', 'G-P-U', 'computing', 'coding', 1, 'A processor designed to do many parallel math operations at once.', 'GPU stands for graphics processing unit. It was built for graphics workloads, but the same parallel shape is useful for machine learning, image processing, simulations, and model inference. GPUs are fast when the same kind of math can run across many pieces of data at the same time.', 'we couldn''t fit the model on one GPU, so we had to split it across two cards.', 'the reason training an ai model means renting expensive cloud chips instead of just using a faster laptop is the gpu. once you know the word, the talk about vram limits, heat, and capacity waitlists actually makes sense.', ARRAY['hw-cpu','hw-core','hw-ram','ai-inference']::text[], ARRAY['hw-cpu']::text[], 'hw-soc', ARRAY['the all-purpose processor that runs ordinary program instructions','a single chip fusing processor, graphics, and memory together','small fast memory placed right beside the processor']::text[], 'we couldn''t fit the model on one ___, so we had to split it across two cards.', 'Use ''GPU'' in a sentence about parallel compute or AI workloads.', 'curated', 'curator', '2026-05-25'),
('hw-instruction-set', 'instruction set', null, 'computing', 'coding', 2, 'The operations a processor architecture knows how to execute.', 'An instruction set is the vocabulary of machine instructions a CPU understands: load, store, add, branch, compare, vector operations, and more. Software has to be compiled for the instruction set it will run on. ARM and x86 are major instruction-set families.', 'the downloaded binary wouldn''t launch because it was compiled for a different instruction set.', 'the reason the same source code needs separate builds for an apple silicon mac, an intel mac, and a phone is the instruction set. it''s the word for the exact operations a given chip family knows how to run.', ARRAY['hw-cpu','hw-arm','dev-build-artifact','os-kernel']::text[], ARRAY['hw-cpu']::text[], 'hw-arm', ARRAY['the processor architecture used in phones and modern macs','the operations bundled together onto one combined chip','the bus standard that connects expansion hardware']::text[], 'the downloaded binary wouldn''t launch because it was compiled for a different ___.', 'Use ''instruction set'' in a sentence about what a processor can run.', 'curated', 'curator', '2026-05-25'),
('hw-motherboard', 'motherboard', null, 'computing', 'coding', 1, 'The main circuit board that connects the computer components.', 'The motherboard holds or connects the CPU, RAM slots, storage connectors, PCIe slots, firmware chip, power delivery, and ports. It defines what components fit together and which features the system can support.', 'the motherboard only supports that ram type, so the faster sticks wouldn''t have worked anyway.', 'before you buy a new cpu or more ram, the motherboard decides whether the parts even fit. it''s the word behind every ''sorry, that chip isn''t compatible with this board'' moment.', ARRAY['hw-cpu','hw-ram','hw-pcie','hw-firmware']::text[], ARRAY['hw-cpu','hw-ram']::text[], 'hw-bios-uefi', ARRAY['the high-speed slot standard that expansion cards connect through','the startup firmware that initializes parts at boot','the all-purpose processor that executes the instruction stream']::text[], 'the ___ only supports that ram type, so the faster sticks wouldn''t have worked anyway.', 'Use ''motherboard'' in a sentence about the main board connecting computer parts.', 'curated', 'curator', '2026-05-25'),
('hw-pcie', 'PCIe', 'P-C-I-E', 'computing', 'coding', 2, 'A high-speed connection standard for hardware components.', 'PCIe stands for Peripheral Component Interconnect Express. It is the bus standard used by GPUs, high-speed SSDs, network cards, and other expansion devices. PCIe versions and lane counts determine how much data can move between the device and the rest of the computer.', 'dropping the card into a full-width PCIe slot gave it the bandwidth it had been starved of.', 'when a hardware person frets about which slot the gpu goes in or how many lanes it gets, they mean pcie. it''s the word that explains why physical placement can quietly cap a card''s bandwidth.', ARRAY['hw-bus','hw-gpu','hw-ssd','hw-motherboard']::text[], ARRAY['hw-bus']::text[], 'hw-motherboard', ARRAY['any generic channel components use to shuttle data around','the board deciding which parts physically fit together','persistent storage holding files after the machine shuts down']::text[], 'dropping the card into a full-width ___ slot gave it the bandwidth it had been starved of.', 'Use ''PCIe'' in a sentence about a high-speed hardware connection.', 'curated', 'curator', '2026-05-25'),
('hw-ram', 'RAM', 'ram', 'computing', 'coding', 1, 'Fast temporary memory used by running programs.', 'RAM stands for random-access memory. It holds the working data for programs while the computer is on: browser tabs, dev servers, build tools, editor state, and model processes. RAM is much faster than storage, but it is temporary.', 'the laptop started swapping once the dev server and browser ate all my RAM.', 'when you open thirty tabs plus a dev server and the whole machine grinds, you''ve run low on ram. knowing it''s temporary working space, not disk, tells you when to close things versus when to free up storage.', ARRAY['hw-cpu','hw-cache','hw-ssd','os-process']::text[], ARRAY['hw-cpu']::text[], 'os-memory', ARRAY['persistent flash storage that keeps files with power off','tiny fast memory built directly into the processor','the temporary space measured by how fast its clock ticks']::text[], 'the laptop started swapping once the dev server and browser ate all my ___.', 'Use ''RAM'' in a sentence about temporary working memory.', 'curated', 'curator', '2026-05-25'),
('hw-soc', 'system on a chip (SoC)', 'S-O-C', 'computing', 'coding', 2, 'A chip that combines CPU, GPU, memory controllers, and other hardware blocks.', 'A system on a chip puts many computer subsystems onto one piece of silicon. Phones and Apple silicon Macs use SoCs so the CPU, GPU, neural engine, media engines, security hardware, and memory controllers can work closely together with less power and latency.', 'apple silicon is a system on a chip (SoC), so the gpu and cpu share the same memory pool.', 'modern phones and apple silicon feel fast and sip power because the cpu, gpu, and memory controllers all live on one piece of silicon. that integration is the soc, and it''s also why those machines are harder to upgrade part by part.', ARRAY['hw-cpu','hw-gpu','hw-arm','hw-ram']::text[], ARRAY['hw-cpu','hw-gpu','hw-arm']::text[], 'hw-instruction-set', ARRAY['a single processor that only handles ordinary instructions','the board that separate components plug into','the high-speed bus that links add-in cards']::text[], 'apple silicon is a ___, so the gpu and cpu share the same memory pool.', 'Use ''SoC'' in a sentence about a chip that combines many hardware subsystems.', 'curated', 'curator', '2026-05-25'),
('hw-ssd', 'SSD', 'S-S-D', 'computing', 'coding', 1, 'Persistent flash storage that keeps files when power is off.', 'SSD stands for solid-state drive. It stores the OS, apps, source code, databases, build artifacts, photos, and downloaded packages. Compared with older spinning disks, SSDs have much faster random access, which helps app launches, builds, and local database work.', 'i moved the giant node_modules folder onto a faster SSD and installs got quicker.', 'the reason a fresh laptop opens apps and checks out repos so fast is the ssd. it also helps you catch yourself when you mix up ''no room for files'' (storage) with ''no room to run this'' (memory).', ARRAY['hw-ram','os-filesystem','dev-node-modules','dev-build-artifact']::text[], ARRAY['os-filesystem']::text[], 'hw-pcie', ARRAY['fast temporary memory wiped every time the machine powers down','the small cache sitting right beside the processor','the main circuit board every component plugs into']::text[], 'i moved the giant node_modules folder onto a faster ___ and installs got quicker.', 'Use ''SSD'' in a sentence about persistent storage.', 'curated', 'curator', '2026-05-25'),
('os-daemon', 'daemon', 'DEE-mun', 'computing', 'coding', 2, 'A background process that runs without a normal interactive window.', 'A daemon is a long-running background process managed by the OS or a service manager. It might listen for network requests, watch files, sync data, run scheduled work, or keep a local service alive. On macOS, launchd manages many daemon-like services.', 'the database daemon kept serving connections even after i quit the terminal.', 'when something keeps listening or syncing long after you closed the terminal, that''s a daemon, a background process with no window. on a mac, launchd is full of them, and it''s the first word to reach for when a port mysteriously stays busy.', ARRAY['os-process','flow-port','os-shell']::text[], ARRAY['os-process']::text[], 'cloud-cron', ARRAY['a foreground process tied to an interactive terminal window','a single stream of work inside one process','the os layer managing every process and chunk of memory']::text[], 'the database ___ kept serving connections even after i quit the terminal.', 'Use ''daemon'' in a sentence about a background process.', 'curated', 'curator', '2026-05-25'),
('os-deadlock', 'deadlock', null, 'computing', 'coding', 2, 'A state where two or more tasks wait on each other forever.', 'A deadlock happens when work cannot continue because each participant is holding something the other needs. In software this often means locks: thread A holds lock 1 and waits for lock 2, while thread B holds lock 2 and waits for lock 1.', 'the two workers hit a deadlock because each grabbed one lock and waited on the other.', 'when two parts of a program freeze forever, each holding the lock the other needs, that''s a deadlock. naming it precisely matters because the fix is about lock ordering, not the timeouts or restarts you''d reach for with a mere slowdown.', ARRAY['os-thread','sys-race-condition','sys-timeout','data-transaction']::text[], ARRAY['os-thread']::text[], 'sys-race-condition', ARRAY['two tasks racing to touch shared state in the wrong order','a single task that simply gives up after a time limit','a single stream of work running inside one process']::text[], 'the two workers hit a ___ because each grabbed one lock and waited on the other.', 'Use ''deadlock'' in a sentence about tasks waiting on each other forever.', 'curated', 'curator', '2026-05-25'),
('os-environment-variable', 'environment variable', null, 'computing', 'coding', 1, 'A named runtime value supplied outside the source code.', 'An environment variable lets a process read configuration from its environment: API URLs, feature flags, mode names, and secret references. Sensitive values should not be printed or committed. Local, preview, and production environments can have different values.', 'the function blew up in production because one environment variable was never set there.', 'the trick that lets identical code hit a local api in dev and a real one in production, without editing the repo, is the environment variable. it''s also where secrets belong, so you don''t hardcode or commit them.', ARRAY['os-process','os-shell','sec-secret','cloud-environment']::text[], ARRAY['os-process']::text[], 'sec-secret', ARRAY['the running program that reads these values from its surroundings','the command interpreter that can print or set those values','a stored secret reference checked into source control']::text[], 'the function blew up in production because one ___ was never set there.', 'Use ''environment variable'' in a sentence about runtime configuration outside code.', 'curated', 'curator', '2026-05-25'),
('os-filesystem', 'filesystem', null, 'computing', 'coding', 1, 'The OS structure that stores and organizes files and folders.', 'A filesystem defines how files are named, stored, found, permissioned, and updated on storage. Paths, folders, file extensions, read/write permissions, and disk free-space errors all live in this layer.', 'the import broke because the filesystem was case-sensitive on the server but not on my mac.', 'paths, missing assets, permission errors, and ''works from this folder but not that one'' all live in the filesystem. it''s the literal ground your repo sits on, so naming it helps you place a whole class of bugs.', ARRAY['os-path','hw-ssd','os-permission','dev-build-artifact']::text[], ARRAY['hw-ssd']::text[], 'os-system-call', ARRAY['the single text address pointing at one file or folder','the flash hardware that physically stores the files','the rule deciding who can read or write a file']::text[], 'the import broke because the ___ was case-sensitive on the server but not on my mac.', 'Use ''filesystem'' in a sentence about storing and finding files.', 'curated', 'curator', '2026-05-25'),
('os-garbage-collection', 'garbage collection', null, 'computing', 'coding', 2, 'Runtime cleanup that frees heap memory no longer reachable by the program.', 'Garbage collection is automatic memory cleanup. The runtime tracks which objects can still be reached by the program, then frees heap memory that is no longer reachable. It reduces manual memory bugs, but collection pauses and memory pressure can still affect performance.', 'the app hitched for a moment whenever garbage collection swept up the unused objects.', 'the reason some languages feel easier yet still stutter under load is garbage collection, the runtime pausing to free memory nothing references anymore. knowing it lets you read a performance dip without immediately blaming the hardware.', ARRAY['os-heap','os-memory','code-object']::text[], ARRAY['os-heap']::text[], 'os-memory', ARRAY['the region of memory where dynamically created objects live','manually freeing each allocation yourself in code','two tasks stuck waiting on each other''s locks forever']::text[], 'the app hitched for a moment whenever ___ swept up the unused objects.', 'Use ''garbage collection'' in a sentence about automatic memory cleanup.', 'curated', 'curator', '2026-05-26'),
('os-heap', 'heap', null, 'computing', 'coding', 2, 'The part of process memory used for data created while a program runs.', 'The heap is a region of memory where a program stores dynamically created objects and values that need to live beyond one function call. Languages manage heap memory differently: some require manual freeing, while others use garbage collection.', 'the editor crashed once a few huge image previews filled the heap.', '''used too much memory'' gets a specific shape in crash logs when the heap fills, the region holding objects created while the program runs. spotting the word tells you the leak is in dynamically allocated data, not the stack or the cache.', ARRAY['os-memory','os-garbage-collection','code-object','os-process']::text[], ARRAY['os-memory']::text[], 'os-garbage-collection', ARRAY['the total working space a running program is handed','the os choice of which thread gets cpu time next','the runtime cleanup that frees unreachable objects']::text[], 'the editor crashed once a few huge image previews filled the ___.', 'Use ''heap'' in a sentence about dynamically allocated process memory.', 'curated', 'curator', '2026-05-26'),
('os-kernel', 'kernel', null, 'computing', 'coding', 2, 'The core OS layer that manages hardware, memory, files, and processes.', 'The kernel sits between programs and hardware. It schedules processes, manages memory, controls filesystem access, exposes networking, and handles system calls. Apps do not usually talk directly to hardware; they ask the kernel to do privileged work.', 'the kernel stepped in and killed the runaway process before it took down the whole machine.', 'when the system itself kills your process for using too much memory, that decision came from the kernel. it''s the privileged core that sits between your code and the hardware, so permissions, crashes, and drivers all trace back to it.', ARRAY['os-system-call','os-process','os-filesystem','hw-firmware']::text[], ARRAY['os-process']::text[], 'os-system-call', ARRAY['a single running instance of one program','a program''s request to that core for protected work','the startup firmware that runs before the os loads']::text[], 'the ___ stepped in and killed the runaway process before it took down the whole machine.', 'Use ''kernel'' in a sentence about the OS layer managing hardware and processes.', 'curated', 'curator', '2026-05-25'),
('os-memory', 'memory', null, 'computing', 'coding', 1, 'The working space a running program uses while it is active.', 'Memory is the fast working space a process uses for code, data, stacks, heaps, caches, and temporary values. RAM is the hardware that provides much of that space; OS memory management decides how running programs get it and what happens when they use too much.', 'the browser tab chewed through so much memory that the os finally killed it.', 'when a tab balloons and the system kills it, you''ve hit a memory limit, the live working space a program runs in. knowing this is how you hear ''it ran out of working space'' instead of confusing it with running out of disk.', ARRAY['hw-ram','os-process','os-heap','os-kernel']::text[], ARRAY['hw-ram','os-process']::text[], 'os-heap', ARRAY['persistent storage that keeps files after a power-off','the small fast cache built right into the processor','the region of working space used for dynamically created data']::text[], 'the browser tab chewed through so much ___ that the os finally killed it.', 'Use ''memory'' in a sentence about the working space a running program uses.', 'curated', 'curator', '2026-05-26'),
('os-path', 'path', null, 'computing', 'coding', 1, 'The text address that tells the OS where a file or folder lives.', 'A path points to a location in the filesystem. It can be absolute, starting from the root of the machine, or relative, starting from the current working folder. Paths explain why the same command can work in one folder and fail in another.', 'the script broke because the path still pointed at the old build folder.', 'the same command working in one folder and failing in another almost always comes down to a path, the text address pointing at a file. knowing absolute versus relative is what stops ''file not found'' from being a mystery.', ARRAY['os-filesystem','os-shell','dev-build-artifact','flow-localhost']::text[], ARRAY['os-filesystem']::text[], 'os-permission', ARRAY['the os structure organizing all files and folders overall','the command interpreter that runs terminal commands','the rule deciding who can read or write the file']::text[], 'the script broke because the ___ still pointed at the old build folder.', 'Use ''path'' in a sentence about where a file or folder lives.', 'curated', 'curator', '2026-05-26'),
('os-permission', 'OS permission', null, 'computing', 'coding', 1, 'An operating-system rule that decides who can read, write, or execute a file or resource.', 'OS permissions are access rules enforced by the operating system. A file might be readable but not writable, a script might need execute permission, and a process might be blocked from writing outside an allowed folder. These permissions are lower-level than app roles or product settings.', 'the deploy script was right there, but it lacked the OS permission to actually execute.', 'when a script clearly exists but still won''t run, the os permission, not your app''s settings, is often the wall. this word lets you tell ''the app said no'' apart from ''the operating system refused to let the file execute''.', ARRAY['os-path','os-filesystem','sec-permission','os-process']::text[], ARRAY['os-filesystem']::text[], 'sec-permission', ARRAY['a role bundle configured inside an app''s admin dashboard','the text address telling the os where a file lives','the os structure that stores and organizes files']::text[], 'the deploy script was right there, but it lacked the ___ to actually execute.', 'Use ''OS permission'' in a sentence about file or process access on a machine.', 'curated', 'curator', '2026-05-26'),
('os-process', 'process', null, 'computing', 'coding', 1, 'A running instance of a program managed by the OS.', 'A process has its own memory, open files, environment, permissions, and execution state. When you start a dev server, browser, database, or test runner, the OS creates one or more processes to run that work.', 'the port stayed occupied because an old node process was still hanging around.', 'when a port is still busy or a dev server won''t die, it''s usually an old process the os never cleaned up. it''s the unit you actually hunt for in activity monitor when something keeps running in the background.', ARRAY['os-thread','os-kernel','os-environment-variable','flow-port']::text[], ARRAY['os-kernel']::text[], 'os-thread', ARRAY['a single stream of work running within a larger program','the core os layer that manages every running program','a long-running background service with no interactive window']::text[], 'the port stayed occupied because an old node ___ was still hanging around.', 'Use ''process'' in a sentence about a running program.', 'curated', 'curator', '2026-05-25'),
('os-scheduler', 'scheduler', null, 'computing', 'coding', 2, 'The OS component that decides which process or thread gets CPU time next.', 'The scheduler is the operating-system traffic controller for CPU time. Many processes and threads want to run, but CPU cores are limited. The scheduler pauses and resumes work so the machine can feel like it is doing many things at once.', 'the scheduler handed the test runner cpu time while the browser sat waiting on the network.', 'the reason a busy machine can still feel like it''s juggling everything at once is the scheduler deciding who gets cpu time next. it''s the word that reframes background spikes and laggy responsiveness as an os concern, not just your app code.', ARRAY['os-kernel','os-process','os-thread','hw-cpu']::text[], ARRAY['os-kernel','os-process','os-thread']::text[], 'os-deadlock', ARRAY['one independent execution unit physically inside the cpu','the privileged core managing hardware, memory, and processes','a lone stream of work running within a process']::text[], 'the ___ handed the test runner cpu time while the browser sat waiting on the network.', 'Use ''scheduler'' in a sentence about the OS deciding what runs next.', 'curated', 'curator', '2026-05-26'),
('os-shell', 'shell', null, 'computing', 'coding', 1, 'A command interpreter that runs terminal commands.', 'The shell reads commands like git status, npm run test, cd, rg, and kill, then starts programs or changes shell state. zsh, bash, and fish are shells. The terminal is the window; the shell is the command language running inside it.', 'the command did something weird because the shell expanded the * before it ever ran.', 'the terminal is just the window; the shell is the language running inside it that interprets your commands. knowing the difference is why quoting, wildcards, and environment variables behave the way they do when a command misfires.', ARRAY['os-environment-variable','os-process']::text[], ARRAY['os-process']::text[], 'os-system-call', ARRAY['the window or app the command language runs inside','a named runtime value the shell reads from its surroundings','a running instance of one single program']::text[], 'the command did something weird because the ___ expanded the * before it ever ran.', 'Use ''shell'' in a sentence about running terminal commands.', 'curated', 'curator', '2026-05-25'),
('os-system-call', 'system call', null, 'computing', 'coding', 2, 'A request from a program to the kernel for OS-level work.', 'A system call is how user-space code asks the kernel to do protected work: read a file, open a socket, allocate memory, start a process, or write to a device. Languages and libraries wrap system calls so app code rarely invokes them directly.', 'that innocent-looking open() turns into a system call before the file ever gets read.', 'every time your code opens a file or a socket, it''s quietly making a system call to ask the kernel to do the protected part. knowing this makes ''software talks to hardware'' feel like clear layers instead of magic.', ARRAY['os-kernel','os-filesystem','net-socket','os-process']::text[], ARRAY['os-kernel']::text[], 'os-permission', ARRAY['the core os layer the request is actually made to','a named runtime value passed in from outside the code','a rule deciding who may read or write a file']::text[], 'that innocent-looking open() turns into a ___ before the file ever gets read.', 'Use ''system call'' in a sentence about a program asking the kernel for work.', 'curated', 'curator', '2026-05-25'),
('os-thread', 'thread', null, 'computing', 'coding', 2, 'A path of execution inside a process.', 'A thread lets one process run multiple paths of work. Threads share the process memory, which makes communication fast but also creates coordination problems. Bugs like deadlocks and race conditions often come from threads or async work touching shared state in the wrong order.', 'the ui froze because we accidentally did the file parsing on the main thread.', 'when an app stays responsive while doing heavy work, someone moved that work off the main thread. it''s the word that separates ''one running program'' from ''one stream of work inside it'', and it''s where deadlocks and race conditions are born.', ARRAY['os-process','hw-core','sys-race-condition','os-deadlock']::text[], ARRAY['os-process']::text[], 'os-deadlock', ARRAY['a full running instance of a program with its own memory','one independent execution unit physically inside the chip','the os component that decides what runs next']::text[], 'the ui froze because we accidentally did the file parsing on the main ___.', 'Use ''thread'' in a sentence about one execution path inside a process.', 'curated', 'curator', '2026-05-25'),
('bi-calculated-column', 'calculated column', null, 'data-analytics', 'coding', 2, 'A model column computed from a DAX expression for each row.', 'A calculated column stores a DAX result for each row of a table in the semantic model. It differs from a measure, which is evaluated dynamically in filter context.', 'We used a calculated column for customer segment because the value never changes once the row is loaded.', 'a calculated column is figured out once per row and frozen into the table, unlike a measure that recalculates with filters. mixing them up is a classic Power BI mistake — using a column where you needed a measure gives you totals that won''t move when you slice.', ARRAY['bi-dax','bi-measure','bi-semantic-model']::text[], ARRAY['bi-dax']::text[], 'bi-measure', ARRAY['a value that recomputes with the current filters','a column of untouched imported source data','the clickable filter sitting on the report page']::text[], 'We used a ___ for customer segment because the value never changes once the row is loaded.', 'Use ''calculated column'' in a sentence about Power BI model logic.', 'curated', 'curator', '2026-05-29'),
('bi-dashboard', 'Power BI dashboard', null, 'data-analytics', 'coding', 1, 'A one-page collection of pinned visuals for monitoring key metrics.', 'A Power BI dashboard is a single canvas of pinned tiles from one or more reports or semantic models. It is usually used for monitoring rather than deep report authoring.', 'Leadership just watches the Power BI dashboard on Monday mornings; nobody opens the full report.', 'leadership usually wants a dashboard — one screen of pinned numbers to glance at every Monday — not a full report to dig through. calling the right one keeps you from building a deep report when they wanted a single overview.', ARRAY['bi-report','prod-kpi']::text[], ARRAY['ent-powerbi']::text[], 'bi-report', ARRAY['a multi-page interactive report you click through','the shared data model feeding the numbers','the team container that holds the published content']::text[], 'Leadership just watches the ___ on Monday mornings; nobody opens the full report.', 'Use ''Power BI dashboard'' in a sentence about monitoring metrics.', 'curated', 'curator', '2026-05-29'),
('bi-dax', 'DAX', 'D-A-X', 'data-analytics', 'coding', 2, 'Data Analysis Expressions, the formula language for Power BI measures and calculated models.', 'DAX stands for Data Analysis Expressions. It is the formula language used in Power BI, Analysis Services, and Power Pivot to write measures, calculated columns, and model logic.', 'The margin measure is written in DAX, so the fix is in the model, not in the visual.', 'DAX is the formula language behind Power BI measures, and it reads nothing like Excel formulas even though it looks similar. when a measure returns a weird total, knowing it''s DAX tells you where to go look instead of treating it like a broken SUM.', ARRAY['bi-measure','excel-power-pivot','bi-calculated-column']::text[], ARRAY['bi-semantic-model']::text[], 'bi-filter-context', ARRAY['the get-and-transform language used to clean data','the shared container holding reports and models','the clickable filter sitting on a report page']::text[], 'The margin measure is written in ___, so the fix is in the model, not in the visual.', 'Use ''DAX'' in a sentence about a Power BI calculation.', 'curated', 'curator', '2026-05-29'),
('bi-gateway', 'data gateway', null, 'data-analytics', 'coding', 2, 'A bridge that lets cloud Power BI reach on-premises data sources.', 'A Power BI data gateway is installed inside a network so the Power BI service can refresh or query internal data sources without exposing those sources directly to the public internet.', 'The overnight refresh failed because the data gateway on the office server was offline.', 'when your data still lives inside the company network, cloud Power BI can''t reach it without a gateway sitting in between. it''s the usual culprit when a scheduled refresh suddenly can''t find a source it pulled from fine yesterday.', ARRAY['bi-refresh','sec-rbac']::text[], ARRAY['bi-refresh']::text[], 'bi-refresh', ARRAY['the scheduled reload of a model''s data','a rule limiting which rows each viewer can see','the reusable model the reports query']::text[], 'The overnight refresh failed because the ___ on the office server was offline.', 'Use ''data gateway'' in a sentence about Power BI reaching internal data.', 'curated', 'curator', '2026-05-29'),
('bi-measure', 'measure', null, 'data-analytics', 'coding', 2, 'A DAX calculation evaluated in the current filter context.', 'A Power BI measure is a reusable calculation, usually written in DAX. Measures respond to slicers, filters, report visuals, and relationships, so the same measure can calculate different results in different views.', 'The revenue measure recalculates the moment you click a different region in the slicer.', 'a measure recalculates based on whatever filters are active, so the same "revenue" tile shows a different number per region or per quarter without you writing a new formula. it''s why one calculation can answer a hundred slices of the question.', ARRAY['bi-dax','bi-slicer']::text[], ARRAY['bi-semantic-model']::text[], 'bi-dax', ARRAY['a value computed once per row and stored on the table','the clickable filter control on a report page','the whole shared model sitting behind the report']::text[], 'The revenue ___ recalculates the moment you click a different region in the slicer.', 'Use ''measure'' in a sentence about a Power BI calculation.', 'curated', 'curator', '2026-05-29'),
('bi-refresh', 'refresh', null, 'data-analytics', 'coding', 1, 'Updating a semantic model by reloading or recalculating its source data.', 'A Power BI refresh updates imported data, recalculates model results, and makes newer source data available to reports. Scheduled refresh often depends on credentials, gateways, capacity, and source-system availability.', 'The report looked fine but the numbers were a day old because the overnight refresh failed.', 'a report can look perfectly fine and still be showing yesterday''s data if the refresh failed overnight. knowing the word is how you explain why the dashboard is "working" but the numbers are stale.', ARRAY['bi-semantic-model','bi-gateway','fabric-direct-lake']::text[], ARRAY['bi-semantic-model']::text[], 'bi-gateway', ARRAY['the bridge that reaches data behind a company network','the shared model that holds the tables','a rule that limits which rows a viewer sees']::text[], 'The report looked fine but the numbers were a day old because the overnight ___ failed.', 'Use ''refresh'' in a sentence about updating Power BI data.', 'curated', 'curator', '2026-05-29'),
('bi-report', 'Power BI report', null, 'data-analytics', 'coding', 1, 'An interactive multi-page analytical view built from visuals and a semantic model.', 'A Power BI report is a set of pages filled with visuals such as charts, tables, slicers, cards, and maps. Reports usually query a semantic model and let viewers filter or explore data.', 'Open the Power BI report and use the channel page — conversion is broken out by source there.', 'when someone shares "the Power BI report," they mean the interactive multi-page thing you click through and filter — not the data behind it and not a one-screen summary. knowing the difference keeps you from asking for the wrong artifact.', ARRAY['ent-powerbi','bi-semantic-model']::text[], ARRAY['ent-powerbi']::text[], 'bi-dashboard', ARRAY['a single-page board of pinned metric tiles','the reusable data model the visuals query against','a clickable control that narrows the visuals']::text[], 'Open the ___ and use the channel page — conversion is broken out by source there.', 'Use ''Power BI report'' in a sentence about an interactive report page.', 'curated', 'curator', '2026-05-29'),
('bi-rls', 'RLS', 'R-L-S', 'data-analytics', 'coding', 2, 'Row-level security that filters model data based on the viewer.', 'RLS stands for row-level security. In Power BI, row-level security applies roles and filters so different viewers can see different rows from the same semantic model.', 'RLS means each regional manager opens the same report but only sees their own region''s rows.', 'RLS is how one report safely shows each person only their own rows — every regional manager opens the same report but sees just their region. when a stakeholder asks "can they see everyone''s numbers?", this is the control that answers it.', ARRAY['bi-semantic-model','sec-rbac','sys-rls']::text[], ARRAY['bi-semantic-model']::text[], 'sec-rbac', ARRAY['a control viewers click to narrow the page','the reusable data model behind the report','the bridge reaching data inside a company network']::text[], '___ means each regional manager opens the same report but only sees their own region''s rows.', 'Use ''RLS'' in a sentence about filtered Power BI access.', 'curated', 'curator', '2026-05-29'),
('bi-semantic-model', 'semantic model', null, 'data-analytics', 'coding', 2, 'The reusable Power BI data model behind reports, measures, relationships, and refresh.', 'A Power BI semantic model defines tables, relationships, measures, security, refresh, and business-friendly field names. Reports use it so multiple views can agree on the same metrics.', 'We rebuilt the report on the certified semantic model so finance and ops finally see the same revenue number.', 'the semantic model is the shared data layer that makes every report agree on what "revenue" means. when two reports show different numbers for the same thing, the fix usually lives in the model, not in the charts.', ARRAY['bi-measure','bi-refresh']::text[], ARRAY['ent-powerbi','data-table']::text[], 'bi-measure', ARRAY['a single interactive page inside a report','a one-screen board of pinned number tiles','the scheduled job that reloads the underlying data']::text[], 'We rebuilt the report on the certified ___ so finance and ops finally see the same revenue number.', 'Use ''semantic model'' in a sentence about the Power BI data model behind reports.', 'curated', 'curator', '2026-05-29'),
('bi-slicer', 'slicer', null, 'data-analytics', 'coding', 1, 'An interactive filter control on a Power BI report page.', 'A slicer is a report visual that lets viewers choose filters such as region, date, department, or product. Slicers change the context used by visuals and measures on the page.', 'Drag the date slicer to this quarter and every visual on the page updates with it.', 'the slicer is the on-page control viewers actually click — region, date, department — to narrow what they''re looking at. when someone says "just use the date filter at the top," they mean the slicer.', ARRAY['bi-report','bi-measure']::text[], ARRAY['bi-report']::text[], 'bi-filter-context', ARRAY['a reusable calculation defined in the model','a pinned number tile on a dashboard','the shared data model behind the report']::text[], 'Drag the date ___ to this quarter and every visual on the page updates with it.', 'Use ''slicer'' in a sentence about filtering a Power BI report.', 'curated', 'curator', '2026-05-29'),
('bi-workspace', 'Power BI workspace', null, 'data-analytics', 'coding', 1, 'A shared container for Power BI reports, semantic models, dashboards, apps, and permissions.', 'A Power BI workspace is where teams collaborate on Power BI content. It can hold reports, dashboards, semantic models, dataflows, apps, and role-based access settings.', 'The finance report lives in the Finance Power BI workspace, so ask to be added there if you can''t open it.', 'a workspace is the shared container where a team''s reports, models, and dashboards live and where access is granted. when you can''t see a report someone built, the answer is almost always "you''re not in that workspace yet."', ARRAY['bi-report','bi-semantic-model']::text[], ARRAY['ent-powerbi']::text[], 'bi-app', ARRAY['a single multi-page interactive report','the data model sitting behind the reports','the packaged app handed out to viewers']::text[], 'The finance report lives in the Finance ___, so ask to be added there if you can''t open it.', 'Use ''Power BI workspace'' in a sentence about where reports and models live.', 'curated', 'curator', '2026-05-29'),
('excel-cell', 'cell', null, 'data-analytics', 'coding', 1, 'One grid address in a worksheet where a value or formula can live.', 'A cell is a single box in an Excel worksheet, usually addressed by column and row, such as B7. A cell can hold typed text, a number, a date, a formula result, or a direct formula.', 'The total was off because cell B7 still pointed at last month''s number.', 'when a number looks wrong, the fastest fix is naming the exact cell — "B7 is pointing at last month." being able to say the address instead of "that box up there" is half of spreadsheet debugging.', ARRAY['excel-range','excel-formula','excel-worksheet']::text[], ARRAY['excel-worksheet']::text[], 'excel-range', ARRAY['a rectangular block of several grouped cells','one tab of the spreadsheet file','a built-in operation like sum or average']::text[], 'The total was off because ___ B7 still pointed at last month''s number.', 'Use ''cell'' in a sentence about one address in Excel.', 'curated', 'curator', '2026-05-29'),
('excel-formula', 'formula', null, 'data-analytics', 'coding', 1, 'An expression Excel calculates from values, functions, or cell references.', 'A formula is an Excel expression that starts with an equals sign and calculates a result. It can use cell references, functions, constants, operators, and references to tables or ranges.', 'The margin formula just divides profit by revenue, so if profit''s wrong the whole column is wrong.', 'when you review someone''s sheet, the real question is which numbers were typed and which are calculated. a formula is the calculated kind — click a cell, see the equals sign, and you know it''s doing math instead of holding a hardcoded number.', ARRAY['excel-function','excel-cell','excel-range']::text[], ARRAY['excel-cell']::text[], 'excel-function', ARRAY['a built-in named operation such as sum or if','a constant value somebody typed straight in','a summary view that groups rows by category']::text[], 'The margin ___ just divides profit by revenue, so if profit''s wrong the whole column is wrong.', 'Use ''formula'' in a sentence about Excel calculating a value.', 'curated', 'curator', '2026-05-29'),
('excel-function', 'function', null, 'data-analytics', 'coding', 1, 'A built-in Excel operation such as SUM, XLOOKUP, or IF.', 'An Excel function is a named operation used inside a formula. Functions do common work such as adding values, looking up matches, checking conditions, counting rows, or transforming text.', 'Use the XLOOKUP function to pull the customer tier from the other tab instead of copy-pasting it.', 'formulas are built out of functions — SUM, IF, XLOOKUP. when someone says "use a lookup function for that," they''re naming the specific building block to drop inside the formula, not the formula itself.', ARRAY['excel-formula']::text[], ARRAY['excel-formula']::text[], 'excel-xlookup', ARRAY['the whole expression beginning with an equals sign','a pointer to the value in another cell','a grouped summary you build by dragging fields']::text[], 'Use the XLOOKUP ___ to pull the customer tier from the other tab instead of copy-pasting it.', 'Use ''function'' in a sentence about a named Excel operation.', 'curated', 'curator', '2026-05-29'),
('excel-pivot-table', 'PivotTable', null, 'data-analytics', 'coding', 1, 'An Excel summary table for grouping, filtering, and aggregating data.', 'A PivotTable summarizes source data by dragging fields into rows, columns, values, and filters. It is commonly used to group and aggregate data without writing formulas for every view.', 'I built a PivotTable to group sales by region and month so I didn''t have to write a formula for each combination.', 'when you have thousands of raw rows and someone wants "sales by region by month" in five minutes, a PivotTable gets you there by dragging fields instead of writing a formula for every cell. it''s the fastest way to turn a data dump into an answer.', ARRAY['excel-table','bi-slicer']::text[], ARRAY['excel-table']::text[], 'excel-power-pivot', ARRAY['a structured table feeding the raw source rows','a clickable filter tile that narrows a report','one formula sitting in a single cell']::text[], 'I built a ___ to group sales by region and month so I didn''t have to write a formula for each combination.', 'Use ''PivotTable'' in a sentence about summarizing Excel data.', 'curated', 'curator', '2026-05-29'),
('excel-power-pivot', 'Power Pivot', null, 'data-analytics', 'coding', 2, 'An Excel data model feature for relationships, measures, and larger analytical models.', 'Power Pivot lets Excel work with a richer data model: multiple related tables, measures, calculated columns, and larger datasets than ordinary worksheet formulas are comfortable handling.', 'The workbook uses Power Pivot to relate customers, orders, and items so one measure works across all three.', 'once a workbook needs related tables and reusable measures instead of one giant flat sheet, you''ve outgrown normal formulas — Power Pivot is where Excel starts behaving like Power BI. recognizing it tells you someone''s doing real modeling, not just a spreadsheet.', ARRAY['excel-pivot-table','bi-dax','bi-semantic-model']::text[], ARRAY['excel-table']::text[], 'bi-dax', ARRAY['the get-and-transform step that cleans incoming data','a grouped summary you assemble by dragging fields','one plain grid tab in the workbook']::text[], 'The workbook uses ___ to relate customers, orders, and items so one measure works across all three.', 'Use ''Power Pivot'' in a sentence about Excel data modeling.', 'curated', 'curator', '2026-05-29'),
('excel-power-query', 'Power Query', null, 'data-analytics', 'coding', 1, 'A data shaping tool in Excel and Power BI for cleaning and combining data before analysis.', 'Power Query is used to connect to data, clean it, reshape it, combine sources, and load the result into Excel, Power BI, or Fabric. It is the "get and transform" layer before analysis.', 'Power Query strips the blank rows and renames the columns before the report ever sees the data.', 'raw exports are almost never clean — blank rows, weird headers, three files that need stitching together. Power Query is the step where you fix all that once and have it re-run every refresh, instead of hand-cleaning the same vendor file every month.', ARRAY['excel-table','fabric-dataflow-gen2','bi-refresh']::text[], ARRAY['excel-table']::text[], 'fabric-dataflow-gen2', ARRAY['a grouped summary built by dragging fields around','the in-memory model that holds relationships and measures','a chart wired to a fixed cell range']::text[], '___ strips the blank rows and renames the columns before the report ever sees the data.', 'Use ''Power Query'' in a sentence about cleaning or combining data.', 'curated', 'curator', '2026-05-29'),
('excel-range', 'range', null, 'data-analytics', 'coding', 1, 'A selected group of Excel cells referenced together.', 'A range is one or more cells treated as a group, such as A1:D20. Formulas, charts, formatting rules, and named ranges often point at ranges.', 'Double-check the chart is reading the range A1 through D20 and not just the header row.', 'every chart and formula reads from some block of cells, and that block is the range. when a chart looks empty, the first question is usually "what range is it pointing at?"', ARRAY['excel-cell','excel-table']::text[], ARRAY['excel-cell']::text[], 'excel-table', ARRAY['a single cell address such as b7','a structured table with named header columns','a label assigned to one fixed constant']::text[], 'Double-check the chart is reading the ___ A1 through D20 and not just the header row.', 'Use ''range'' in a sentence about grouped cells in Excel.', 'curated', 'curator', '2026-05-29'),
('excel-table', 'Excel table', null, 'data-analytics', 'coding', 1, 'A named structured range with headers, filters, and formulas that expand.', 'An Excel table turns a cell range into structured data with named columns, filter controls, formatting, and formulas that can automatically fill down when rows are added.', 'Convert the revenue rows into an Excel table before Power Query reads them, or new rows won''t get picked up.', 'a plain block of cells breaks the moment you add a row; an Excel table grows with you and keeps its formulas. when a teammate says "make it an actual table first," this is the upgrade they mean.', ARRAY['excel-range','excel-power-query']::text[], ARRAY['excel-range']::text[], 'excel-power-query', ARRAY['a loose selection of highlighted cells','a pivottable that summarizes data from elsewhere','one tab inside the spreadsheet file']::text[], 'Convert the revenue rows into an ___ before Power Query reads them, or new rows won''t get picked up.', 'Use ''Excel table'' in a sentence about structured spreadsheet data.', 'curated', 'curator', '2026-05-29'),
('excel-workbook', 'Excel workbook', null, 'data-analytics', 'coding', 1, 'An Excel file that contains worksheets, tables, formulas, pivots, and data connections.', 'An Excel workbook is the whole spreadsheet file. It can contain multiple worksheets, tables, formulas, PivotTables, charts, Power Query connections, and data models.', 'I dropped everything into one Excel workbook with a separate tab for each region so nothing gets lost.', 'when someone says "i''ll send you the workbook," they mean the whole .xlsx file, not one tab. knowing the word keeps you from hunting through ten worksheets looking for "the spreadsheet they meant" — it''s all of them, in one file.', ARRAY['excel-worksheet','excel-table','excel-formula']::text[], ARRAY[]::text[], 'excel-power-query', ARRAY['a single tab of cells inside the file','a named block of cells you reference by label','a saved pivottable layout sitting on a tab']::text[], 'I dropped everything into one ___ with a separate tab for each region so nothing gets lost.', 'Use ''Excel workbook'' in a sentence about the whole spreadsheet file.', 'curated', 'curator', '2026-05-29'),
('excel-worksheet', 'worksheet', null, 'data-analytics', 'coding', 1, 'One tab inside an Excel workbook.', 'A worksheet is a single grid tab inside an Excel workbook. Each worksheet contains rows, columns, cells, formulas, tables, charts, and other spreadsheet objects.', 'Keep the assumptions on their own worksheet so people don''t edit them by accident.', 'people say "check the second tab" all day, but the real word is worksheet. once you have it, you can talk about a model with five worksheets instead of vaguely gesturing at "the other page."', ARRAY['excel-workbook','excel-cell','excel-range']::text[], ARRAY['excel-workbook']::text[], 'excel-table', ARRAY['the whole .xlsx file holding every tab','a structured range with headers you can filter','a pop-out pane showing the same numbers']::text[], 'Keep the assumptions on their own ___ so people don''t edit them by accident.', 'Use ''worksheet'' in a sentence about an Excel tab.', 'curated', 'curator', '2026-05-29'),
('fabric-data-pipeline', 'data pipeline', null, 'data-analytics', 'coding', 2, 'A Fabric workflow for moving or transforming data between systems.', 'A Fabric data pipeline orchestrates steps that copy, transform, schedule, or move data between sources and destinations. Pipelines are often used for repeatable data ingestion and ETL-style workflows.', 'The data pipeline copies CRM rows into the lakehouse every night without anyone touching it.', 'a data pipeline is the scheduled plumbing that copies and moves data between systems so nobody''s exporting CSVs by hand every night. when someone says "the nightly load," they''re talking about a pipeline doing the work while everyone''s asleep.', ARRAY['fabric-dataflow-gen2','fabric-lakehouse']::text[], ARRAY['data-table']::text[], 'fabric-dataflow-gen2', ARRAY['a power-query item that cleans data without code','a lakehouse that stores raw files as queryable tables','a notebook where an engineer runs code interactively']::text[], 'The ___ copies CRM rows into the lakehouse every night without anyone touching it.', 'Use ''data pipeline'' in a sentence about moving analytics data.', 'curated', 'curator', '2026-05-29'),
('fabric-dataflow-gen2', 'Dataflow Gen2', 'dataflow gen two', 'data-analytics', 'coding', 2, 'A Fabric and Power Query based data transformation artifact.', 'Dataflow Gen2 is a Microsoft Fabric data preparation experience built around Power Query. It lets makers connect, transform, and load data into destinations such as lakehouses and warehouses.', 'The maker used Dataflow Gen2 to clean the vendor file before loading it into the lakehouse.', 'Dataflow Gen2 is Fabric''s no-code cleanup built on the same Power Query you might know from Excel, so the skill carries over. if you''ve cleaned a vendor file in Excel, you already half-understand how makers prep data here.', ARRAY['excel-power-query','fabric-data-pipeline','fabric-lakehouse']::text[], ARRAY['excel-power-query']::text[], 'fabric-data-pipeline', ARRAY['a pipeline that schedules and orchestrates copy steps','a measure written in dax for the semantic model','a lakehouse that keeps raw files queryable as tables']::text[], 'The maker used ___ to clean the vendor file before loading it into the lakehouse.', 'Use ''Dataflow Gen2'' in a sentence about Fabric data preparation.', 'curated', 'curator', '2026-05-29'),
('fabric-direct-lake', 'Direct Lake', 'direct lake', 'data-analytics', 'coding', 2, 'A Power BI mode that reads Fabric lake data directly without import refresh.', 'Direct Lake is a Power BI semantic model storage mode in Microsoft Fabric. It can load data directly from Delta tables in OneLake for high-performance interactive analysis without a traditional import refresh cycle.', 'The big Fabric model uses Direct Lake, so it reads OneLake live instead of importing every table.', 'Direct Lake lets a Power BI model read straight from OneLake tables instead of importing and refreshing on a schedule, which is why big Fabric models stay fast without a nightly reload. it explains why some models never talk about refresh at all.', ARRAY['fabric-onelake','bi-semantic-model','bi-refresh']::text[], ARRAY['fabric-onelake','bi-semantic-model']::text[], 'bi-directquery', ARRAY['the scheduled import-and-reload cycle a model can run','the single lake storage foundation itself','a reusable model holding measures and relationships']::text[], 'The big Fabric model uses ___, so it reads OneLake live instead of importing every table.', 'Use ''Direct Lake'' in a sentence about a Power BI model reading Fabric data.', 'curated', 'curator', '2026-05-29'),
('fabric-lakehouse', 'lakehouse', null, 'data-analytics', 'coding', 2, 'A Fabric data item combining data lake storage with warehouse-style querying.', 'A Fabric lakehouse stores files and tables in OneLake and supports analytical querying over structured and unstructured data. It is a common home for data engineering work before reporting.', 'The raw events land in a lakehouse first, then Power BI reads from the cleaned tables.', 'a lakehouse lets you dump raw files and still query them like tables, so engineers don''t have to choose between a messy data lake and a strict warehouse. it''s where most data engineering work lands before anything gets reported on.', ARRAY['fabric-onelake','fabric-notebook']::text[], ARRAY['fabric-onelake']::text[], 'fabric-warehouse', ARRAY['the org-wide lake foundation every fabric item sits on','a strict warehouse that rejects unstructured raw files','a scheduled pipeline that shuttles rows between stores']::text[], 'The raw events land in a ___ first, then Power BI reads from the cleaned tables.', 'Use ''lakehouse'' in a sentence about Fabric data storage.', 'curated', 'curator', '2026-05-29'),
('fabric-microsoft-fabric', 'Microsoft Fabric', null, 'data-analytics', 'coding', 2, 'Microsoft Fabric is Microsoft''s unified analytics platform for data movement, storage, engineering, science, real-time analytics, and BI.', 'Microsoft Fabric brings together analytics workloads such as Data Factory, Data Engineering, Data Warehouse, Data Science, Real-Time Intelligence, OneLake, and Power BI under one SaaS platform.', 'We moved the whole pipeline and the Power BI model into Microsoft Fabric so it all lives in one place.', 'Fabric is the umbrella that bundles data pipelines, storage, notebooks, warehouses, and Power BI into one place. once you have the word, all those separate-looking analytics screens stop feeling like a dozen unrelated apps.', ARRAY['fabric-onelake','fabric-lakehouse','ent-powerbi']::text[], ARRAY['ent-powerbi','data-warehouse']::text[], 'fabric-onelake', ARRAY['the shared lake storage that all the data sits on','a relational sql store for structured warehousing','an interactive coding document for data work']::text[], 'We moved the whole pipeline and the Power BI model into ___ so it all lives in one place.', 'Use ''Microsoft Fabric'' in a sentence about Microsoft analytics work.', 'curated', 'curator', '2026-05-29'),
('fabric-notebook', 'notebook', null, 'data-analytics', 'coding', 2, 'An interactive Fabric coding document for data engineering or data science.', 'A Fabric notebook lets data workers run code, notes, queries, and visual outputs together. Notebooks are commonly used for exploration, transformations, Spark jobs, and data science workflows.', 'The data engineer tried the transformation in a Fabric notebook before wiring it into the pipeline.', 'a notebook is where a data engineer runs code, notes, and query output together to explore or transform data before it''s productionized. when someone says "let me test that in a notebook," they mean the scratchpad, not a finished pipeline.', ARRAY['fabric-lakehouse','lang-python']::text[], ARRAY['lang-python']::text[], 'fabric-spark-job', ARRAY['a drag-and-drop pipeline canvas for scheduled data moves','a no-code power query editor for cleaning tables','a sql warehouse you query with plain select statements']::text[], 'The data engineer tried the transformation in a Fabric ___ before wiring it into the pipeline.', 'Use ''notebook'' in a sentence about Fabric data engineering.', 'curated', 'curator', '2026-05-29'),
('fabric-onelake', 'OneLake', 'one lake', 'data-analytics', 'coding', 2, 'The shared Microsoft Fabric data lake for organizational analytics data.', 'OneLake is the unified data lake built into Microsoft Fabric. It gives Fabric workloads a common storage foundation for lakehouses, warehouses, shortcuts, and analytics data.', 'Both the lakehouse and the warehouse tables actually live in OneLake underneath.', 'OneLake is the single storage foundation everything in Fabric sits on, so a lakehouse and a warehouse aren''t separate islands of data. it''s the reason teams stop copying the same dataset into five different tools.', ARRAY['fabric-microsoft-fabric','fabric-lakehouse']::text[], ARRAY['fabric-microsoft-fabric']::text[], 'fabric-lakehouse', ARRAY['a single lakehouse item holding one team''s tables','a sql warehouse tuned for relational reporting queries','a semantic model that powers the report visuals']::text[], 'Both the lakehouse and the warehouse tables actually live in ___ underneath.', 'Use ''OneLake'' in a sentence about Fabric storage.', 'curated', 'curator', '2026-05-29'),
('fabric-warehouse', 'warehouse', null, 'data-analytics', 'coding', 2, 'A Fabric SQL analytics store for relational data warehousing.', 'A Fabric warehouse is a relational analytics store for SQL-based data warehousing. It is designed for structured tables, SQL queries, reporting, and analytical workloads.', 'We modeled the finance tables in a Fabric warehouse so the team could query them with plain SQL.', 'when the data is clean, structured, and you want to hit it with SQL, a Fabric warehouse is the right home — not a lakehouse and not a notebook. knowing which is which keeps you from modeling finance tables in the wrong store.', ARRAY['fabric-microsoft-fabric','data-warehouse','lang-sql']::text[], ARRAY['data-warehouse','lang-sql']::text[], 'fabric-lakehouse', ARRAY['a store that keeps raw files queryable alongside tables','the lake foundation that underlies every fabric store','a power-query cleanup item that preps incoming data']::text[], 'We modeled the finance tables in a Fabric ___ so the team could query them with plain SQL.', 'Use ''warehouse'' in a sentence about Fabric SQL analytics.', 'curated', 'curator', '2026-05-29'),
('data-backfill', 'backfill', null, 'databases', 'coding', 2, 'A one-time update that fills or repairs existing rows.', 'A backfill updates data that already exists. If a new column is added, a backfill might populate it for old rows. If old records used inconsistent labels, a backfill might normalize them. Backfills need care because they touch historical data.', 'a pronunciation backfill filled in missing say-it hints for the old acronym terms.', 'there''s a real difference between changing future behavior and fixing records that already exist. a backfill is the second one, and because it touches historical data it''s the kind of job you scope carefully and watch.', ARRAY['data-migration','data-transaction','data-column']::text[], ARRAY['data-migration']::text[], 'data-normalization', ARRAY['a numbered schema change applied in sequence','the demo rows seeded into an empty database','a group of writes that all succeed or all reverse']::text[], 'a pronunciation ___ filled in missing say-it hints for the old acronym terms.', 'Use ''backfill'' in a sentence about updating existing database rows.', 'curated', 'curator', '2026-05-26'),
('data-column', 'column', null, 'databases', 'coding', 1, 'A named field that rows in a table can store.', 'A column defines one field across every row in a table. A terms table might have columns for id, term, definition, difficulty, and pronunciation. Each row supplies values for those columns.', 'the pronunciation column sits empty for terms that are said exactly as they''re spelled.', 'columns are the shape of your data: they decide what kind of value each record is even allowed to hold. knowing this is the difference between guessing at a record and knowing what fields it actually has.', ARRAY['data-table','data-row','data-primary-key','code-object']::text[], ARRAY['data-table','data-row']::text[], 'data-primary-key', ARRAY['one full record stored inside the drawer','the row id, such as an integer or slug','a reference pointing at a record in another drawer']::text[], 'the pronunciation ___ sits empty for terms that are said exactly as they''re spelled.', 'Use ''column'' in a sentence about a named database field.', 'curated', 'curator', '2026-05-26'),
('data-denormalization', 'denormalization', null, 'databases', 'coding', 3, 'Duplicating or reshaping data to make reads simpler or faster.', 'Denormalization intentionally duplicates or precomputes data so reads are easier or faster. A dashboard might store a cached count instead of recomputing it from many rows each time. Denormalization can improve performance, but it creates sync risk.', 'an analytics dashboard uses denormalization to store daily mastery totals instead of recomputing them every load.', 'sometimes engineers duplicate data on purpose to make reads faster, then spend effort keeping the copies in sync. understanding the speed-versus-drift tradeoff is what tells you when that bargain is worth it.', ARRAY['data-normalization','data-warehouse','cloud-cache','data-query-plan']::text[], ARRAY['data-normalization']::text[], 'data-warehouse', ARRAY['arranging data so each fact is stored exactly once','a store tuned for analysis over long history','a helper index that shortens lookup time']::text[], 'an analytics dashboard uses ___ to store daily mastery totals instead of recomputing them every load.', 'Use ''denormalization'' in a sentence about duplicating data for easier reads.', 'curated', 'curator', '2026-05-26'),
('data-foreign-key', 'foreign key', null, 'databases', 'coding', 2, 'A field that points to a row in another table.', 'A foreign key stores a reference to a row in another table. A user progress row might include user_id pointing at the users table and term_id pointing at the terms table. Foreign keys help databases keep relationships valid.', 'a progress record uses a foreign key to point at the term you just reviewed.', 'this is how separate tables connect without copying everything into one giant table. it''s the pointer that lets a progress record stay slim and still know exactly which term it''s about.', ARRAY['data-primary-key','data-join','data-row']::text[], ARRAY['data-primary-key']::text[], 'data-join', ARRAY['the field giving this record its own identity','a query step that combines two drawers into one result','a lookup aid that makes finding records faster']::text[], 'a progress record uses a ___ to point at the term you just reviewed.', 'Use ''foreign key'' in a sentence about one table pointing to another.', 'curated', 'curator', '2026-05-26'),
('data-index', 'index', null, 'databases', 'coding', 2, 'A structure that helps a database find rows faster.', 'An index is like a lookup structure the database maintains so it does not have to scan every row for common queries. Indexes speed reads but add cost to writes because the index must be updated too.', 'you put an index on the slug column so looking a term up stays fast as the table grows.', 'performance work on a database very often starts with how it finds rows. an index speeds up the reads you do constantly, at the cost of a little extra work on every write, so knowing when to add one is a real edge.', ARRAY['data-query-plan','data-table','data-column','sys-index']::text[], ARRAY['data-table','data-column']::text[], 'data-query-plan', ARRAY['a named field that every record can carry','a query step that merges rows from two drawers','the path an engine takes to answer a query']::text[], 'you put an ___ on the slug column so looking a term up stays fast as the table grows.', 'Use ''index'' in a sentence about speeding up database lookups.', 'curated', 'curator', '2026-05-26'),
('data-join', 'join', null, 'databases', 'coding', 2, 'A query operation that combines related tables.', 'A join lets a query combine rows from multiple tables using a relationship such as a foreign key. If progress rows store only term IDs, a join can pull in the term names and definitions at the same time.', 'a dashboard runs a join to show each mastered term right next to your score.', 'this is how apps build rich screens out of slim, normalized rows. when a progress record only stores a term id, a join is what pulls in the name and definition so the screen actually has something to show.', ARRAY['data-foreign-key','data-primary-key','data-query-plan']::text[], ARRAY['data-foreign-key']::text[], 'data-index', ARRAY['a reference one record holds toward another drawer','the field that singles out one record','the route an engine chooses to run one query']::text[], 'a dashboard runs a ___ to show each mastered term right next to your score.', 'Use ''join'' in a sentence about combining related database tables.', 'curated', 'curator', '2026-05-26'),
('data-lake', 'data lake', null, 'databases', 'coding', 3, 'Storage for large raw datasets in many shapes.', 'A data lake stores large amounts of raw or lightly processed data, often files, logs, events, exports, images, or semi-structured records. Warehouses usually organize data for querying; lakes keep more raw material for later processing, ML, or analytics.', 'a team dumps raw app events into a data lake first, then models them for analytics later.', 'some teams keep a huge, messy store of raw events and logs separate from their clean reporting tables. knowing why helps you see the split: lakes hold raw material for later, warehouses hold data already shaped for queries.', ARRAY['data-warehouse','data-denormalization']::text[], ARRAY['data-warehouse']::text[], 'ml-training-data', ARRAY['a database arranged for clean analysis questions','copying records deliberately for faster reads','storage that accelerates the most common lookups']::text[], 'a team dumps raw app events into a ___ first, then models them for analytics later.', 'Use ''data lake'' in a sentence about raw large-scale data storage.', 'curated', 'curator', '2026-05-26'),
('data-migration', 'migration', null, 'databases', 'coding', 2, 'A versioned change to database schema or data.', 'A migration is a recorded database change applied in order. It might add a table, add a column, create an index, insert seed content, or update existing rows. Migrations make database changes reviewable and repeatable.', 'a new content pack shipped as a migration so every database could apply it in the same order.', 'database changes move through numbered files instead of loose manual edits for a reason: it makes them reviewable and repeatable. once you get migrations, you understand why nobody just hand-edits the production schema.', ARRAY['data-backfill','data-transaction','flow-commit','sys-migration']::text[], ARRAY['data-table','data-column']::text[], 'data-backfill', ARRAY['a one-pass cleanup repairing records already stored','a batch of writes that all land or all roll back','the route an engine picks to run a query']::text[], 'a new content pack shipped as a ___ so every database could apply it in the same order.', 'Use ''migration'' in a sentence about a versioned database change.', 'curated', 'curator', '2026-05-26'),
('data-normalization', 'normalization', null, 'databases', 'coding', 3, 'Organizing data to reduce duplication and drift.', 'Normalization means structuring data so each fact has one clear home. Instead of copying customer details into every order row, the database stores customers once and lets orders point to them. Normalization reduces inconsistency but can require more joins.', 'normalization keeps each term definition in one table instead of copying it into every progress record.', 'this is the one-source-of-truth idea, and it''s why databases split related information across tables. store a fact once and point at it, and you stop fighting copies of the same value that quietly disagree.', ARRAY['data-denormalization','data-foreign-key','data-join','prod-system-of-record']::text[], ARRAY['data-foreign-key','data-join']::text[], 'data-denormalization', ARRAY['copying records on purpose so reads run faster','a query step that joins two related drawers','a store built for analysis across years of history']::text[], '___ keeps each term definition in one table instead of copying it into every progress record.', 'Use ''normalization'' in a sentence about reducing duplicated database facts.', 'curated', 'curator', '2026-05-26'),
('data-primary-key', 'primary key', null, 'databases', 'coding', 1, 'The unique identity field for a row.', 'A primary key uniquely identifies each row in a table. It might be a UUID, integer, slug, or stable text ID. Other rows can point at it, and the database uses it to know which record is which.', 'the term id is the primary key, so no two vocabulary records can ever be mixed up.', 'this is how a database avoids confusing one record with another. once you see that every row needs a stable identity, foreign keys and joins suddenly have something solid to hang on.', ARRAY['data-foreign-key','data-row','data-table']::text[], ARRAY['data-table','data-row']::text[], 'data-foreign-key', ARRAY['a reference pointing at a record in a separate drawer','a field that every record in the drawer shares','a saved lookup aid for the slug column']::text[], 'the term id is the ___, so no two vocabulary records can ever be mixed up.', 'Use ''primary key'' in a sentence about a unique row identity.', 'curated', 'curator', '2026-05-26'),
('data-query-plan', 'query plan', null, 'databases', 'coding', 2, 'The database strategy for running a query.', 'A query plan is the route a database chooses to answer a query. It decides which indexes to use, which tables to scan, what order to join tables, and how to filter rows. Slow queries are often diagnosed by reading the query plan.', 'the query plan showed the database scanning every row instead of using the index, which explained the slowdown.', 'a database doesn''t magically answer your SQL, it picks a route. when a query is slow, reading the query plan is usually how you find out it''s scanning every row instead of using the index you thought it would.', ARRAY['data-index','data-join','data-transaction']::text[], ARRAY['data-index','data-join']::text[], 'data-transaction', ARRAY['a lookup aid that speeds up finding records','a query step that combines two related drawers','a numbered file that changes the database shape']::text[], 'the ___ showed the database scanning every row instead of using the index, which explained the slowdown.', 'Use ''query plan'' in a sentence about how a database runs a query.', 'curated', 'curator', '2026-05-26'),
('data-row', 'row', null, 'databases', 'coding', 1, 'One record inside a database table.', 'A row is one individual record in a table. In a terms table, one row might be the term "webhook." In a user table, one row might be Alice. Rows hold values for the table''s columns.', 'one row in the terms table is the whole CORS lesson, definition and all.', 'it''s easy to blur the table (a whole collection) with a single item inside it. keeping "row" as the one-record word is what lets you reason precisely about which exact item a query touched.', ARRAY['data-table','data-column','data-primary-key']::text[], ARRAY['data-table']::text[], 'data-column', ARRAY['a named field every record in the drawer carries','a whole drawer of records sharing the same shape','the id value other rows use to find this one']::text[], 'one ___ in the terms table is the whole CORS lesson, definition and all.', 'Use ''row'' in a sentence about one database record.', 'curated', 'curator', '2026-05-26'),
('data-table', 'table', null, 'databases', 'coding', 1, 'A named collection of related database rows.', 'A table is where a database stores one kind of record. A terms table stores term records. A profiles table stores user profile records. Tables have columns that describe which fields each row can hold.', 'every vocabulary entry you study is just one entry in the terms table.', 'before app data becomes cards, screens, or reports, it lives in a table. picturing the table first is what makes the rest of the database make sense.', ARRAY['data-row','data-column','data-primary-key']::text[], ARRAY[]::text[], 'data-row', ARRAY['the field that singles out one record from the rest','a query step that pulls two related drawers together','one stored record inside the collection']::text[], 'every vocabulary entry you study is just one entry in the terms ___.', 'Use ''table'' in a sentence about where related database records live.', 'curated', 'curator', '2026-05-26'),
('data-transaction', 'transaction', null, 'databases', 'coding', 2, 'A group of database operations that succeed or fail together.', 'A transaction wraps multiple database operations so they commit as one unit or roll back as one unit. If accepting an invite needs to update several tables, a transaction prevents the system from doing half the work and leaving inconsistent state.', 'an invite-accept flow runs inside a transaction so profile creation and the allowlist update either both land or neither does.', 'when several changes belong together, a transaction is what stops the system from doing half the work and leaving inconsistent state. it''s the safety net behind any action that has to touch more than one table.', ARRAY['data-migration','data-backfill','prod-audit-log']::text[], ARRAY['data-row','data-table']::text[], 'data-migration', ARRAY['a numbered file that adds a column or table','a one-pass job that fixes records already stored','a side structure that quickens record lookups']::text[], 'an invite-accept flow runs inside a ___ so profile creation and the allowlist update either both land or neither does.', 'Use ''transaction'' in a sentence about database writes that succeed or fail together.', 'curated', 'curator', '2026-05-26'),
('data-warehouse', 'data warehouse', null, 'databases', 'coding', 3, 'A database organized for analytics instead of app transactions.', 'A data warehouse is built for analysis across lots of historical data. Product, finance, marketing, support, and operational data may be copied there so teams can run reports without slowing the production app database.', 'a company copies event data into a data warehouse so the weekly retention reports never touch the production app.', 'this is what separates the database that runs the app from the one used to study the business. it''s why a heavy weekly report can run without slowing down the live app.', ARRAY['data-lake','data-denormalization','prod-kpi','cloud-metric']::text[], ARRAY['data-table','data-denormalization']::text[], 'data-lake', ARRAY['storage for big piles of raw, unshaped data','the database that serves the live app''s writes','copying records on purpose to speed up reads']::text[], 'a company copies event data into a ___ so the weekly retention reports never touch the production app.', 'Use ''data warehouse'' in a sentence about analytics-oriented storage.', 'curated', 'curator', '2026-05-26'),
('sys-constraint', 'constraint', null, 'databases', 'coding', 2, 'A database rule that rejects data that does not fit.', 'A constraint is a rule the database enforces: a column cannot be null, an email must be unique, a foreign key must point to a real row, or a status must be one of a known set. Constraints catch bad data even when app code misses something.', 'you can add a unique constraint so the same email can''t get saved twice no matter how many times the form is submitted.', 'app code misses things, retries fire twice, two clients write at once. a constraint is the guardrail at the data layer that makes correctness survive all of that, so a duplicate email gets rejected even when the form lets it through.', ARRAY['data-column','data-primary-key','data-foreign-key','sys-enum']::text[], ARRAY['sys-schema','data-column']::text[], 'sys-transaction', ARRAY['the column holding the row id, like a UUID','a batch of writes that all commit or all roll back','a field limited to one pick from a set list']::text[], 'you can add a unique ___ so the same email can''t get saved twice no matter how many times the form is submitted.', 'Use ''constraint'' in a sentence about a database rule that rejects invalid data.', 'curated', 'curator', '2026-05-25'),
('sys-cursor', 'cursor', null, 'databases', 'coding', 2, 'A marker that tells an API where to continue fetching the next page.', 'A cursor is a bookmark for pagination. Instead of saying "give me page 3," the client says "continue after this last item." Cursor pagination is more stable when new rows are being added while someone is browsing, because it follows the data position rather than a fragile page number.', 'you can use the last-seen timestamp as a cursor so "load more" keeps working even as new items come in.', 'when new rows keep getting added while someone is browsing, page numbers go fragile fast. a cursor follows the data position instead, which is why "load more" stays reliable on feeds that never stop changing.', ARRAY['sys-pagination','sys-timestamp','sys-query-param']::text[], ARRAY['sys-pagination']::text[], 'sys-index', ARRAY['chopping a big result into numbered pages','a side index that makes row lookups faster','a field restricted to a fixed menu of options']::text[], 'you can use the last-seen timestamp as a ___ so "load more" keeps working even as new items come in.', 'Use ''cursor'' in a sentence about continuing a paginated API request.', 'curated', 'curator', '2026-05-25'),
('sys-enum', 'enum', 'EE-num', 'databases', 'coding', 2, 'A field whose value must be one option from a fixed list.', 'An enum is a controlled list of allowed values. A status might be draft, active, paused, or archived. Enums are useful when free-form text would create drift: "in progress," "In Progress," and "working" all meaning the same thing.', 'you can make order status an enum so the app only ever stores known states like draft, active, or archived.', 'free-form text drifts fast: "in progress," "In Progress," and "working" all end up meaning the same thing in your data. an enum pins a field to a known set of options so messy vocabulary never becomes messy data.', ARRAY['sys-constraint','data-column','sys-schema']::text[], ARRAY['data-column','sys-constraint']::text[], 'sys-schema', ARRAY['a saved date and time marking when something happened','a reference held by one record pointing at another drawer','a stored value standing for nothing entered yet']::text[], 'you can make order status an ___ so the app only ever stores known states like draft, active, or archived.', 'Use ''enum'' in a sentence about a field with a fixed list of allowed values.', 'curated', 'curator', '2026-05-25'),
('sys-null', 'null', null, 'databases', 'coding', 1, 'A database or programming value that means no value is present.', 'Null is not zero, false, or an empty string. It means the value is missing or not set. A nullable column allows null; a not-null column rejects it. Null bugs happen when code assumes a value exists and then meets nothing.', 'a profile can leave the nickname field as null until someone actually chooses to fill it in.', 'null is the difference between "nothing here yet" and "the person typed an empty answer." mixing those up is where a surprising number of bugs come from, so it''s worth knowing null isn''t zero, false, or an empty string.', ARRAY['data-column','sys-constraint','dev-typecheck']::text[], ARRAY['data-column']::text[], 'sys-constraint', ARRAY['a numeric zero saved inside a number field','a piece of text with zero characters in it','a field locked to a fixed menu of choices']::text[], 'a profile can leave the nickname field as ___ until someone actually chooses to fill it in.', 'Use ''null'' in a sentence about a missing database value.', 'curated', 'curator', '2026-05-25'),
('sys-pagination', 'pagination', null, 'databases', 'coding', 2, 'Splitting a large result set into smaller pages.', 'Pagination is how an app avoids loading every row at once. Instead of fetching 10,000 records, it asks for the first 50, then the next 50. Pagination can use page numbers, offsets, or cursors. It keeps screens fast and APIs sane.', 'you add pagination before a long list gets too big to load in one go.', 'nobody wants to load 10,000 records at once. pagination is the polite way to hand data over in chunks, and it''s what keeps a growing list from freezing the browser and hammering the database with one giant fetch.', ARRAY['sys-cursor','sys-query-param','sys-index','sys-timestamp']::text[], ARRAY['sys-query-param','data-row']::text[], 'sys-cursor', ARRAY['a bookmark marking where the next batch should begin','a lookup aid that shortens how long a search takes','a step that pulls two related drawers together']::text[], 'you add ___ before a long list gets too big to load in one go.', 'Use ''pagination'' in a sentence about loading records in smaller chunks.', 'curated', 'curator', '2026-05-25'),
('sys-seed-data', 'seed data', null, 'databases', 'coding', 1, 'Starter data loaded into a database so the app has something real to use.', 'Seed data is the baseline content a database starts with: starter terms, admin users, demo records, default settings. In this repo, the local seed mirrors curated cloud migrations so local resets still have the learning content.', 'you can add new vocabulary to seed data so a local reset still has the same lessons as the cloud.', 'an empty database isn''t a usable app. seed data is the baseline content that makes a fresh setup actually work, and it''s also how tests avoid depending on whatever happens to be live at the moment.', ARRAY['sys-migration','dev-fixture','data-table','data-backfill']::text[], ARRAY['data-table']::text[], 'sys-backfill', ARRAY['a cleanup pass that fixes records already stored','a numbered, replayable change to the database shape','a batch of writes that all go through or all reverse']::text[], 'you can add new vocabulary to ___ so a local reset still has the same lessons as the cloud.', 'Use ''seed data'' in a sentence about starter database content.', 'curated', 'curator', '2026-05-25'),
('sys-timestamp', 'timestamp', null, 'databases', 'coding', 1, 'A stored date and time for when something happened.', 'A timestamp records time in a structured way: created_at, updated_at, dismissed_at, accepted_at. Good timestamps make audits, ordering, stale-data checks, and user-facing histories possible. Time zones still matter, but the database needs a precise value first.', 'a dismissed_at timestamp tells you exactly when someone last closed a banner.', 'timestamps are how software remembers when. without created_at and updated_at on your rows, debugging turns into folklore and you can''t tell what happened before what.', ARRAY['data-row','data-column','data-backfill','sys-pagination']::text[], ARRAY['data-column']::text[], 'sys-pagination', ARRAY['the stable id other tables point back to','a menu of allowed status labels','a tally of how many records a drawer holds']::text[], 'a dismissed_at ___ tells you exactly when someone last closed a banner.', 'Use ''timestamp'' in a sentence about storing when something happened.', 'curated', 'curator', '2026-05-25'),
('sys-upsert', 'upsert', null, 'databases', 'coding', 2, 'A database write that inserts a row if it does not exist, or updates it if it does.', 'Upsert is insert plus update. It is useful when code wants one row per user, email, or key and does not know whether that row already exists. Good upserts need clear conflict rules so retries do not create duplicates.', 'you upsert the profile so a returning person updates their existing row instead of spawning a second one.', 'when you want exactly one row per user or key but don''t know if it already exists, an upsert saves you from checking first and racing. it''s one of the main moves behind safe, repeatable writes that don''t pile up duplicates on retry.', ARRAY['sys-idempotent','data-primary-key','data-transaction','sys-constraint']::text[], ARRAY['data-primary-key','sys-idempotent']::text[], 'sys-transaction', ARRAY['a step that fuses two related drawers in a query','a batch of writes that all apply or all undo together','a one-pass job that repairs older records']::text[], 'you ___ the profile so a returning person updates their existing row instead of spawning a second one.', 'Use ''upsert'' in a sentence about insert-or-update database writes.', 'curated', 'curator', '2026-05-25'),
('dev-codegen', 'codegen', null, 'dev-concepts', 'coding', 2, 'Generating code from another source of truth, like a schema, API spec, or design token registry.', 'Codegen is short for code generation. Instead of hand-writing repetitive files, a script reads a source of truth and writes the code for you: TypeScript types from a database schema, API clients from an OpenAPI spec, CSS variables from design tokens. The generated files should be treated as outputs, not places to do careful hand edits.', 'run codegen after the schema change so the TypeScript types know about the new column.', 'codegen is the reason some files should be regenerated, never hand-patched — they''re outputs from a schema, spec, or token registry. knowing that saves you from carefully editing a generated file only to watch the next run overwrite your changes.', ARRAY['dev-build','dev-dependency']::text[], ARRAY['dev-build']::text[], 'dev-monorepo', ARRAY['confirming code obeys its declared types before it runs','a review auto-opened off a pull request','a random string handed to a row as its primary key']::text[], 'run ___ after the schema change so the TypeScript types know about the new column.', 'Use ''codegen'' in a sentence about creating code from a schema or spec.', 'curated', 'curator', '2026-05-25'),
('dev-monorepo', 'monorepo', null, 'dev-concepts', 'coding', 2, 'One repository that holds multiple related apps, packages, or services together.', 'A monorepo is a single repo that contains more than one project: maybe the web app, shared UI package, backend functions, docs, and scripts all live together. The tradeoff is coordination. Shared code is easier to change in one place, but builds, tests, and ownership need more structure.', 'the whole ecosystem is basically a monorepo of related apps and shared packages.', 'when the web app, the shared ui package, the backend functions, and the docs all live near each other, monorepo is the word that makes that shape legible. it''s worth knowing because shared code gets easier to change while builds and ownership get harder — that tradeoff shapes a lot of decisions.', ARRAY['dev-repo','dev-package-manager','dev-dependency']::text[], ARRAY['dev-repo']::text[], 'dev-codegen', ARRAY['a repo holding exactly one commit and nothing more','a repo with just one app and no shared packages','a live server juggling several running containers']::text[], 'the whole ecosystem is basically a ___ of related apps and shared packages.', 'Use ''monorepo'' in a sentence about several related projects living in one repository.', 'curated', 'curator', '2026-05-25'),
('dev-typecheck', 'typecheck', null, 'dev-concepts', 'coding', 1, 'Checking whether the code obeys its declared TypeScript types before it runs.', 'A typecheck asks TypeScript to inspect the code without launching the app. It catches mismatches like passing a number where a string is expected, reading a property that might not exist, or returning the wrong shape from a function. It is one of the fastest ways to catch broken assumptions before a browser ever opens.', 'run the typecheck before the build so we catch that bad prop shape early.', 'when a build says "typecheck failed," it means the code is structurally inconsistent — a wrong shape, a missing property — not that the page looked off. knowing that distinction makes test output far less cryptic and points you at the real problem fast.', ARRAY['dev-build','dev-bug','dev-framework']::text[], ARRAY['dev-build']::text[], 'dev-codegen', ARRAY['running the app to confirm a feature behaves right','spell-checking the comments scattered through the source','tallying how many lines a pull request touched']::text[], 'run the ___ before the build so we catch that bad prop shape early.', 'Use ''typecheck'' in a sentence about TypeScript catching a shape mismatch.', 'curated', 'curator', '2026-05-25'),
('dev-build-artifact', 'build artifact', null, 'dev-tooling', 'coding', 1, 'A generated output file or folder produced by the build step.', 'A build artifact is the thing a build leaves behind: compiled JavaScript, CSS bundles, static assets, coverage reports, or a deployable `dist` folder. Source code is what humans edit; artifacts are what tools produce. If an artifact is stale, the app can show old behavior even after source files changed.', 'the change was in my code but the site didn''t update, the host was still serving an old build artifact from the last deploy.', 'when you fix a bug but the deployed site still shows the old behavior, it''s usually because the build artifact is stale, the server is still serving yesterday''s output. knowing this stops you from re-fixing code that was already right.', ARRAY['dev-build','dev-bundler','dev-source-map','ent-preview-deployment']::text[], ARRAY['dev-build']::text[], 'dev-source-map', ARRAY['the source file a developer edits directly','the config that tells the build tool what to do','the cached dependencies a build downloads to run']::text[], 'the change was in my code but the site didn''t update, the host was still serving an old ___ from the last deploy.', 'Use ''build artifact'' in a sentence about generated output from a build.', 'curated', 'curator', '2026-05-25'),
('dev-bundler', 'bundler', null, 'dev-tooling', 'coding', 2, 'A build tool that turns many source files into browser-ready assets.', 'A bundler follows imports through your app, collects the code and styles that are needed, transforms TypeScript or JSX, and writes browser-ready files. Vite uses Rollup for production builds. When an import path breaks or a dependency cannot be resolved, the bundler is often the thing complaining.', 'the bundler choked on a bad import path, so the whole app refused to compile until i fixed the filename.', 'when a build fails with ''cannot resolve import,'' the bundler is the thing complaining, and it''s usually right that a file path is wrong. reading its errors as a map of broken imports saves you a lot of guessing.', ARRAY['dev-build','dev-build-artifact','dev-source-map','dev-dependency']::text[], ARRAY['dev-build','dev-dependency']::text[], 'dev-source-map', ARRAY['the tool that installs your project''s dependencies','the dev server that reloads the app as you edit','the tool that rewrites code into a consistent style']::text[], 'the ___ choked on a bad import path, so the whole app refused to compile until i fixed the filename.', 'Use ''bundler'' in a sentence about turning source files into browser-ready assets.', 'curated', 'curator', '2026-05-25'),
('dev-component', 'component', null, 'dev-tooling', 'coding', 1, 'A reusable piece of UI with its own inputs, rendering, and sometimes state.', 'In React, a component is a function that returns UI. A button, version pill, quiz card, form, or whole route can be a component. Components receive inputs called props, may hold state, and re-render when their inputs or state change.', 'i pulled the repeated card markup into its own component so i could reuse it across both screens.', 'once you can see a screen as a set of named components instead of one giant page, frontend work stops feeling like a wall. a button, a card, a whole route, each is its own piece you can build and reason about on its own.', ARRAY['dev-props','dev-state','dev-hook','dev-framework']::text[], ARRAY['dev-frontend','dev-framework']::text[], 'dev-hook', ARRAY['an input value passed into a piece of UI','the live data a piece of UI remembers','a special function that hooks into React features']::text[], 'i pulled the repeated card markup into its own ___ so i could reuse it across both screens.', 'Use ''component'' in a sentence about a reusable React UI piece.', 'curated', 'curator', '2026-05-25'),
('dev-formatter', 'formatter', null, 'dev-tooling', 'coding', 1, 'A tool that rewrites code layout into a consistent style.', 'A formatter handles code shape: spaces, wrapping, commas, indentation, and line breaks. Prettier is the common JavaScript example. The goal is not taste; the goal is to stop humans and agents from spending review energy on whether a line should wrap.', 'i ran the formatter before committing so the diff would show the actual logic change and nothing else.', 'when a pull request shows fifty changed lines but only one actually does anything, it''s usually because nobody ran the formatter consistently. letting it own spacing and wrapping means your diffs show real changes, not arguments about indentation.', ARRAY['dev-linter','dev-typecheck','git-diff']::text[], ARRAY['dev-build']::text[], 'dev-linter', ARRAY['a tool that flags suspicious or buggy code patterns','a tool that checks types are consistent','a tool that bundles source files for the browser']::text[], 'i ran the ___ before committing so the diff would show the actual logic change and nothing else.', 'Use ''formatter'' in a sentence about consistent code layout.', 'curated', 'curator', '2026-05-25'),
('dev-hook', 'hook', null, 'dev-tooling', 'coding', 2, 'A React function that lets a component use state, effects, refs, or shared behavior.', 'A hook is a special React function like `useState`, `useEffect`, `useMemo`, or a custom `useSomething` helper. Hooks let function components remember state, run side effects, cache work, and share behavior without classes. Hook bugs often come from stale dependencies or doing async work in the wrong lifecycle moment.', 'i added a hook that listens for the escape key and closes the panel when it''s pressed.', 'modern react does most of its invisible work through hooks like useState and useEffect, so the word shows up constantly in explanations and bug reports. knowing it also helps you spot the classic trap: a hook misbehaving because its dependency list is stale.', ARRAY['dev-component','dev-state','dev-props','dev-linter']::text[], ARRAY['dev-component','dev-state']::text[], 'dev-hydration', ARRAY['an input passed down into a component','the live data a component keeps between renders','a reusable piece of UI that returns markup']::text[], 'i added a ___ that listens for the escape key and closes the panel when it''s pressed.', 'Use ''hook'' in a sentence about React state or effects inside a component.', 'curated', 'curator', '2026-05-25'),
('dev-hot-reload', 'hot reload', null, 'dev-tooling', 'coding', 1, 'A dev-server feature that updates the running app after a file changes.', 'Hot reload watches source files while the dev server is running. When you edit a component or CSS file, the browser updates without a full manual restart. It is a speed feature, not proof that the production build works. Sometimes a weird local state bug disappears after a hard refresh because hot reload preserved state that a real load would reset.', 'thanks to hot reload my color tweak showed up the second i saved, no restart needed.', 'hot reload is why editing a style and seeing it update instantly feels so good while developing. it''s also why a bug sometimes vanishes after a hard refresh, the reload kept some state alive that a real page load would have wiped, so don''t trust it as proof the build is fine.', ARRAY['dev-localhost','dev-server','dev-build','dev-state']::text[], ARRAY['dev-localhost','dev-server']::text[], 'dev-build', ARRAY['a full page refresh that resets all app state','the production build step that outputs final files','the bundler pass that resolves all the imports']::text[], 'thanks to ___ my color tweak showed up the second i saved, no restart needed.', 'Use ''hot reload'' in a sentence about a dev server updating after a file edit.', 'curated', 'curator', '2026-05-25'),
('dev-linter', 'linter', null, 'dev-tooling', 'coding', 1, 'A tool that flags suspicious code patterns before the app runs.', 'A linter scans source code for rules: unused variables, unsafe patterns, missing dependencies in React hooks, inconsistent imports, or code that violates the project style. It does not prove the app works, but it catches many small mistakes early and keeps the codebase from drifting into avoidable mess.', 'the linter flagged a variable i declared and never used, which made me realize i''d deleted the wrong line.', 'the linter is the thing that flags an unused variable or a missing hook dependency before you ever run the app. it feels fussy right up until one of its warnings turns out to be a real bug you would''ve shipped.', ARRAY['dev-formatter','dev-typecheck','dev-test-runner','agile-regression-test']::text[], ARRAY['dev-build']::text[], 'dev-typecheck', ARRAY['a tool that only reformats code spacing and layout','a tool that runs your tests and reports pass or fail','a tool that checks types match across the codebase']::text[], 'the ___ flagged a variable i declared and never used, which made me realize i''d deleted the wrong line.', 'Use ''linter'' in a sentence about a code-quality rule check.', 'curated', 'curator', '2026-05-25'),
('dev-lockfile', 'lockfile', null, 'dev-tooling', 'coding', 1, 'A file that pins the exact dependency versions a project installed.', 'A lockfile is the package manager''s receipt. `package.json` might say a project accepts version 4.x of a library, but the lockfile records the exact version actually installed, plus the versions of every dependency underneath it. That is how you, CI, Vercel, and another agent can install the same project and get the same dependency tree.', 'don''t gitignore the lockfile, or everyone ends up on slightly different versions and bugs get impossible to reproduce.', 'when something works on your laptop but breaks in CI and the app code didn''t change, the lockfile is the first place to look. it''s the difference between ''we might have installed the same versions'' and ''we definitely did.''', ARRAY['dev-package-manager','dev-dependency','dev-semver','dev-node-modules']::text[], ARRAY['dev-package-manager','dev-dependency']::text[], 'dev-transitive-dependency', ARRAY['the file that lists which dependencies a project wants','the cache folder a package manager downloads into','a config file that sets the package registry url']::text[], 'don''t gitignore the ___, or everyone ends up on slightly different versions and bugs get impossible to reproduce.', 'Use ''lockfile'' in a sentence about keeping installs identical across machines.', 'curated', 'curator', '2026-05-25'),
('dev-node-modules', 'node_modules', null, 'dev-tooling', 'coding', 1, 'The local folder where JavaScript dependencies are installed.', '`node_modules` is the big generated folder full of packages your app depends on. You do not edit it by hand and you usually do not commit it. If it is missing or stale, the project may fail to run until the package manager installs dependencies again.', 'my build kept failing on a missing package until i blew away node_modules and reinstalled from scratch.', 'the day a project mysteriously won''t start, deleting node_modules and reinstalling fixes it surprisingly often. knowing it''s generated machinery and not your code means you won''t panic when it''s huge or go editing files inside it.', ARRAY['dev-package-manager','dev-dependency','dev-lockfile']::text[], ARRAY['dev-package-manager']::text[], 'dev-lockfile', ARRAY['the file that pins exact installed dependency versions','the list of packages a project declares it needs','the registry a package manager downloads packages from']::text[], 'my build kept failing on a missing package until i blew away ___ and reinstalled from scratch.', 'Use ''node_modules'' in a sentence about installed JavaScript dependencies.', 'curated', 'curator', '2026-05-25'),
('dev-props', 'props', null, 'dev-tooling', 'coding', 1, 'Inputs passed into a component by whatever renders it.', 'Props are how one React component gives another component information. A quiz card might receive a term, a list of answer options, and an `onAnswer` function as props. Props should be treated like read-only inputs: the child uses them, but the parent owns the decision to pass them.', 'the card showed the wrong title because i passed the wrong term in as props, the component itself was fine.', 'when a component renders the wrong thing, the component is often innocent, the wrong props got passed in, so the real fix is in the parent. treating props as read-only inputs the parent owns saves you from debugging the wrong file.', ARRAY['dev-component','dev-state','dev-hook','dev-typecheck']::text[], ARRAY['dev-component']::text[], 'dev-state', ARRAY['the internal data a component changes over time','a function that lets a component use React features','global values shared across the whole app']::text[], 'the card showed the wrong title because i passed the wrong term in as ___, the component itself was fine.', 'Use ''props'' in a sentence about inputs passed into a React component.', 'curated', 'curator', '2026-05-25'),
('dev-semver', 'semantic versioning', 'SEM-ver', 'dev-tooling', 'coding', 2, 'The major.minor.patch version pattern used to signal how risky an update is.', 'Semantic versioning, often shortened to semver, uses versions like 2.4.1. The first number is major, the second is minor, and the third is patch. In theory, patch means bug fix, minor means backwards-compatible feature, and major means breaking change. In practice, it is a promise you still verify with tests.', 'by semantic versioning a jump from 2.x to 3.x signals a breaking change, so i pinned the version until i had time to test it.', 'when a dependency jumps from 2.4.1 to 3.0.0, semantic versioning is the heads-up that something might break and you should read the changelog before updating. it turns a scary-looking version bump into a rough risk level you can act on.', ARRAY['dev-lockfile','dev-dependency','dev-package-manager','dev-transitive-dependency']::text[], ARRAY['dev-dependency']::text[], 'dev-transitive-dependency', ARRAY['the file that records the exact version actually installed','the major-version-only tag attached to a git release','a date-based release scheme like 2026.05.31']::text[], 'by ___ a jump from 2.x to 3.x signals a breaking change, so i pinned the version until i had time to test it.', 'Use ''semantic versioning'' in a sentence about reading a dependency version number.', 'curated', 'curator', '2026-05-25'),
('dev-source-map', 'source map', null, 'dev-tooling', 'coding', 2, 'A file that connects bundled code back to the original source files for debugging.', 'A source map is a translation guide for debuggers. The browser may be running minified bundled JavaScript, but the source map lets DevTools point an error back to `src/routes/splash.tsx` line 42. Without it, production errors can point at unreadable generated code.', 'i couldn''t make sense of the crash until the source map traced it back to one specific line in the original file.', 'when a production error points at one unreadable line of minified gibberish, a source map is what turns it back into a real filename and line number you can actually open. without it, debugging a deployed crash is mostly squinting.', ARRAY['dev-bundler','dev-build-artifact','dev-build','agile-visual-qa']::text[], ARRAY['dev-build']::text[], 'dev-bundler', ARRAY['the generated bundle a source map points back to','a diagram of how routes connect in the app','the config that tells the bundler which files to include']::text[], 'i couldn''t make sense of the crash until the ___ traced it back to one specific line in the original file.', 'Use ''source map'' in a sentence about debugging bundled JavaScript.', 'curated', 'curator', '2026-05-25'),
('dev-state', 'state', null, 'dev-tooling', 'coding', 1, 'Data an app or component remembers and uses to render the current screen.', 'State is the live memory of the interface: whether a modal is open, which answer is selected, which user is signed in, or what text is in a form. When state changes, React re-renders the affected UI. Some state is local to one component; some lives in a store or database.', 'i tracked whether the menu was open in state so the icon could flip between the two views.', 'state is the answer to ''why did the screen change when i clicked that?'' whether a menu is open, which option is selected, what''s typed in a form, all of it is state, and it''s where a lot of subtle UI bugs quietly live.', ARRAY['dev-component','dev-props','dev-hook','dev-hot-reload']::text[], ARRAY['dev-component']::text[], 'dev-hook', ARRAY['an input handed to a component from its parent','a file produced by the build step','a function that lets a component tap into React features']::text[], 'i tracked whether the menu was open in ___ so the icon could flip between the two views.', 'Use ''state'' in a sentence about data a component remembers while rendering.', 'curated', 'curator', '2026-05-25'),
('dev-test-coverage', 'test coverage', null, 'dev-tooling', 'coding', 2, 'A measure of which code was touched by tests during a run.', 'Test coverage tells you which lines, branches, or functions executed while tests ran. High coverage can be useful, but it is not the same as high confidence: a test can touch code without asserting the important behavior. Coverage is a map of what got exercised, not a grade on whether the tests are meaningful.', 'our test coverage looked great at 90 percent, but half those lines ran without actually asserting anything useful.', 'high test coverage feels reassuring, but a test can run a line of code without ever checking it did the right thing. knowing coverage is a map of what got exercised, not a grade on confidence, keeps you from trusting a green number too much.', ARRAY['dev-test-runner','agile-regression-test','agile-visual-qa','dev-contract-test']::text[], ARRAY['dev-test-runner']::text[], 'agile-regression-test', ARRAY['the tool that finds and executes the test files','the share of users who completed a flow','a count of how many assertions a test makes']::text[], 'our ___ looked great at 90 percent, but half those lines ran without actually asserting anything useful.', 'Use ''test coverage'' in a sentence about what a test run exercised.', 'curated', 'curator', '2026-05-25'),
('dev-test-runner', 'test runner', null, 'dev-tooling', 'coding', 1, 'A tool that finds test files, runs them, and reports pass or fail.', 'A test runner is the program behind commands like `npm run test`. Vitest finds test files, sets up the environment, executes assertions, and reports which tests passed or failed. Playwright is a browser test runner for end-to-end checks. The tests are the recipes; the runner is the thing executing them.', 'the test runner went red, but it turned out the runner couldn''t start, not that any of my actual tests failed.', 'when someone says ''the test runner failed,'' it pays to know whether the app actually broke, the test setup broke, or the runner couldn''t even start. the term lets you ask the right follow-up instead of assuming the worst.', ARRAY['dev-test-harness','dev-test-coverage','agile-regression-test','dev-snapshot-test']::text[], ARRAY[]::text[], 'dev-test-coverage', ARRAY['the individual test files that describe expected behavior','a measure of which code the tests actually touched','a person who tries the app before it ships']::text[], 'the ___ went red, but it turned out the runner couldn''t start, not that any of my actual tests failed.', 'Use ''test runner'' in a sentence about a tool that executes tests.', 'curated', 'curator', '2026-05-25'),
('dev-transitive-dependency', 'transitive dependency', null, 'dev-tooling', 'coding', 2, 'A dependency your project gets indirectly because another dependency needs it.', 'A transitive dependency is not one you chose directly. Your app installs library A, library A installs library B, and now library B is part of your project too. Security alerts and build breaks often come from these indirect packages, which is why dependency trees can be deeper than the list in `package.json`.', 'the audit flagged a transitive dependency three layers deep, so we couldn''t just upgrade it directly, we had to bump the parent package.', 'when a security alert names a package you''ve never heard of, it''s almost always a transitive dependency, something pulled in by a library you actually chose. the term turns a confusing audit into a map of where the risky package is hiding.', ARRAY['dev-dependency','dev-package-manager','dev-lockfile','dev-semver']::text[], ARRAY['dev-dependency','dev-package-manager']::text[], 'dev-lockfile', ARRAY['a dependency you list directly in package.json','a dependency only needed while developing, not in production','a dependency bundled into the final build output']::text[], 'the audit flagged a ___ three layers deep, so we couldn''t just upgrade it directly, we had to bump the parent package.', 'Use ''transitive dependency'' in a sentence about an indirect package in a dependency tree.', 'curated', 'curator', '2026-05-25'),
('flow-artifact', 'artifact', null, 'dev-workflow', 'coding', 2, 'A generated file or bundle produced by a build.', 'An artifact is an output from a build or automation step: a bundled app, test report, coverage file, container image, source map, or downloadable package. Artifacts are generated outputs, not usually hand-edited source files.', 'the deploy pulls the artifact straight from the last passing build, so we never ship untested output.', 'an artifact is what a build spits out — the bundled app, the test report, the container image — and it''s what a deploy actually picks up and ships. when you grab the artifact from a passing run, you''re shipping the exact output that already passed the checks.', ARRAY['flow-build','flow-ci','cloud-image','dev-build-artifact']::text[], ARRAY['flow-build']::text[], 'cloud-deploy', ARRAY['the step that compiles source into a runnable app','the shared checks a server runs after each change','an independent development line kept off main']::text[], 'the deploy pulls the ___ straight from the last passing build, so we never ship untested output.', 'Use ''artifact'' in a sentence about a generated build output.', 'curated', 'curator', '2026-05-26'),
('flow-branch', 'branch', null, 'dev-workflow', 'coding', 1, 'A separate line of work in version control.', 'A branch lets work happen without changing the main line immediately. Developers create branches for fixes, experiments, PRs, or stacked work. The branch can later be merged, rebased, or discarded.', 'i''ll spin up a branch for the login fix so main stays clean while i work.', 'branches are how you try something risky without breaking what already works. when a teammate says ''do it on a branch,'' they''re telling you to keep your half-finished change off the main line until it''s ready.', ARRAY['flow-repository','flow-commit','flow-pull-request','flow-merge']::text[], ARRAY['flow-repository']::text[], 'flow-pull-request', ARRAY['the version-controlled home where a whole project lives','a saved snapshot of one change set plus a note','the act of folding two working lines back together']::text[], 'i''ll spin up a ___ for the login fix so main stays clean while i work.', 'Use ''branch'' in a sentence about a separate line of code work.', 'curated', 'curator', '2026-05-26'),
('flow-build', 'build', null, 'dev-workflow', 'coding', 1, 'Turning source code into runnable output.', 'A build turns source files into something the runtime can use: bundled JavaScript, compiled TypeScript, CSS assets, server output, or a container image. A build can fail even when the editor looks fine.', 'the build keeps failing on a missing import even though the page renders fine locally.', 'a build turns the source you wrote into something the runtime can actually run, and it can fail even when your editor looks perfectly happy. knowing the build broke tells you the problem is in producing the app, not in the code you were just reading.', ARRAY['flow-artifact','flow-ci','cloud-deploy','dev-build']::text[], ARRAY['flow-ci']::text[], 'flow-artifact', ARRAY['the automatic gates that run on every push','a generated file or package a finished build emits','a saved checkpoint of one batch of edits with a note']::text[], 'the ___ keeps failing on a missing import even though the page renders fine locally.', 'Use ''build'' in a sentence about turning source code into runnable output.', 'curated', 'curator', '2026-05-26'),
('flow-ci', 'CI', 'C-I', 'dev-workflow', 'coding', 1, 'Continuous Integration: automated checks that run after code changes.', 'CI stands for Continuous Integration. CI systems run builds, tests, linting, type checks, and other gates when code changes. Good CI catches problems before humans merge or deploy a broken branch.', 'i''ll wait for CI to finish before i merge, just in case a test fails on the server.', 'CI is the set of automated checks that run on every change so a broken branch doesn''t sneak into main. it''s why a green run on your laptop still isn''t enough — the shared checks have to pass before anyone merges.', ARRAY['flow-pull-request','flow-build','qa-regression-test','qa-test-coverage']::text[], ARRAY['flow-pull-request','qa-unit-test']::text[], 'flow-build', ARRAY['compiling written source into something runnable','a person reading a change before it lands','a generated bundle that a finished build spits out']::text[], 'i''ll wait for ___ to finish before i merge, just in case a test fails on the server.', 'Use ''CI'' in a sentence about automated checks after code changes.', 'curated', 'curator', '2026-05-26'),
('flow-code-review', 'code review', null, 'dev-workflow', 'coding', 1, 'Human or agent inspection of proposed code changes.', 'Code review means reading a change before it lands to look for bugs, missing tests, unclear design, risky behavior, and maintainability problems. It often happens on a pull request, but it can also happen locally or in an agent thread.', 'during code review i flagged two spots where the error handling looked off.', 'code review is the second pair of eyes that catches the bug, the missing test, or the unclear name before it ships. when a reviewer leaves comments on your change, they''re inspecting the work independently from whoever wrote it.', ARRAY['flow-pull-request','flow-diff','qa-regression-test','flow-ci']::text[], ARRAY['flow-diff','flow-pull-request']::text[], 'qa-regression-test', ARRAY['the automated gates that fire on every push','the bundle that packages a branch for folding in','the changed lines shown side by side for two versions']::text[], 'during ___ i flagged two spots where the error handling looked off.', 'Use ''code review'' in a sentence about inspecting proposed changes.', 'curated', 'curator', '2026-05-26'),
('flow-commit', 'commit', null, 'dev-workflow', 'coding', 1, 'A saved snapshot of code changes with a message.', 'A commit records a specific set of file changes in Git history. It has an id, author, timestamp, and message. Good commits make progress reviewable and reversible because each one explains what changed and why.', 'i made one commit for the bug fix and another for the test that proves it.', 'a commit is the unit of ''i saved my progress, here''s what changed and why.'' when you can read the commit history, you can see exactly how the code got to where it is instead of guessing from the current folder.', ARRAY['flow-branch','flow-diff','flow-pull-request']::text[], ARRAY['flow-branch']::text[], 'flow-diff', ARRAY['a parallel line of development off the main line','the set of added and removed lines between versions','a labeled marker pinned to a release point']::text[], 'i made one ___ for the bug fix and another for the test that proves it.', 'Use ''commit'' in a sentence about saving code changes into history.', 'curated', 'curator', '2026-05-26'),
('flow-conflict', 'merge conflict', null, 'dev-workflow', 'coding', 2, 'A place where Git cannot automatically combine changes.', 'A merge conflict happens when Git sees competing edits and cannot safely choose the right result. Someone must inspect the conflict markers, keep the correct lines, remove the markers, and rerun verification.', 'we both edited the same function, so now there''s a merge conflict i have to resolve by hand.', 'a merge conflict is git telling you it can''t safely pick between two competing edits, so a human has to decide. you''ll hit one when you and a teammate change the same lines, and you have to sort out which version wins.', ARRAY['flow-merge','flow-rebase','flow-diff','flow-branch']::text[], ARRAY['flow-merge','flow-rebase']::text[], 'flow-rebase', ARRAY['folding two branches cleanly into a single line','moving commits to sit on top of a newer base','the side-by-side added and removed lines per version']::text[], 'we both edited the same function, so now there''s a ___ i have to resolve by hand.', 'Use ''merge conflict'' in a sentence about Git needing a human combine decision.', 'curated', 'curator', '2026-05-26'),
('flow-debugger', 'debugger', null, 'dev-workflow', 'coding', 2, 'A tool for pausing code and inspecting state while it runs.', 'A debugger lets a developer set breakpoints, pause execution, inspect variables, step through code, and understand why behavior is happening. It is different from logs because it lets you stop inside the running program.', 'i set a breakpoint and let the debugger show me what the state looked like right before it crashed.', 'a debugger lets you freeze the running program and look at exactly what the variables hold, instead of sprinkling print statements and guessing. when logs aren''t enough to explain the bug, you drop a breakpoint and step through it line by line.', ARRAY['flow-localhost','cloud-log','qa-root-cause','code-stack-trace']::text[], ARRAY['flow-localhost','code-stack-trace']::text[], 'qa-root-cause', ARRAY['a printed line a program writes while running','the captured trace of an error unwinding','a tool that pauses code on a fixed timer']::text[], 'i set a breakpoint and let the ___ show me what the state looked like right before it crashed.', 'Use ''debugger'' in a sentence about pausing code and inspecting state.', 'curated', 'curator', '2026-05-26'),
('flow-diff', 'diff', null, 'dev-workflow', 'coding', 1, 'The visible change between two versions of files.', 'A diff shows what lines were added, removed, or changed between two versions. Code review usually starts by reading the diff, because it makes the actual change visible without rereading the whole project.', 'the diff is tiny, just three lines changed in one file, so it''s a quick review.', 'reviewing a diff is how you see what actually changed without rereading the whole project. when someone asks you to ''look at the diff,'' they want your eyes on the added and removed lines, not a summary you have to trust.', ARRAY['flow-commit','flow-code-review','flow-pull-request']::text[], ARRAY['flow-commit']::text[], 'flow-code-review', ARRAY['a recorded snapshot of one batch of edits','a branch packaged up and proposed for review','an independent line of work kept off main']::text[], 'the ___ is tiny, just three lines changed in one file, so it''s a quick review.', 'Use ''diff'' in a sentence about comparing file changes.', 'curated', 'curator', '2026-05-26'),
('flow-localhost', 'localhost', null, 'dev-workflow', 'coding', 1, 'The developer machine addressed as a local server.', 'Localhost is a hostname that points back to the same machine you are using. When a dev server runs at localhost:5173, the browser is talking to a server on your own computer, not the public internet.', 'it loads fine on localhost, but let me check the preview url before i call it done.', 'localhost is your own machine pretending to be a server, so what you see there is private to you and nobody else. it''s the difference between ''works on my computer'' and ''works on the deployed preview the whole team can hit.''', ARRAY['flow-port','cloud-environment','sys-origin','dev-localhost']::text[], ARRAY['cloud-environment']::text[], 'flow-port', ARRAY['a numbered slot a service listens on','the shared preview link teammates can open','the public internet address of a live server']::text[], 'it loads fine on ___, but let me check the preview url before i call it done.', 'Use ''localhost'' in a sentence about a local dev server.', 'curated', 'curator', '2026-05-26'),
('flow-merge', 'merge', null, 'dev-workflow', 'coding', 1, 'Combining changes from one branch into another.', 'A merge brings branch changes into another branch. Git tries to combine the histories and file changes automatically. If two branches changed the same area differently, a merge conflict may need a human decision.', 'once the checks are green you can merge it into main and delete the branch.', 'merging is the moment your proposed work actually becomes part of the shared line everyone builds on. when someone says ''go ahead and merge it,'' the review is done and your branch is joining main.', ARRAY['flow-branch','flow-pull-request','flow-conflict','flow-rebase']::text[], ARRAY['flow-branch','flow-pull-request']::text[], 'flow-conflict', ARRAY['replaying a branch''s commits onto a newer base','a proposal opened so others can review code first','a recorded checkpoint of one edit set with a note']::text[], 'once the checks are green you can ___ it into main and delete the branch.', 'Use ''merge'' in a sentence about combining branch changes.', 'curated', 'curator', '2026-05-26'),
('flow-port', 'port', null, 'dev-workflow', 'coding', 1, 'A number that lets multiple local services listen separately.', 'A port is a numbered endpoint on a machine. Local dev servers, databases, and APIs can all run on the same computer because each listens on a different port, such as 5173, 3000, or 5432.', 'the dev server grabbed port 5173, so i ran the second project on 3000 instead.', 'a port is the number that lets several services run on one machine without colliding — the app on 5173, the database on 5432. when something says ''port already in use,'' two things are fighting for the same number and one has to move.', ARRAY['flow-localhost','net-port','sys-origin','os-process']::text[], ARRAY['flow-localhost','net-port']::text[], 'sys-origin', ARRAY['the machine itself reached as a local server','the public web address of a deployed site','a generated package that a finished build emits']::text[], 'the dev server grabbed ___ 5173, so i ran the second project on 3000 instead.', 'Use ''port'' in a sentence about multiple services listening on one machine.', 'curated', 'curator', '2026-05-26'),
('flow-pull-request', 'pull request (PR)', 'P-R or pull request', 'dev-workflow', 'coding', 1, 'A reviewable proposal to merge code changes.', 'PR stands for pull request. A pull request packages branch changes for review before they merge into another branch, usually main. It shows commits, diffs, tests, discussion, approvals, and merge status.', 'i opened a pull request (PR) this morning, so take a look and approve it if the tests pass.', 'a pull request is where a code change goes to get looked at before it lands. when you open a pull request (PR), you''re saying ''here''s my branch, review it, run the checks, then we merge'' — it''s the spot where review, checks, and discussion all happen.', ARRAY['flow-branch','flow-code-review','flow-ci','flow-merge']::text[], ARRAY['flow-branch','flow-commit']::text[], 'flow-code-review', ARRAY['one saved checkpoint already sitting in history','replaying your commits on top of a fresher base','the added and changed lines between two file states']::text[], 'i opened a ___ this morning, so take a look and approve it if the tests pass.', 'Use ''PR'' or ''pull request'' in a sentence about proposing code for review.', 'curated', 'curator', '2026-05-26'),
('flow-rebase', 'rebase', null, 'dev-workflow', 'coding', 2, 'Moving commits onto a newer base branch.', 'A rebase takes commits from one branch and replays them on top of another base, often the latest main. Rebasing can make history linear and update a branch without a merge commit, but it can also require resolving conflicts carefully.', 'main moved a lot this week, so i need to rebase my branch before opening the PR.', 'a rebase moves your commits on top of the latest main so your branch isn''t built on stale ground. it''s why a branch that was current yesterday suddenly needs updating before it can merge cleanly today.', ARRAY['flow-branch','flow-commit','flow-merge','flow-conflict']::text[], ARRAY['flow-branch','flow-commit']::text[], 'flow-conflict', ARRAY['folding two branches together with a merge commit','a spot where the tool cannot auto-combine edits','a feature line split off from the shared trunk']::text[], 'main moved a lot this week, so i need to ___ my branch before opening the PR.', 'Use ''rebase'' in a sentence about moving commits onto a newer base.', 'curated', 'curator', '2026-05-26'),
('flow-repository', 'repository', 'repo', 'dev-workflow', 'coding', 1, 'The version-controlled home for a codebase.', 'A repository, often shortened to repo, is the folder and history for a project tracked by version control. It contains files, commits, branches, tags, and the story of how the code changed. A repo may live locally, on GitHub, or in both places.', 'go ahead and clone the repository, then you''ll have the whole history on your machine.', 'when someone says ''push it to the repo'' or ''clone the repository,'' they mean the version-controlled home of the project. you can''t talk about branches, commits, or pull requests until you know where the code actually lives.', ARRAY['flow-branch','flow-commit','git-remote','dev-repo']::text[], ARRAY['dev-repo']::text[], 'flow-branch', ARRAY['a single saved snapshot of one set of edits','a separate working line split off for a feature','the line-by-line change shown between two file versions']::text[], 'go ahead and clone the ___, then you''ll have the whole history on your machine.', 'Use ''repository'' or ''repo'' in a sentence about a version-controlled project.', 'curated', 'curator', '2026-05-26'),
('ent-deployment-alias', 'deployment alias', null, 'enterprise', 'coding', 2, 'A stable URL that points at a particular deployment, even when the raw deployment URL changes.', 'A deployment alias is a friendly or stable URL assigned to a deployed build. The underlying deployment may have a long generated URL, but the alias can point reviewers to the right one. Aliases are useful when you want "open the stack preview" to mean one current link instead of hunting through many deployment URLs.', 'point the review deployment alias at the newest build so the link in the PR doesn''t go stale on people.', 'the raw url for a build is a long generated string that changes every time. a deployment alias is a stable link you can paste once and trust, so "open the latest preview" always points at the current build instead of one from yesterday.', ARRAY['ent-preview-deployment','ent-stack-preview','dev-deploy']::text[], ARRAY['ent-preview-deployment']::text[], null, ARRAY['the long auto-generated url that comes with one specific build','a purchased custom domain wired to the live app','the branch name your terminal prompt happens to show']::text[], 'point the review ___ at the newest build so the link in the PR doesn''t go stale on people.', 'Use ''deployment alias'' in a sentence about a stable preview URL.', 'curated', 'curator', '2026-05-25'),
('ent-draft-pr', 'draft PR', null, 'enterprise', 'coding', 1, 'A pull request opened for visibility before it is ready for final review or merge.', 'A draft PR says "look if you want, but do not treat this as final yet." Developers use it to show direction early, get CI running, collect comments, or share a preview while the branch is still in progress. On GitHub, a draft PR cannot be merged until it is marked ready.', 'i pushed a draft PR so you can watch the direction take shape while i keep filling in the empty states.', 'sometimes you want eyes on a direction without anyone thinking it''s finished. opening a draft PR is how you say "look if you want, but this isn''t ready to merge yet" so people can comment early without confusing visible with done.', ARRAY['git-pr','ent-preview-deployment','agile-acceptance-criteria']::text[], ARRAY['git-pr']::text[], 'ent-stacked-pr', ARRAY['a pull request that has already landed on the main branch','a pull request stuck behind one failing required check','a release branch cut straight from the newest tag']::text[], 'i pushed a ___ so you can watch the direction take shape while i keep filling in the empty states.', 'Use ''draft PR'' in a sentence about showing in-progress work before final review.', 'curated', 'curator', '2026-05-25'),
('ent-preview-deployment', 'preview deployment', null, 'enterprise', 'coding', 1, 'A temporary live build of a branch so reviewers can click around before it merges.', 'A preview deployment is a real hosted copy of the app created from a non-main branch. Vercel, Netlify, and similar hosts make one automatically for each PR or branch. It is not production, but it is close enough to catch layout, auth, routing, and copy issues that a diff will not show you.', 'the preview deployment is up, so pull it open on your phone before we merge anything.', 'you review with your eyes, not by reading a diff. a preview deployment gives you a real hosted copy of the branch so you can open it on your phone and catch the layout, login, and routing problems a code diff would never show you.', ARRAY['git-pr','ent-stack-preview','ent-deployment-alias']::text[], ARRAY['git-pr','dev-deploy']::text[], 'ent-deployment-alias', ARRAY['a dev server running locally on one person''s laptop','a still screenshot pasted into the pull request thread','the live build that is currently serving real users']::text[], 'the ___ is up, so pull it open on your phone before we merge anything.', 'Use ''preview deployment'' in a sentence about clicking a branch before it merges.', 'curated', 'curator', '2026-05-25'),
('ent-stack-preview', 'stack preview', null, 'enterprise', 'coding', 2, 'A combined preview branch or deployment that shows what several PR branches look like together.', 'A stack preview is not a standard Git object. It is a review workflow: take several PR branches that are still separate for review, combine them into one branch, and deploy that combined branch so you can see the app as if all of them had merged. It answers a different question than any single PR: "do these changes feel right together?"', 'open the stack preview and you''ll see the new login, the version pill, and the mobile fixes all running together.', 'diffs tell you what each branch changed, but not how the changes feel together. when you want to answer "do all three of these land okay side by side?" a stack preview is the surface that lets you click through them as one app before any of them merge.', ARRAY['ent-stacked-pr','ent-preview-deployment','git-merge']::text[], ARRAY['git-pr','ent-preview-deployment']::text[], 'ent-deployment-alias', ARRAY['a hosted build made from one single branch on its own','the list of branches still sitting in the review queue','a screen recording captured right after a styling change']::text[], 'open the ___ and you''ll see the new login, the version pill, and the mobile fixes all running together.', 'Use ''stack preview'' in a sentence about seeing several pending PRs together.', 'curated', 'curator', '2026-05-25'),
('ent-stacked-pr', 'stacked PR', null, 'enterprise', 'coding', 2, 'A pull request that depends on another pull request landing before it.', 'A stacked PR is part of a chain. PR #2 is built on top of PR #1, PR #3 is built on top of PR #2, and so on. Stacking lets a developer break one big change into reviewable pieces while still building toward the larger feature. The catch is bookkeeping: if a lower PR changes, everything above it may need a rebase.', 'this visual pass is a stacked PR on the oauth branch, so review the oauth one first or my diff won''t make sense.', 'when a reviewer says "review them in order, the second one sits on top of the first," they mean a stack. knowing this saves you from reviewing pieces out of sequence and getting confused about why changes you expected are missing from the lower pull request.', ARRAY['git-pr','git-rebase','ent-draft-pr']::text[], ARRAY['git-pr','git-branch']::text[], 'ent-stack-preview', ARRAY['one big pull request that touches many unrelated files at once','two pull requests opened against two different repositories','a pull request a bot merged automatically once checks went green']::text[], 'this visual pass is a ___ on the oauth branch, so review the oauth one first or my diff won''t make sense.', 'Use ''stacked PR'' in a sentence about a pull request that depends on an earlier one.', 'curated', 'curator', '2026-05-25'),
('prod-acceptance-criteria', 'acceptance criteria', null, 'enterprise', 'coding', 2, 'Conditions that define when work is done.', 'Acceptance criteria are specific checks that must be true before a story or ticket counts as complete. They can cover behavior, edge cases, copy, accessibility, performance, data, and verification evidence.', 'the acceptance criteria require both mobile and desktop layouts to pass visual qa before we call it shipped.', '"make it good" can''t be tested; "passes visual qa on mobile and desktop" can. acceptance criteria turn a fuzzy request into a checklist everyone agrees on, so done means done instead of an argument later.', ARRAY['prod-story','se-requirement','se-verification','qa-e2e-test']::text[], ARRAY['prod-story','se-requirement']::text[], 'se-verification', ARRAY['a user-shaped sentence describing the behavior you want','the queue of work still waiting for someone to start it','a metric tracked to gauge how the business is doing']::text[], 'the ___ require both mobile and desktop layouts to pass visual qa before we call it shipped.', 'Use ''acceptance criteria'' in a sentence about conditions for done.', 'curated', 'curator', '2026-05-26'),
('prod-audit-log', 'audit log', null, 'enterprise', 'coding', 2, 'A record of who did what and when.', 'An audit log records important actions with actor, time, target, and details. It helps teams answer questions such as who changed this setting, who accessed this record, what integration fired, and what happened before an incident.', 'the audit log showed exactly who accepted the invite and the timestamp, which settled the whole question.', 'after an incident, the first question is "who changed this and when?" an audit log is what lets a system answer that, recording actor, time, and action so you can reconstruct what happened instead of guessing.', ARRAY['prod-compliance','cloud-log','prod-system-of-record','sec-permission']::text[], ARRAY['cloud-log']::text[], 'prod-compliance', ARRAY['the live stream of runtime errors the app throws','the public list of changes shipped in each release','the queue of work nobody has started yet']::text[], 'the ___ showed exactly who accepted the invite and the timestamp, which settled the whole question.', 'Use ''audit log'' in a sentence about recording who did what and when.', 'curated', 'curator', '2026-05-26'),
('prod-backlog', 'backlog', null, 'enterprise', 'coding', 1, 'The queue of work not yet done.', 'A backlog is the ordered or unordered collection of possible work: bugs, improvements, chores, ideas, research, and requests. A healthy backlog is curated; an unhealthy one becomes a junk drawer nobody trusts.', 'our backlog has five visual qa fixes and three content gaps, but only the qa ones are scheduled.', '"it''s in the backlog" can mean we''re doing it next or we''ll never touch it again. knowing the word helps you hear the difference between something that''s genuinely planned and something that was just captured so the asker would stop asking.', ARRAY['prod-ticket','prod-roadmap','prod-epic','prod-story']::text[], ARRAY['prod-ticket']::text[], 'prod-ticket', ARRAY['the set of tickets a team locked in for this sprint','the dated plan of which releases ship in which order','a single ticket already assigned to one owner']::text[], 'our ___ has five visual qa fixes and three content gaps, but only the qa ones are scheduled.', 'Use ''backlog'' in a sentence about queued product or engineering work.', 'curated', 'curator', '2026-05-26'),
('prod-compliance', 'compliance', null, 'enterprise', 'coding', 2, 'Meeting required rules, policies, contracts, or standards.', 'Compliance means satisfying rules that come from law, contracts, internal policy, security standards, privacy expectations, or industry requirements. In software, compliance often affects logging, access control, retention, auditability, approvals, and data handling.', 'compliance is why the app has to keep an audit log of every admin change, not just nice-to-have history.', 'some enterprise work isn''t optional polish, it''s required by law, contract, or policy with consequences for skipping it. knowing the word helps you tell "nice to have" apart from "we literally cannot ship without this" when the requirement is compliance.', ARRAY['prod-audit-log','sec-permission','prod-sso','prod-erp']::text[], ARRAY['prod-audit-log','sec-permission']::text[], 'sec-threat-model', ARRAY['the timestamped trail of who changed what and when','handing out access to people based on their role','hitting a contracted uptime number for customers']::text[], '___ is why the app has to keep an audit log of every admin change, not just nice-to-have history.', 'Use ''compliance'' in a sentence about meeting required rules or standards.', 'curated', 'curator', '2026-05-26'),
('prod-crm', 'CRM', 'C-R-M', 'enterprise', 'coding', 2, 'Customer relationship management software for customer accounts and sales activity.', 'CRM stands for customer relationship management. A CRM stores accounts, contacts, deals, notes, sales stages, support context, and customer interactions. Salesforce and HubSpot are common examples.', 'the sales team checked the CRM for the account history before they looped engineering in on the escalation.', 'when a customer escalation lands, the sales team doesn''t ping engineering first, they open the CRM. knowing the word tells you where the business keeps the history of who a customer is and everything that''s happened with their account.', ARRAY['prod-system-of-record','ent-salesforce','ent-hubspot','prod-audit-log']::text[], ARRAY['prod-system-of-record']::text[], 'prod-system-of-record', ARRAY['software running finance, inventory, and operations together','the agreed authoritative source for one kind of data','a help-desk system that tracks support tickets and replies']::text[], 'the sales team checked the ___ for the account history before they looped engineering in on the escalation.', 'Use ''CRM'' in a sentence about customer account and sales tracking software.', 'curated', 'curator', '2026-05-26'),
('prod-epic', 'epic', null, 'enterprise', 'coding', 2, 'A larger body of related product work.', 'An epic groups multiple stories, tickets, or tasks under one larger outcome. It is bigger than a single ticket but smaller and more concrete than a whole strategy. Epics help teams plan, estimate, and communicate progress across related work.', 'the learning-content epic pulls together the ml, systems, qa, and pm vocabulary packs under one outcome.', 'when a dozen tickets all serve one bigger outcome, an epic is the bucket that ties them together. it''s how you explain why scattered tasks belong to the same goal without pretending they''re a whole company strategy.', ARRAY['prod-story','prod-ticket','prod-milestone','prod-roadmap']::text[], ARRAY['prod-ticket','prod-roadmap']::text[], 'prod-story', ARRAY['a single user-shaped description of one desired behavior','the whole multi-quarter strategy for a company','a checkpoint that marks the end of one phase of work']::text[], 'the learning-content ___ pulls together the ml, systems, qa, and pm vocabulary packs under one outcome.', 'Use ''epic'' in a sentence about a larger body of related work.', 'curated', 'curator', '2026-05-26'),
('prod-erp', 'ERP', 'E-R-P', 'enterprise', 'coding', 2, 'Enterprise resource planning software for finance, inventory, operations, and planning.', 'ERP stands for enterprise resource planning. An ERP is the backbone system many large companies use for finance, procurement, inventory, HR, supply chain, and operational planning. SAP and Oracle are common examples.', 'the warehouse integration stalled on the ERP because the real inventory counts only lived there.', 'ever wonder why a simple integration takes months at a big company? often it''s waiting on the ERP, the giant slow backbone where finance and inventory actually live. knowing the word explains why some data doesn''t sit in a friendly little app database.', ARRAY['prod-system-of-record','ent-sap','ent-oracle','prod-compliance']::text[], ARRAY['prod-system-of-record']::text[], 'prod-compliance', ARRAY['software tracking customer accounts and sales deals','the trusted master copy other systems read one data type from','the identity service handling company-wide sign-on']::text[], 'the warehouse integration stalled on the ___ because the real inventory counts only lived there.', 'Use ''ERP'' in a sentence about enterprise finance, inventory, or operations software.', 'curated', 'curator', '2026-05-26'),
('prod-kpi', 'KPI', 'K-P-I', 'enterprise', 'coding', 2, 'Key performance indicator: a metric used to track business health.', 'KPI stands for key performance indicator. A KPI is a chosen business metric that signals whether something important is moving in the right direction: retention, conversion, revenue, activation, support response time, or churn.', 'weekly active learners is our KPI for whether the learning loop is actually working.', 'in any leadership conversation, a few numbers get treated as signal and the rest as noise. knowing which metric is a KPI tells you what the room actually steers by, so you can argue about the right number instead of a vanity one.', ARRAY['prod-okr','cloud-metric','prod-roadmap','qa-slo']::text[], ARRAY['cloud-metric']::text[], 'prod-okr', ARRAY['a stated objective backed by several key results','a contractual uptime promise made to paying customers','any raw count of events the app happens to log']::text[], 'weekly active learners is our ___ for whether the learning loop is actually working.', 'Use ''KPI'' in a sentence about a key business metric.', 'curated', 'curator', '2026-05-26'),
('prod-milestone', 'milestone', null, 'enterprise', 'coding', 1, 'A named checkpoint for a body of work.', 'A milestone groups work around a target such as a launch, review date, demo, release, or phase boundary. It helps teams see whether a larger body of work is on track without treating every ticket as equally important.', 'our beta milestone covers sign-in, lesson playback, and basic progress tracking, and we''re two tickets short of it.', 'when work spans dozens of tickets, you need a way to ask "are we actually close?" a milestone is the checkpoint that answers that, so progress gets measured against a target like a launch instead of by counting tasks.', ARRAY['prod-roadmap','prod-epic','prod-ticket','flow-pull-request']::text[], ARRAY['prod-roadmap']::text[], 'prod-epic', ARRAY['the full planned sequence of releases stretching over time','one single trackable bug, request, or task','an unordered pile of ideas nobody has scheduled']::text[], 'our beta ___ covers sign-in, lesson playback, and basic progress tracking, and we''re two tickets short of it.', 'Use ''milestone'' in a sentence about a named checkpoint for work.', 'curated', 'curator', '2026-05-26'),
('prod-okr', 'OKR', 'O-K-R', 'enterprise', 'coding', 2, 'Objectives and key results: a goal-setting format that links outcomes to measures.', 'OKR stands for objectives and key results. The objective names the qualitative aim; key results name measurable outcomes that show progress. A good OKR says what the team is trying to accomplish, not just which tasks it will do.', 'our OKR pairs the objective of making the app genuinely useful with key results on lesson completion and retention.', 'a task list tells you what you''ll do; an OKR makes you say what it''s supposed to change. when planning starts, knowing this format helps you separate "we shipped the thing" from "the thing actually moved the number we cared about."', ARRAY['prod-kpi','prod-roadmap','prod-milestone','cloud-metric']::text[], ARRAY['prod-kpi']::text[], 'prod-roadmap', ARRAY['one headline number watched on a dashboard over time','a ranked wish list of features waiting to be built','a labeled checkpoint that closes one phase of work']::text[], 'our ___ pairs the objective of making the app genuinely useful with key results on lesson completion and retention.', 'Use ''OKR'' in a sentence about an objective and measurable key results.', 'curated', 'curator', '2026-05-26'),
('prod-roadmap', 'roadmap', null, 'enterprise', 'coding', 1, 'A planned sequence of product bets, releases, or capability work.', 'A roadmap is a directional plan for what a team expects to build or improve over time. Good roadmaps explain priorities, order, uncertainty, and why the work matters. They are not the same as a fixed promise unless the team explicitly treats them that way.', 'our roadmap puts mobile onboarding ahead of the team dashboard, but none of those dates are promises yet.', 'the first time someone treats your roadmap like a signed delivery contract, you''ll wish you''d named it as direction. knowing the word helps you say "this is the order we''re betting on, not a set of dates" before expectations harden.', ARRAY['prod-milestone','prod-backlog','prod-epic','prod-okr']::text[], ARRAY['prod-milestone']::text[], 'prod-milestone', ARRAY['the ordered queue of work nobody has picked up yet','a named checkpoint that wraps up one phase of work','an objective paired with a few measurable key results']::text[], 'our ___ puts mobile onboarding ahead of the team dashboard, but none of those dates are promises yet.', 'Use ''roadmap'' in a sentence about planned product direction.', 'curated', 'curator', '2026-05-26'),
('prod-sso', 'enterprise SSO', 'S-S-O', 'enterprise', 'coding', 2, 'Single sign-on managed organization-wide by an identity provider.', 'SSO stands for single sign-on. Enterprise SSO lets employees use one managed identity provider, such as Okta, Google Workspace, Microsoft Entra ID, or OneLogin, to access many work apps with centralized access control.', 'the enterprise SSO requirement meant every employee had to sign in through okta, not a standalone password.', 'ever notice work apps make you sign in through okta instead of a plain email and password? that''s enterprise SSO. knowing the word explains why companies route logins through one managed identity provider so access can be granted and revoked in one place.', ARRAY['sec-sso','sec-oauth','sec-role','prod-compliance']::text[], ARRAY['sec-sso','sec-oauth']::text[], 'prod-compliance', ARRAY['a texted code or push prompt added on top of a password','assigning permissions to people according to their role','the directory service holding all the user accounts']::text[], 'the ___ requirement meant every employee had to sign in through okta, not a standalone password.', 'Use ''enterprise SSO'' in a sentence about organization-wide single sign-on.', 'curated', 'curator', '2026-05-26'),
('prod-story', 'story', null, 'enterprise', 'coding', 1, 'A user-shaped description of desired behavior.', 'A story frames work from a user or stakeholder perspective, often in the form "as a user, I want..." The useful part is not the template; it is the discipline of naming who needs what outcome and why.', 'the story says a learner wants to tap any unfamiliar term and get a plain explanation on the spot.', 'it''s easy to build a feature and forget who it was for. a story keeps the work tied to a real person and the outcome they want, so "as a learner, i want..." stays in front of you while you''re heads-down in the code.', ARRAY['prod-epic','prod-acceptance-criteria','prod-ticket','se-use-case']::text[], ARRAY['prod-ticket','se-use-case']::text[], 'prod-acceptance-criteria', ARRAY['a larger outcome that bundles many related tickets together','the conditions that prove a feature is actually finished','a checkpoint that groups work heading toward a launch']::text[], 'the ___ says a learner wants to tap any unfamiliar term and get a plain explanation on the spot.', 'Use ''story'' in a sentence about user-shaped desired behavior.', 'curated', 'curator', '2026-05-26'),
('prod-system-of-record', 'system of record', null, 'enterprise', 'coding', 2, 'The authoritative source for a type of business data.', 'A system of record is the place everyone agrees is the official source for a data category. A CRM might be the system of record for accounts. An ERP might be the system of record for inventory. Other systems may copy the data, but the source wins when they disagree.', 'the crm is our system of record for account owner and status, so when the dashboard disagrees, the crm wins.', 'when two screens show different account owners, somebody has to win. asking "which one is the system of record?" cuts the argument short by naming the source everyone already agreed to trust when the data disagrees.', ARRAY['prod-crm','prod-erp','data-primary-key','prod-audit-log']::text[], ARRAY['prod-crm','prod-erp']::text[], 'prod-audit-log', ARRAY['a downstream copy that mirrors data from somewhere else','the finance-and-operations backbone a big company runs on','the sales software that logs customer accounts and deals']::text[], 'the crm is our ___ for account owner and status, so when the dashboard disagrees, the crm wins.', 'Use ''system of record'' in a sentence about the authoritative source for business data.', 'curated', 'curator', '2026-05-26'),
('prod-ticket', 'ticket', null, 'enterprise', 'coding', 1, 'A trackable unit of work, bug, request, or investigation.', 'A ticket is a record for one piece of work. It usually has a title, description, owner, status, priority, comments, and links to designs or pull requests. Tickets help teams coordinate without losing context in chat.', 'i filed a ticket asking for the version pill to show the latest three releases, so it won''t get lost in the thread.', 'loose requests die in chat. when someone says "open a ticket for that," they mean give the work an owner, a status, and a place to live so it survives past the conversation and someone is actually accountable for it.', ARRAY['prod-backlog','prod-story','flow-pull-request','prod-acceptance-criteria']::text[], ARRAY['prod-backlog']::text[], 'prod-story', ARRAY['a larger chunk of related work spread across many tasks','the unsorted pile of possible work waiting in a queue','a condition that has to be true before work counts as done']::text[], 'i filed a ___ asking for the version pill to show the latest three releases, so it won''t get lost in the thread.', 'Use ''ticket'' in a sentence about a trackable unit of work.', 'curated', 'curator', '2026-05-26'),
('az-key-vault', 'Azure Key Vault', null, 'enterprise-platforms', 'coding', 2, 'Azure''s service for storing secrets, keys, and certificates securely.', 'Azure Key Vault stores sensitive objects such as API keys, passwords, connection strings, cryptographic keys, and certificates. Apps can read from it with controlled identity and permissions instead of hardcoding secrets.', 'the database password lives in Azure Key Vault, so it''s never sitting in the repo or an env file.', 'this is how serious systems keep passwords and api keys out of code, logs, and chat, the app reads them from here at runtime instead of hardcoding them. when you wonder "where should this secret live?", this is the answer in azure.', ARRAY['sec-secret','az-managed-id','az-rbac']::text[], ARRAY['sec-secret']::text[], 'az-managed-id', ARRAY['an Azure identity an app uses without its own password','the role you assign to give someone the Reader permission','the control plane that deploys and organizes resources']::text[], 'the database password lives in ___, so it''s never sitting in the repo or an env file.', 'Use ''Azure Key Vault'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('az-managed-id', 'managed identity', null, 'enterprise-platforms', 'coding', 2, 'An Azure-provided identity an app can use without managing its own password.', 'A managed identity lets an Azure app authenticate to supported services without storing credentials. Azure creates a service principal behind the scenes and handles the credential lifecycle.', 'the function app uses a managed identity to read key vault, so there''s no client secret to rotate.', 'this is how an azure app proves who it is without anyone storing a password for it, azure handles the credential behind the scenes. it''s the clean answer to "how does this function read key vault without a secret in the code?"', ARRAY['az-key-vault','ms365-entra','az-rbac']::text[], ARRAY['ms365-entra']::text[], 'az-rbac', ARRAY['the vault where passwords and keys are kept out of code','the role assignment that grants the access itself','the directory service that holds users and groups']::text[], 'the function app uses a ___ to read key vault, so there''s no client secret to rotate.', 'Use ''managed identity'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('az-rbac', 'Azure RBAC', 'R-back', 'enterprise-platforms', 'coding', 2, 'Azure role-based access control for granting permissions to Azure resources.', 'Azure RBAC stands for role-based access control. It assigns roles to users, groups, service principals, or managed identities at scopes such as subscription, resource group, or resource.', 'Azure RBAC is what let the app read the storage account once we gave it the reader role.', 'when an app or person hits a "permission denied" in azure, this is almost always why, a role wasn''t assigned at the right scope. understanding it turns random access errors into a fixable "who has which role where" question.', ARRAY['sec-rbac','az-resource-group','az-managed-id']::text[], ARRAY['sec-rbac']::text[], 'az-managed-id', ARRAY['the Azure identity an app uses without storing a password','the vault that keeps secrets and certificates out of code','the logical container grouping related resources together']::text[], '___ is what let the app read the storage account once we gave it the reader role.', 'Use ''Azure RBAC'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('az-resource-group', 'Azure resource group', null, 'enterprise-platforms', 'coding', 1, 'A logical container for Azure resources that are managed together.', 'An Azure resource group holds related resources such as apps, databases, storage accounts, functions, networks, and Key Vaults. Teams often organize resource groups by app, environment, or lifecycle.', 'the api and its key vault sit in one Azure resource group, so we can tear the whole stack down together.', 'when you''re staring at the azure portal trying to find an app and its database, they''re usually bundled in one resource group on purpose. it''s the folder that keeps related services together so you can manage or delete them as a unit.', ARRAY['az-subscription','az-resource-manager','az-key-vault']::text[], ARRAY['az-subscription']::text[], 'az-resource-manager', ARRAY['the billing boundary that contains many groups','the control layer that applies policy and access','a role assignment that lets one app read a storage account']::text[], 'the api and its key vault sit in one ___, so we can tear the whole stack down together.', 'Use ''Azure resource group'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('az-resource-manager', 'Azure Resource Manager', null, 'enterprise-platforms', 'coding', 2, 'Azure''s control layer for creating, updating, organizing, and securing resources.', 'Azure Resource Manager is the management layer behind Azure deployments. It receives requests from the portal, Azure CLI, templates, SDKs, and automation, then applies access control, policy, tags, and deployment operations to resources.', 'the infrastructure template deployed through Azure Resource Manager, so every resource picked up our tags.', 'whether someone clicks the portal, runs the cli, or fires a template, it all funnels through this one control plane that applies access and policy. that''s why a resource created two different ways still ends up following the same rules.', ARRAY['az-resource-group','az-rbac']::text[], ARRAY['ent-azure']::text[], 'az-rbac', ARRAY['the logical container that holds related resources','the billing boundary grouping usage and quotas','the store that keeps passwords and API keys out of code']::text[], 'the infrastructure template deployed through ___, so every resource picked up our tags.', 'Use ''Azure Resource Manager'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('az-subscription', 'Azure subscription', null, 'enterprise-platforms', 'coding', 1, 'A billing and management boundary for Azure resources.', 'An Azure subscription groups Azure usage, billing, quotas, policies, and access. Resources live inside resource groups, and resource groups live inside subscriptions. A tenant can contain multiple subscriptions.', 'we run staging in a separate Azure subscription so its costs don''t get mixed in with production.', 'this is the boundary your azure bill and access both hang off of, resource groups sit inside it, and one org can run several. when costs need splitting between staging and prod, separate subscriptions are usually how.', ARRAY['az-resource-group','az-resource-manager','ent-azure']::text[], ARRAY['ent-azure']::text[], 'az-resource-group', ARRAY['a logical container grouping resources managed together','the control layer that creates and secures resources','the identity service behind Azure sign-in and access']::text[], 'we run staging in a separate ___ so its costs don''t get mixed in with production.', 'Use ''Azure subscription'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('dv-column', 'Dataverse column', null, 'enterprise-platforms', 'coding', 1, 'A typed field on a Dataverse table.', 'A Dataverse column stores one piece of data on each row, such as text, number, date, choice, lookup, file, email, currency, or image. Columns used to be called fields or attributes.', 'the due date is a Dataverse column on the request table, set to a date type so it gets a calendar picker.', 'every field you fill in on a microsoft business form comes from one of these, and its type, text, date, choice, is what decides which control and validation you get. knowing this explains why a date picker behaves differently than a free-text box.', ARRAY['dv-table','data-column','dv-dataverse']::text[], ARRAY['dv-table']::text[], 'data-column', ARRAY['the table structure that holds the full set of rows','the lookup link that points one table at another','the saved view that controls which rows appear in a list']::text[], 'the due date is a ___ on the request table, set to a date type so it gets a calendar picker.', 'Use ''Dataverse column'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('dv-dataverse', 'Microsoft Dataverse', null, 'enterprise-platforms', 'coding', 1, 'Microsoft''s secure business data platform for apps, flows, tables, and rules.', 'Microsoft Dataverse stores business data for Power Platform and model-driven apps. It organizes data into tables, rows, and columns, and adds security roles, relationships, validation, business rules, workflows, and solution packaging.', 'all the customer records for that app live in Microsoft Dataverse, so the security roles are set there too.', 'when a power app or a copilot agent needs somewhere real to store and secure its data, this is usually the backbone holding the tables. knowing it explains where a low-code app''s records actually live.', ARRAY['dv-table','dv-column','dv-solution']::text[], ARRAY['data-table']::text[], 'dv-solution', ARRAY['a single structure that stores rows of one business thing','the bundle that ships components between environments','the boundary that walls dev apps off from prod']::text[], 'all the customer records for that app live in ___, so the security roles are set there too.', 'Use ''Microsoft Dataverse'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('dv-solution', 'Dataverse solution', null, 'enterprise-platforms', 'coding', 2, 'A package for moving Power Platform components between environments.', 'A Dataverse or Power Platform solution packages apps, tables, columns, flows, security roles, and other components so they can move from development to test or production. Unmanaged solutions are usually for development; managed solutions are usually for downstream environments.', 'we exported the unmanaged Dataverse solution from dev so we could import it into the test environment.', 'this is how low-code work actually ships, you package the apps, tables, and flows into one bundle and move it from dev to production instead of rebuilding by hand. it''s the difference between loose clicking and a real release.', ARRAY['pp-environment','dv-dataverse','cloud-deploy']::text[], ARRAY['pp-environment']::text[], 'cloud-deploy', ARRAY['the data backbone that stores the tables being packaged','the boundary the package gets imported into','the packaged integration that calls other services']::text[], 'we exported the unmanaged ___ from dev so we could import it into the test environment.', 'Use ''Dataverse solution'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('dv-table', 'Dataverse table', null, 'enterprise-platforms', 'coding', 1, 'A Dataverse structure that stores rows of one business thing, like accounts or requests.', 'A Dataverse table is similar to a database table but carries Microsoft business-app behavior: columns, relationships, forms, views, business rules, ownership, and security. Tables were historically called entities.', 'the model-driven app starts with a Dataverse table for store locations, one row per site.', 'every screen and form in a model-driven app is really sitting on top of one of these, what used to be called an entity. once you see the table, you can map an app''s ui straight back to its underlying data.', ARRAY['dv-dataverse','dv-column','dv-solution']::text[], ARRAY['dv-dataverse']::text[], 'dv-column', ARRAY['a typed field that stores one value on each row','the whole data backbone the tables are stored in','the bundle that packages components for shipping']::text[], 'the model-driven app starts with a ___ for store locations, one row per site.', 'Use ''Dataverse table'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('gh-actions', 'GitHub Actions', 'GitHub Actions', 'enterprise-platforms', 'coding', 1, 'GitHub automation for running checks, builds, and deploy workflows from repository events.', 'GitHub Actions is the automation system inside GitHub. It runs workflow files from a repository when events happen, such as a pull request opening, a push landing, a schedule firing, or a manual run starting.', 'i pushed the fix but GitHub Actions is still running the lint check, so don''t merge yet.', 'when you open a pull request and see green checkmarks or a red x next to your commit, that''s github actions running. knowing the name means a failing build is a workflow you can open and read, not a mysterious badge judging your code.', ARRAY['gh-workflow','gh-runner','flow-ci']::text[], ARRAY['flow-repository']::text[], 'gh-workflow', ARRAY['GitHub''s issue tracker for filing and discussing bugs','a published package other repos can install','a kanban board for planning work across a repo']::text[], 'i pushed the fix but ___ is still running the lint check, so don''t merge yet.', 'Use ''GitHub Actions'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('gh-runner', 'GitHub runner', null, 'enterprise-platforms', 'coding', 1, 'The machine that executes a GitHub Actions job.', 'A GitHub runner is the Linux, Windows, macOS, or self-hosted machine that actually runs workflow commands. If a job says `ubuntu-latest`, GitHub starts a hosted Linux runner for that work.', 'the test job failed on the windows GitHub runner but passed on the ubuntu one, so it''s probably a path issue.', 'ci isn''t magic in the cloud, it''s a throwaway machine that spins up, runs your commands, and disappears. once you picture the runner, a workflow that says ubuntu-latest just means "give me a fresh linux box for this job."', ARRAY['gh-actions','gh-workflow','os-process']::text[], ARRAY['gh-actions']::text[], 'cloud-container', ARRAY['the YAML file that defines which jobs to run','the repository event that triggers a workflow to start','the log output a finished job prints to the UI']::text[], 'the test job failed on the windows ___ but passed on the ubuntu one, so it''s probably a path issue.', 'Use ''GitHub runner'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('gh-workflow', 'GitHub workflow', null, 'enterprise-platforms', 'coding', 1, 'A YAML-defined automation process checked into a repository.', 'A GitHub workflow is a file under `.github/workflows` that defines when automation runs and which jobs belong to that automation. One repo can have separate workflows for tests, deploys, labels, scheduled tasks, and release work.', 'the deploy GitHub workflow only runs after code merges to main, so feature branches won''t trigger it.', 'if you''ve ever wondered why tests run on every push but the deploy only fires on main, the answer is in a workflow file. knowing the term lets you trace a check back to the exact yaml in .github/workflows that defined it.', ARRAY['gh-actions','gh-runner']::text[], ARRAY['gh-actions']::text[], 'gh-runner', ARRAY['the throwaway machine that executes the job''s commands','a green or red status badge shown on a commit','a saved search that filters a repo''s open issues']::text[], 'the deploy ___ only runs after code merges to main, so feature branches won''t trigger it.', 'Use ''GitHub workflow'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('ms365-admin-center', 'Microsoft 365 admin center', null, 'enterprise-platforms', 'coding', 1, 'The web console where admins manage Microsoft 365 users, licenses, groups, and settings.', 'The Microsoft 365 admin center is the main dashboard for tenant administration. Admins use it to add users, assign licenses, manage groups, inspect service health, and reach related admin centers.', 'i bumped her up to an e5 in the Microsoft 365 admin center, give it a few minutes to apply.', 'when you need to add a user or hand someone a license, this is the one screen that does it instead of hunting through outlook, teams, and sharepoint settings separately. knowing where it lives saves the "where do i even change this?" scramble.', ARRAY['ms365-tenant','ms365-license','ms365-group']::text[], ARRAY['ms365-tenant']::text[], 'ms365-license', ARRAY['the org-wide container holding all users and data','Microsoft''s identity service for sign-in and access','a workspace for pages, lists, and document libraries']::text[], 'i bumped her up to an e5 in the ___, give it a few minutes to apply.', 'Use ''Microsoft 365 admin center'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('ms365-entra', 'Microsoft Entra ID', 'EN-truh I-D', 'enterprise-platforms', 'coding', 2, 'Microsoft''s identity service for users, groups, apps, sign-in, and access control.', 'Microsoft Entra ID is the identity layer behind Microsoft 365 and Azure. It stores users, groups, app registrations, service principals, conditional access rules, and sign-in controls. It used to be called Azure Active Directory.', 'the app registration lives in Microsoft Entra ID, so check the sign-in logs there if auth is failing.', 'every microsoft sign-in, sso prompt, and app permission traces back here, it''s just azure active directory under a newer name. when a login or conditional-access rule misbehaves, entra id is where you go to see why.', ARRAY['ms365-tenant','az-managed-id','az-rbac']::text[], ARRAY['ms365-tenant']::text[], 'az-managed-id', ARRAY['the billing and management boundary for Azure resources','the org-level Microsoft 365 container for users and apps','a per-user license that switches on Microsoft apps']::text[], 'the app registration lives in ___, so check the sign-in logs there if auth is failing.', 'Use ''Microsoft Entra ID'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('ms365-group', 'Microsoft 365 group', 'Microsoft three-sixty-five group', 'enterprise-platforms', 'coding', 1, 'A membership object that grants shared access to Microsoft 365 resources.', 'A Microsoft 365 group gives a set of people shared access to collaboration resources, often including an Outlook mailbox, calendar, SharePoint document library, Planner plan, Teams team, or Power BI workspace.', 'adding me to the regional ops Microsoft 365 group is what finally gave me the shared calendar.', 'adding one person to a group can unlock a mailbox, a sharepoint site, and a teams team all at once. that''s why access requests so often end with "just put them in the group" instead of granting five things by hand.', ARRAY['ms365-sharepoint-site','ms365-license','sec-rbac']::text[], ARRAY['ms365-tenant']::text[], 'sec-rbac', ARRAY['the per-user toggle that turns on a single app like Teams','the org-level container for the whole company','a SharePoint workspace holding files and lists']::text[], 'adding me to the regional ops ___ is what finally gave me the shared calendar.', 'Use ''Microsoft 365 group'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('ms365-license', 'Microsoft 365 license', 'Microsoft three-sixty-five license', 'enterprise-platforms', 'coding', 1, 'A paid entitlement that turns Microsoft apps and services on for a user or group.', 'A Microsoft 365 license controls which apps and service plans a person can use, such as Exchange, SharePoint, Teams, Office apps, Copilot, Power BI, or Power Platform capabilities.', 'she couldn''t open power bi until i assigned the Microsoft 365 license, then it worked right away.', 'this is why someone can have a working account but still get locked out of power bi or copilot. the license is the on-switch for each service, so "do they have a license for that?" is usually the first question when access breaks.', ARRAY['ms365-admin-center','ms365-group','ent-powerbi']::text[], ARRAY['ms365-tenant']::text[], 'ms365-group', ARRAY['a membership list that grants people a shared mailbox','the admin console where access gets assigned','the role definition that controls what a user can do']::text[], 'she couldn''t open power bi until i assigned the ___, then it worked right away.', 'Use ''Microsoft 365 license'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('ms365-sharepoint-site', 'SharePoint site', null, 'enterprise-platforms', 'coding', 1, 'A Microsoft 365 workspace for pages, lists, document libraries, permissions, and team content.', 'A SharePoint site is a container for collaboration content. It can hold pages, lists, files, document libraries, metadata, permissions, and often the files behind Teams channels.', 'the current checklist lives on the SharePoint site, not in anyone''s inbox, so always grab it from there.', 'that policy doc someone keeps emailing around probably already lives on a sharepoint site, with the files behind a teams channel too. knowing this is where shared content actually sits stops the "can you resend that?" loop.', ARRAY['ms365-group','ms365-tenant']::text[], ARRAY['ms365-tenant']::text[], 'copilot-knowledge-source', ARRAY['a membership object that pulls people into a Teams team','the identity service behind Microsoft sign-in','the admin console for managing users and licenses']::text[], 'the current checklist lives on the ___, not in anyone''s inbox, so always grab it from there.', 'Use ''SharePoint site'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('ms365-tenant', 'Microsoft 365 tenant', 'Microsoft three-sixty-five', 'enterprise-platforms', 'coding', 1, 'The organization-level Microsoft 365 container for users, apps, licenses, data, and policy.', 'A Microsoft 365 tenant is the top-level work-account boundary for a company. It contains users, groups, licenses, SharePoint sites, Teams, mailboxes, admin settings, and identity configuration through Microsoft Entra ID.', 'the new hire showed up in the Microsoft 365 tenant this morning, so i can finally add them to teams.', 'your whole work identity lives inside one tenant: every user, license, mailbox, and teams team. when someone asks "is that account in our tenant?" they''re really asking whether the org even recognizes that person at all.', ARRAY['ms365-admin-center','ms365-license','ms365-entra']::text[], ARRAY[]::text[], 'ms365-entra', ARRAY['the web console where admins assign licenses and settings','the on-switch that unlocks Power BI for one person','a membership list granting people shared access to resources']::text[], 'the new hire showed up in the ___ this morning, so i can finally add them to teams.', 'Use ''Microsoft 365 tenant'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('pp-connector', 'Power Platform connector', null, 'enterprise-platforms', 'coding', 2, 'A reusable integration that lets Power Platform talk to another service or API.', 'A Power Platform connector gives Power Apps, Power Automate, and Copilot Studio a packaged way to read data, write data, or call actions in another system. Connectors can be prebuilt or custom-built.', 'the flow uses a Power Platform connector to push each new lead into the crm record automatically.', 'this is the piece that lets a low-code app or flow reach into sharepoint, a crm, or some outside api without custom plumbing. spotting the connector tells you exactly where one microsoft tool crosses into another system.', ARRAY['pp-power-automate','arch-api']::text[], ARRAY['arch-api']::text[], 'copilot-connector', ARRAY['the workflow engine that runs the automated steps','the data backbone that stores the records being updated','the boundary that keeps environments apart']::text[], 'the flow uses a ___ to push each new lead into the crm record automatically.', 'Use ''Power Platform connector'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('pp-environment', 'Power Platform environment', null, 'enterprise-platforms', 'coding', 1, 'A workspace boundary for Power Apps, Power Automate, Dataverse, connections, and security.', 'A Power Platform environment separates apps, flows, Dataverse databases, connectors, users, and security settings. Teams often use different environments for development, testing, and production.', 'the maker built the inspection app in the dev Power Platform environment first, then we moved it once it was stable.', 'this is the boundary that explains why a low-code app exists in dev but not in production yet, each environment has its own apps, flows, and data. when a maker says "it works in the dev environment," they mean it hasn''t crossed that line.', ARRAY['pp-power-apps','pp-power-automate','dv-dataverse']::text[], ARRAY[]::text[], 'dv-solution', ARRAY['the secure data backbone that stores tables and rows','the bundle that ships components between dev and prod','a packaged integration that calls another service']::text[], 'the maker built the inspection app in the dev ___ first, then we moved it once it was stable.', 'Use ''Power Platform environment'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('pp-power-apps', 'Power Apps', null, 'enterprise-platforms', 'coding', 1, 'Microsoft''s low-code app builder for canvas apps and model-driven apps.', 'Power Apps lets makers build business apps on top of data sources such as Dataverse, SharePoint, SQL, and connectors. Canvas apps focus on custom screen layout; model-driven apps focus on Dataverse data models and forms.', 'we built the store inspection checklist in Power Apps so the field team can fill it out on a phone.', 'when a coworker builds a working form or checklist app without writing real code, this is almost always the tool. knowing it lets you tell a custom-built low-code app apart from a full developer project.', ARRAY['pp-environment','dv-dataverse','pp-connector']::text[], ARRAY['pp-environment']::text[], 'dv-dataverse', ARRAY['the workflow service that reacts to triggers and events','the secure data backbone storing tables behind the app','the boundary that keeps dev apps separate from prod']::text[], 'we built the store inspection checklist in ___ so the field team can fill it out on a phone.', 'Use ''Power Apps'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('pp-power-automate', 'Power Automate', null, 'enterprise-platforms', 'coding', 1, 'Microsoft''s workflow automation service for triggers, actions, approvals, and connectors.', 'Power Automate creates flows that react to events, move data between services, request approvals, send notifications, or run scheduled work. It often connects Microsoft 365, Dataverse, SharePoint, Outlook, and third-party systems.', 'Power Automate sends a teams message to the lead whenever someone submits the request form.', 'anytime a microsoft form submission quietly fires off an email or posts to teams with nobody clicking, a flow built here did it. it''s the glue word for "this just happens automatically" in the microsoft world.', ARRAY['pp-connector','pp-environment','ms365-sharepoint-site']::text[], ARRAY['pp-environment']::text[], 'pp-connector', ARRAY['the low-code builder for canvas and model-driven apps','a packaged integration that calls into another system','the agent-building surface for Copilot assistants']::text[], '___ sends a teams message to the lead whenever someone submits the request form.', 'Use ''Power Automate'' in a sentence about the system where it appears.', 'curated', 'curator', '2026-05-28'),
('git-cherry-pick', 'cherry-pick', null, 'git-cli', 'coding', 2, 'Copying one specific commit onto your current branch without merging the whole source branch.', 'Cherry-pick is the surgical Git move. Instead of merging an entire branch, you choose one commit and replay just that commit onto the branch you are on now. It is useful when one bug fix needs to move forward but the rest of that branch is not ready.', 'let''s cherry-pick the OAuth fix onto main and leave the visual polish branch alone for now.', 'when a branch has one good commit buried in a pile of unfinished work, cherry-pick is how you rescue just that commit without dragging the whole branch forward. it''s the surgical move when one fix needs to ship but the rest isn''t ready.', ARRAY['git-commit','git-merge','git-rebase']::text[], ARRAY['git-commit','git-branch']::text[], 'git-rebase', ARRAY['replaying every commit from a branch onto a fresh base','tying two branches together with a merge commit','a fresh commit that reverses what an earlier one did']::text[], 'let''s ___ the OAuth fix onto main and leave the visual polish branch alone for now.', 'Use ''cherry-pick'' in a sentence about moving one commit without merging a whole branch.', 'curated', 'curator', '2026-05-25'),
('git-squash', 'squash', null, 'git-cli', 'coding', 2, 'Combining several commits into one cleaner commit before a branch is merged.', 'Squashing takes a messy series of commits and compresses them into one commit with one clear message. The code result is the same, but the history reads better. Teams often squash before merging a PR so main does not fill up with "fix typo", "try again", and "actually fix it" commits.', 'squash the three checkpoint commits into one clean auth commit before you merge.', 'agent branches pile up tiny checkpoint commits — "fix typo," "try again," "actually fix it." squashing compresses them into one clear commit before merge, so main reads like a story instead of a stream of consciousness.', ARRAY['git-commit','git-rebase','git-pr']::text[], ARRAY['git-commit']::text[], 'git-rebase', ARRAY['dropping a single commit from another branch onto this one','rewording just the most recent commit''s message','pulling down remote commits without folding them in']::text[], '___ the three checkpoint commits into one clean auth commit before you merge.', 'Use ''squash'' in a sentence about cleaning up commit history before a merge.', 'curated', 'curator', '2026-05-25'),
('git-worktree', 'worktree', null, 'git-cli', 'coding', 2, 'A second working checkout of the same repo, tied to its own branch, so you can edit two branches side by side.', 'A Git worktree lets one repository have multiple working folders at the same time. Each folder can be on a different branch, but they share the same underlying git history. It is how an agent can keep a PR branch open in one folder while inspecting a stack branch in another without constantly switching branches or stashing work.', 'I made a worktree for the stack branch so I can inspect it without leaving this PR.', 'when you''ve got several branches alive at once, a worktree is the clean way to look at two of them side by side — each in its own folder — without constantly switching branches or stashing half-finished work and turning it into soup.', ARRAY['git-branch','git-checkout','git-stash']::text[], ARRAY['git-branch','git-checkout']::text[], 'git-rebase', ARRAY['a movable pointer to a particular line of commits','a copy of the repo hosted on a remote like github','stashed-away edits you can drop back on later']::text[], 'I made a ___ for the stack branch so I can inspect it without leaving this PR.', 'Use ''worktree'' in a sentence about keeping two branches open in separate folders.', 'curated', 'curator', '2026-05-25'),
('math-big-o', 'Big O', 'big oh', 'math-logic', 'coding', 3, 'Notation for describing how an algorithm scales as input grows.', 'Big O is the shorthand engineers use for growth rate. O(1) means roughly constant work. O(n) grows with the number of items. O(n squared) grows much faster because each new item can multiply the work. Big O ignores tiny details and focuses on the shape of scaling.', 'i rewrote the matching step so its Big O dropped from quadratic to linear and it stopped timing out.', 'Big O is the shorthand in any code review where someone asks "how does this scale?" knowing it means you can tell a change that stays fast on a huge input from one that quietly gets slower with every row.', ARRAY['math-complexity','code-algorithm','math-optimization','data-index']::text[], ARRAY['math-complexity']::text[], 'math-optimization', ARRAY['the exact runtime in seconds for an input','the memory a single value occupies','the count of times a loop body repeats once']::text[], 'i rewrote the matching step so its ___ dropped from quadratic to linear and it stopped timing out.', 'Use ''Big O'' in a sentence about algorithm scaling.', 'curated', 'curator', '2026-05-26'),
('math-boolean', 'boolean', null, 'math-logic', 'coding', 1, 'A true-or-false value used in logic and code.', 'A boolean is a value with only two possible states: true or false. Code uses booleans for conditions, feature flags, permissions, test results, and any decision that branches one way or another. A checkbox, an allowlist match, and "is this test passing?" can all become booleans.', 'i wired the dark-mode toggle to a single boolean so it''s either on or off, nothing in between.', 'when a teammate says "just make it a boolean," they mean the answer is genuinely yes-or-no, not a score or a maybe. spotting that lets you tell a crisp on/off switch from something fuzzier that needs a number or a range.', ARRAY['code-conditional','sec-permission','qa-unit-test','math-state-machine']::text[], ARRAY[]::text[], 'code-conditional', ARRAY['a value that can hold any whole number','a single character of text like a letter','a placeholder that points to a value elsewhere']::text[], 'i wired the dark-mode toggle to a single ___ so it''s either on or off, nothing in between.', 'Use ''boolean'' in a sentence about a true-or-false software decision.', 'curated', 'curator', '2026-05-26'),
('math-complexity', 'complexity', null, 'math-logic', 'coding', 2, 'How an algorithm''s work grows as the input grows.', 'Complexity describes how much time or memory an algorithm needs as the input gets bigger. A solution that feels instant for 10 items can become unusable for 10 million items. Complexity is why engineers care about growth rate, not only whether code works on a tiny example.', 'the lookup was instant on the demo data, but its complexity bit us once the table hit a million rows.', 'this is why code that works fine on your laptop falls over in production. when someone flags the complexity, they''re warning you it''ll choke once the input gets big — long before users ever see it break.', ARRAY['math-big-o','code-algorithm','math-optimization','hw-cpu']::text[], ARRAY['code-algorithm']::text[], 'math-big-o', ARRAY['the total lines of code in a program','how many branches a function contains','the wall-clock time of one specific run']::text[], 'the lookup was instant on the demo data, but its ___ bit us once the table hit a million rows.', 'Use ''complexity'' in a sentence about how work grows with input size.', 'curated', 'curator', '2026-05-26'),
('math-constraint', 'constraint', null, 'math-logic', 'coding', 1, 'A rule or limit that restricts which solutions are allowed.', 'A constraint is a limit the solution must respect. It might be budget, time, data shape, screen size, privacy, performance, safety, or an engineering rule. Constraints are not always bad; they make the problem real enough to solve.', 'the real constraint wasn''t the design, it was that everything had to fit a phone screen.', '"why can''t we just do X" almost always has a constraint behind it — a budget, a deadline, a screen size, a privacy rule. naming the constraint turns a vague frustration into a concrete thing you can actually argue with.', ARRAY['se-constraint','math-optimization','prod-acceptance-criteria','math-state-machine']::text[], ARRAY[]::text[], 'math-optimization', ARRAY['the target an approach tries to improve toward','a step-by-step recipe for solving a problem','the input value handed to a function']::text[], 'the real ___ wasn''t the design, it was that everything had to fit a phone screen.', 'Use ''constraint'' in a sentence about a limit a solution must respect.', 'curated', 'curator', '2026-05-26'),
('math-distribution', 'distribution', null, 'math-logic', 'coding', 2, 'The shape of possible values and how often they occur.', 'A distribution describes which values can happen and how common each one is. Response times, user ages, model scores, errors per day, and test durations all have distributions. Averages can hide the shape; distributions show whether values cluster, spread out, or have rare extremes.', 'our average response time looked great until the distribution showed a chunk of users waiting eight seconds.', 'an average can look healthy while a slice of users quietly suffers. when someone pulls up the distribution, they''re checking whether values cluster nicely or whether a painful long tail is hiding behind the mean.', ARRAY['math-probability','cloud-metric','qa-slo']::text[], ARRAY['math-probability']::text[], 'math-entropy', ARRAY['the single middle value of a sorted list','the gap between the largest and smallest value','one representative average of the whole group']::text[], 'our average response time looked great until the ___ showed a chunk of users waiting eight seconds.', 'Use ''distribution'' in a sentence about the shape of possible values.', 'curated', 'curator', '2026-05-26'),
('math-edge', 'edge', null, 'math-logic', 'coding', 2, 'A connection between two nodes in a graph.', 'An edge is the relationship line between two nodes. It can mean follows, imports, depends on, connects to, links to, or routes toward, depending on the graph. Edges are what turn a pile of items into a relationship map.', 'i added an edge from the login module to the auth service to show that it depends on it.', 'two systems can have the exact same items but completely different edges — and the edges are usually where the meaning lives. hearing "edge" tells you the talk has shifted from the things to the relationships between them.', ARRAY['math-graph','math-node','math-tree','arch-dependency-injection']::text[], ARRAY['math-node']::text[], 'math-tree', ARRAY['a single item sitting in the structure','the starting point of the whole structure','a complete loop that returns to its start']::text[], 'i added an ___ from the login module to the auth service to show that it depends on it.', 'Use ''edge'' in a sentence about a connection between two nodes.', 'curated', 'curator', '2026-05-26'),
('math-entropy', 'entropy', null, 'math-logic', 'coding', 3, 'A measure of uncertainty, surprise, or information content.', 'Entropy measures how unpredictable something is. A fair coin has more entropy than a coin that almost always lands heads. In computing and AI, entropy shows up in compression, randomness, decision trees, passwords, uncertainty, and model output diversity.', 'we made the reset tokens long enough to carry real entropy so nobody could just guess one.', 'the same word explains why a strong password is hard to guess and why some files compress and others don''t: how unpredictable the data is. knowing it ties randomness, security, and compression together instead of three separate mysteries.', ARRAY['math-probability','math-distribution','sec-secret']::text[], ARRAY['math-probability']::text[], 'math-optimization', ARRAY['the count of bytes a file takes on disk','the speed at which data can be transferred','a fixed-length fingerprint of some data']::text[], 'we made the reset tokens long enough to carry real ___ so nobody could just guess one.', 'Use ''entropy'' in a sentence about uncertainty or information content.', 'curated', 'curator', '2026-05-26'),
('math-graph', 'graph', null, 'math-logic', 'coding', 2, 'A structure made of nodes connected by edges.', 'A graph models relationships. The nodes are things, and the edges are connections between them. Social networks, dependency maps, route maps, knowledge graphs, file imports, and prerequisite chains can all be represented as graphs.', 'we modeled the team''s dependencies as a graph so we could see which service everything else relied on.', 'anytime the real question is "what''s connected to what" — followers, package dependencies, map routes — you''re looking at a graph. naming it helps you reason about the connections instead of getting lost in the individual things.', ARRAY['math-node','math-edge','math-tree','code-module']::text[], ARRAY['math-set']::text[], 'math-node', ARRAY['a strict top-down hierarchy with no cycles','a flat sequence of items in order','a grid of rows and columns of values']::text[], 'we modeled the team''s dependencies as a ___ so we could see which service everything else relied on.', 'Use ''graph'' in a sentence about connected things.', 'curated', 'curator', '2026-05-26'),
('math-node', 'node', null, 'math-logic', 'coding', 2, 'One point or item inside a graph or tree.', 'A node is one item in a connected structure. In a social graph, a node might be a person. In a dependency graph, it might be a package. In a tree, it might be one folder, term, or decision point.', 'each user shows up as one node in the social graph, with lines out to everyone they follow.', 'when an engineer is tracing a network or a tree out loud, "node" is the unit they keep pointing at — one person, one package, one folder. catch the word and you never lose track of which single thing is being discussed.', ARRAY['math-graph','math-edge','math-tree','net-router']::text[], ARRAY['math-graph']::text[], 'math-edge', ARRAY['a link joining two points together','the topmost point that has no parent','an end point with nothing below it']::text[], 'each user shows up as one ___ in the social graph, with lines out to everyone they follow.', 'Use ''node'' in a sentence about one point in a graph or tree.', 'curated', 'curator', '2026-05-26'),
('math-optimization', 'optimization', null, 'math-logic', 'coding', 2, 'Searching for the best available solution under constraints.', 'Optimization means improving a solution toward a goal: faster, cheaper, more accurate, less memory, more revenue, lower risk, or better user experience. Real optimization usually has constraints, so the best answer is not abstractly perfect; it is best under the limits that matter.', 'we treated checkout as an optimization problem: cut the steps without dropping the trust signals.', 'there''s a difference between idly polishing and actually optimizing — optimizing means you''ve named a target and you''re pushing toward it inside real limits. hearing the word tells you a goal and a tradeoff are on the table, not just tinkering.', ARRAY['math-constraint','math-complexity','math-big-o']::text[], ARRAY['math-constraint']::text[], 'math-constraint', ARRAY['checking a function returns the right answer','rewriting code to read more cleanly','measuring how long a routine takes to run']::text[], 'we treated checkout as an ___ problem: cut the steps without dropping the trust signals.', 'Use ''optimization'' in a sentence about improving toward a goal under limits.', 'curated', 'curator', '2026-05-26'),
('math-probability', 'probability', null, 'math-logic', 'coding', 1, 'A measure of how likely something is to happen.', 'Probability is a way to talk about uncertainty with numbers. A probability near zero is unlikely. A probability near one is likely. Models, risk systems, spam filters, forecasts, and experiments all use probability when the answer is not guaranteed.', 'the spam filter gave that email a high probability of being junk, so it never hit my inbox.', 'when a model hands back a probability instead of a flat answer, it''s telling you how sure it is. catch that and you''ll stop reading a confident-looking guess as if it were a proven fact.', ARRAY['math-distribution','qa-flaky-test']::text[], ARRAY[]::text[], 'math-distribution', ARRAY['the count of times an event was observed','the average of a set of measured values','a guaranteed outcome stated as a fact']::text[], 'the spam filter gave that email a high ___ of being junk, so it never hit my inbox.', 'Use ''probability'' in a sentence about likelihood under uncertainty.', 'curated', 'curator', '2026-05-26'),
('math-set', 'set', null, 'math-logic', 'coding', 1, 'A collection where each value appears only once.', 'A set is a collection of unique items. Sets are useful when the question is membership: is this user allowlisted, has this term been seen, which IDs appear in both lists, or which values are missing? The order matters less than whether an item belongs.', 'i dropped the tags into a set so the same one couldn''t get counted twice.', 'the moment someone asks "are there duplicates in here?" or "which ids are in both lists?", they''re really reaching for a set. knowing the word saves you from hand-rolling dedupe logic when the language already does membership for free.', ARRAY['code-array','data-primary-key','math-graph','math-boolean']::text[], ARRAY['code-array']::text[], 'math-graph', ARRAY['an ordered collection that allows repeats','a key-to-value lookup of paired entries','a fixed-size block of same-typed slots']::text[], 'i dropped the tags into a ___ so the same one couldn''t get counted twice.', 'Use ''set'' in a sentence about unique values or membership.', 'curated', 'curator', '2026-05-26'),
('math-state-machine', 'state machine', null, 'math-logic', 'coding', 3, 'A model of allowed states and transitions between them.', 'A state machine describes the allowed states something can be in and the events that move it between those states. An invite can be pending, accepted, expired, or revoked. A lesson can be unseen, learning, due for review, or mastered. State machines prevent impossible combinations.', 'i modeled the order flow as a state machine so a shipped order could never quietly slip back to pending.', 'when you find yourself juggling a pile of boolean flags that keep contradicting each other, a state machine is the fix. it spells out the states something can be in and blocks the impossible combinations like "expired but also accepted."', ARRAY['math-boolean','prod-acceptance-criteria','se-lifecycle','code-conditional']::text[], ARRAY['math-boolean']::text[], 'math-turing-complete', ARRAY['a single true-or-false status flag','a queue of tasks waiting to run in order','a recorded log of every past event']::text[], 'i modeled the order flow as a ___ so a shipped order could never quietly slip back to pending.', 'Use ''state machine'' in a sentence about allowed states and transitions.', 'curated', 'curator', '2026-05-26'),
('math-tree', 'tree', null, 'math-logic', 'coding', 2, 'A hierarchy where nodes branch downward from a root.', 'A tree is a special graph with hierarchy and no loops. Filesystems, menus, document outlines, parse trees, comment threads, and decision trees all use this shape: one root, branches, and leaves.', 'the file browser renders the project as a tree, with folders branching down into files.', 'folders, comment threads, nested menus — the second you hear parent, child, root, or leaf, you''re in a tree. spotting the shape tells you there''s a top, a bottom, and no loops to worry about.', ARRAY['math-graph','math-node','math-edge','os-filesystem']::text[], ARRAY['math-node','math-edge']::text[], 'math-complexity', ARRAY['a network where any two points may connect','a single straight chain of linked items','a collection with no order or nesting']::text[], 'the file browser renders the project as a ___, with folders branching down into files.', 'Use ''tree'' in a sentence about a hierarchy of nodes.', 'curated', 'curator', '2026-05-26'),
('math-turing-complete', 'Turing complete', null, 'math-logic', 'coding', 3, 'Able to express any computation a general computer can run.', 'Turing complete describes a system powerful enough to express general computation, given enough time and memory. Many programming languages are Turing complete. Some configuration formats intentionally are not, because unrestricted computation can make systems harder to predict, secure, or terminate.', 'we kept the rules engine from being Turing complete on purpose so nobody could write an infinite loop into a config.', 'it explains a choice that looks backwards at first: why a config format is deliberately kept weak. if a language is Turing complete it can run anything, which is powerful but also impossible to fully predict or guarantee will stop.', ARRAY['code-algorithm','math-state-machine','os-process','math-complexity']::text[], ARRAY['code-algorithm','math-state-machine']::text[], 'math-complexity', ARRAY['a language with no loops or recursion allowed','a format that only stores fixed data values','a system that always finishes in fixed steps']::text[], 'we kept the rules engine from being ___ on purpose so nobody could write an infinite loop into a config.', 'Use ''Turing complete'' in a sentence about general computation power.', 'curated', 'curator', '2026-05-26'),
('net-bandwidth', 'bandwidth', null, 'networking', 'coding', 1, 'How much data a connection can move over time.', 'Bandwidth is the capacity of a connection, usually measured as data per second. It is not the same as latency. A road can have many lanes but still be far away; similarly, a connection can move lots of data once it starts but still have noticeable delay.', 'streaming 4k eats way more bandwidth than loading a page of text.', 'bandwidth and latency get mixed up constantly, and the difference is real money when you''re moving big files. it''s the capacity word: how much the pipe can carry, not how fast a single request starts.', ARRAY['net-throughput','net-latency','net-packet','cloud-cdn']::text[], ARRAY['net-packet']::text[], 'net-throughput', ARRAY['the delay before a request gets its first response','the useful data you actually get after overhead','the size of a single data unit on the wire']::text[], 'streaming 4k eats way more ___ than loading a page of text.', 'Use ''bandwidth'' in a sentence about network capacity.', 'curated', 'curator', '2026-05-25'),
('net-certificate', 'certificate', null, 'networking', 'coding', 2, 'A signed proof that a server owns or controls an identity.', 'A TLS certificate binds a public key to a domain or service identity. Browsers trust certificates when they chain back to trusted certificate authorities and match the domain being visited. Expired, mismatched, or untrusted certificates trigger browser warnings.', 'the browser threw a warning because the certificate was issued for the wrong hostname.', 'https can break right after a domain move, a staging alias, or a renewal you forgot, and the certificate is almost always the culprit. it''s the proof that ties a key to a domain, so when the names don''t match, the browser slams the door.', ARRAY['net-tls','net-dns','web-domain','sec-encryption']::text[], ARRAY['net-tls','net-dns']::text[], 'net-tls', ARRAY['the protocol that encrypts traffic using this proof','the system that resolves a domain to an address','a private key kept secret on the server']::text[], 'the browser threw a warning because the ___ was issued for the wrong hostname.', 'Use ''certificate'' in a sentence about HTTPS proving server identity.', 'curated', 'curator', '2026-05-25'),
('net-dns', 'DNS', 'D-N-S', 'networking', 'coding', 1, 'The naming system that translates domains into IP addresses.', 'DNS stands for Domain Name System. It lets people type names like example.com while computers connect to IP addresses. DNS records can point a domain at a host, verify ownership, route email, or delegate subdomains.', 'the rollout looked done, but DNS hadn''t propagated yet so half my users still hit the old box.', 'you can ship a perfectly healthy deploy and still get a dead site if dns is pointing the name at the old host. it''s the layer that lets you say "the code is fine, the name is just aimed at the wrong place."', ARRAY['net-ip-address','web-domain','sys-origin','net-certificate']::text[], ARRAY['net-ip-address']::text[], 'net-certificate', ARRAY['the numeric address a hostname finally points at','the box that forwards traffic toward its destination','a signed proof that a server controls a domain']::text[], 'the rollout looked done, but ___ hadn''t propagated yet so half my users still hit the old box.', 'Use ''DNS'' in a sentence about a domain resolving to an address.', 'curated', 'curator', '2026-05-25'),
('net-gateway', 'gateway', null, 'networking', 'coding', 2, 'A bridge between one network and another.', 'A gateway is a network hop that connects different networks or protocols. A home router often acts as the default gateway for devices on Wi-Fi. In cloud systems, gateways can sit at boundaries where traffic enters a private network or reaches external services.', 'local services were fine, but the gateway out to the internet was down so nothing external loaded.', 'ever had something work fine inside your network but die the second it tries to reach out? that''s the gateway. it''s the boundary word for "crossing from this network into another one," which is exactly where a lot of access problems hide.', ARRAY['net-router','net-ip-address','sys-api-gateway','net-vpn']::text[], ARRAY['net-router']::text[], 'sys-api-gateway', ARRAY['a box that forwards packets within the same local network','software that masks your device''s apparent network location','a routing-table entry that picks the next hop']::text[], 'local services were fine, but the ___ out to the internet was down so nothing external loaded.', 'Use ''gateway'' in a sentence about crossing from one network to another.', 'curated', 'curator', '2026-05-25'),
('net-ip-address', 'IP address', 'I-P address', 'networking', 'coding', 1, 'A numeric address for a device or service on a network.', 'IP stands for Internet Protocol. An IP address is how machines identify where traffic should go on a network. Domain names are easier for people to remember, but DNS eventually resolves them to IP addresses that routers can move packets toward.', 'i pinged the server directly by its IP address to rule out a dns problem.', 'when someone says "the site is down," half the time the real problem is that the name never resolved to a reachable address. knowing what an ip address is lets you tell apart "the app is broken" from "nothing can find the box it''s running on."', ARRAY['net-dns','net-router','net-packet','web-domain']::text[], ARRAY['web-url']::text[], 'net-dns', ARRAY['the human-friendly host name traffic gets aimed at','the number that picks which service on a host receives traffic','a small data unit wrapped with routing headers']::text[], 'i pinged the server directly by its ___ to rule out a dns problem.', 'Use ''IP address'' in a sentence about where network traffic goes.', 'curated', 'curator', '2026-05-25'),
('net-latency', 'latency', null, 'networking', 'coding', 1, 'The time delay before data gets a response.', 'Latency is delay. In networking, it is often measured as the time between sending a request and receiving a response, or the round-trip time for packets. A connection can have high bandwidth but still feel slow if latency is high.', 'the payload was tiny, but the cross-region latency made every request feel like it hung.', 'a tiny response can still feel sluggish if every click waits on a round trip. latency is the word for that waiting, and it''s why distance, extra hops, and handshakes make an app feel laggy even when the payload is nothing.', ARRAY['net-bandwidth','net-throughput','net-tcp','cloud-edge']::text[], ARRAY['sys-http-request']::text[], 'net-throughput', ARRAY['the raw capacity a link can carry per second','the count of hops a packet passes through','the share of packets lost on the way']::text[], 'the payload was tiny, but the cross-region ___ made every request feel like it hung.', 'Use ''latency'' in a sentence about waiting on a network response.', 'curated', 'curator', '2026-05-25'),
('net-packet', 'packet', null, 'networking', 'coding', 1, 'A small unit of data sent across a network.', 'A packet is a piece of network data wrapped with addressing and protocol information. Larger messages are split into packets, moved across networks, and reassembled by the receiving side. Packet loss, packet size, and packet routing all affect how a connection behaves.', 'wireshark showed packets getting dropped between my laptop and the router, which explained the stalls.', 'a big response isn''t one delivery, it''s a pile of small ones, and any of them can get dropped on the way. once you think in packets, dropped connections, flaky wifi, and "why is this stalling" start to make sense.', ARRAY['net-ip-address','net-router','net-tcp','net-udp']::text[], ARRAY['net-ip-address']::text[], 'net-router', ARRAY['the whole-machine numeric address traffic is aimed at','the measured useful data delivered under load','a fixed-size buffer the os reserves for i/o']::text[], 'wireshark showed ___s getting dropped between my laptop and the router, which explained the stalls.', 'Use ''packet'' in a sentence about small pieces of network data.', 'curated', 'curator', '2026-05-25'),
('net-port', 'port', null, 'networking', 'coding', 1, 'A number that identifies which service a machine should receive traffic for.', 'A port is like a numbered doorway on a machine. The same IP address can run several services at once because each service listens on a different port. Local dev servers often use ports like 5173, 3000, or 54321.', 'something was already running on port 3000, so i told the dev server to use a different one.', 'almost every "address already in use" error you hit in local dev is a port collision. once you get that one machine runs many services on different numbered doorways, killing the stale process that''s squatting on 5173 stops being a mystery.', ARRAY['net-socket','os-process','sys-route','net-tcp']::text[], ARRAY['net-ip-address']::text[], 'net-socket', ARRAY['one endpoint of a connection that code opens','the numeric address that identifies the whole machine','a numbered priority an os assigns to a running task']::text[], 'something was already running on ___ 3000, so i told the dev server to use a different one.', 'Use ''port'' in a sentence about a service listening on a machine.', 'curated', 'curator', '2026-05-25'),
('net-router', 'router', null, 'networking', 'coding', 1, 'A network device or layer that forwards traffic toward its destination.', 'A router reads destination addresses and decides where packets should go next. Home routers connect local devices to the internet. Cloud and data-center routing layers move traffic between networks, regions, and services.', 'i power-cycled the router and the dropped connections cleared up.', 'connectivity can break at your local network, your provider, the cloud edge, or a service boundary, and a router sits at each of those handoffs. knowing what it does tells you where in the chain to start poking when traffic isn''t getting through.', ARRAY['net-gateway','net-ip-address','net-packet','sys-route']::text[], ARRAY['net-packet']::text[], 'net-gateway', ARRAY['the bridge that connects one whole network to another','the name-to-address lookup that resolves a host','a firewall rule that allows or blocks a port']::text[], 'i power-cycled the ___ and the dropped connections cleared up.', 'Use ''router'' in a sentence about forwarding network traffic.', 'curated', 'curator', '2026-05-25'),
('net-socket', 'socket', null, 'networking', 'coding', 2, 'One endpoint of a network connection between programs.', 'A socket is a program-level network endpoint. Code opens sockets to listen for incoming connections or connect to another service. Underneath many web requests, database clients, dev servers, and realtime connections are sockets managed by the OS.', 'the client kept the socket open so it could stream updates instead of re-requesting.', 'when your code "listens on a port" or throws "connection refused," a socket is the thing actually doing it. it''s the handle between your app and the network plumbing, so the word makes those errors concrete instead of magic.', ARRAY['net-port','net-tcp','os-system-call','os-process']::text[], ARRAY['net-port','os-process']::text[], 'net-tcp', ARRAY['the numbered doorway a service listens on','the reliable ordered protocol that carries the bytes','the os handle for a running program']::text[], 'the client kept the ___ open so it could stream updates instead of re-requesting.', 'Use ''socket'' in a sentence about a program opening a network endpoint.', 'curated', 'curator', '2026-05-25'),
('net-tcp', 'TCP', 'T-C-P', 'networking', 'coding', 2, 'A reliable ordered transport protocol for network data.', 'TCP stands for Transmission Control Protocol. It establishes a connection, delivers bytes in order, retransmits lost data, and controls flow so both sides can keep up. HTTP, database connections, SSH, and many app protocols commonly run over TCP.', 'we run the database connection over TCP so the rows come back in order and nothing gets dropped silently.', 'whenever someone talks about connections, retries, ordered streams, or "the bytes arrived in order," they''re leaning on tcp. it''s the right word for traffic that trades a little speed for not losing or scrambling your data.', ARRAY['net-udp','net-packet','net-socket','sys-http-request']::text[], ARRAY['net-packet','net-socket']::text[], 'net-udp', ARRAY['the send-and-forget protocol with no ordering or retries','the round-trip delay measured before a reply arrives','a checksum that detects corrupted bytes in transit']::text[], 'we run the database connection over ___ so the rows come back in order and nothing gets dropped silently.', 'Use ''TCP'' in a sentence about reliable ordered network delivery.', 'curated', 'curator', '2026-05-25'),
('net-throughput', 'throughput', null, 'networking', 'coding', 2, 'The actual amount of useful data delivered over time.', 'Throughput is what you really get after overhead, congestion, retries, server speed, and protocol behavior. Bandwidth is the possible capacity; throughput is the measured useful delivery. A system can have high theoretical bandwidth but low throughput under load.', 'the link is rated for a gig, but real throughput tanked once everyone got online at 8pm.', 'the speed test promises one number and your actual download crawls, that gap is throughput. it''s the reality-check word for what you really get after congestion, retries, and a slow server eat into the theoretical capacity.', ARRAY['net-bandwidth','net-latency','net-tcp','net-udp']::text[], ARRAY['net-bandwidth']::text[], 'net-latency', ARRAY['the maximum capacity the link could carry on paper','the round-trip time before data starts flowing','the number of open connections a server holds']::text[], 'the link is rated for a gig, but real ___ tanked once everyone got online at 8pm.', 'Use ''throughput'' in a sentence about actual delivered network data.', 'curated', 'curator', '2026-05-25'),
('net-tls', 'TLS', 'T-L-S', 'networking', 'coding', 2, 'The encryption protocol behind HTTPS connections.', 'TLS stands for Transport Layer Security. It encrypts data in transit, helps prove the server is who it claims to be, and protects against network observers reading or altering traffic. HTTPS is HTTP carried over TLS.', 'the page wouldn''t load over https because the TLS handshake failed on an expired cert.', 'the lock icon, the scary "not secure" warning, the expired-cert page, all of that is tls. it''s the layer that encrypts traffic and proves the server is who it says, so when a site is reachable but the browser blocks it, tls is usually why.', ARRAY['net-certificate','sys-http-request','net-vpn','sec-encryption']::text[], ARRAY['sys-http-request']::text[], 'net-certificate', ARRAY['the signed file that proves a server owns a domain','the naming system that maps domains to addresses','the ordered transport that delivers bytes reliably']::text[], 'the page wouldn''t load over https because the ___ handshake failed on an expired cert.', 'Use ''TLS'' in a sentence about encrypted web traffic.', 'curated', 'curator', '2026-05-25'),
('net-udp', 'UDP', 'U-D-P', 'networking', 'coding', 2, 'A fast transport protocol that sends packets without guaranteed delivery or ordering.', 'UDP stands for User Datagram Protocol. It sends packets without setting up the same reliable ordered stream that TCP provides. That makes it useful when speed and low overhead matter more than perfect delivery, such as realtime media, some games, DNS queries, and newer transport layers.', 'the game uses UDP for position updates because a late packet is worth less than the next fresh one.', 'ever wonder why a video call keeps moving instead of freezing to re-send a stale frame? that''s udp choosing speed over guarantees. it''s the word for when getting there fast beats getting there perfectly.', ARRAY['net-tcp','net-packet','net-latency','net-throughput']::text[], ARRAY['net-packet']::text[], 'net-latency', ARRAY['the protocol that guarantees ordered, reliable delivery','a network box that forwards packets onward','a single addressed chunk a message is split into']::text[], 'the game uses ___ for position updates because a late packet is worth less than the next fresh one.', 'Use ''UDP'' in a sentence about fast packet delivery without guaranteed ordering.', 'curated', 'curator', '2026-05-25'),
('net-vpn', 'VPN', 'V-P-N', 'networking', 'coding', 1, 'An encrypted tunnel that routes traffic through another network.', 'VPN stands for virtual private network. It creates an encrypted tunnel from a device to another network, often so the device can act as if it is inside that network. VPNs can protect traffic on untrusted networks or provide access to private company services.', 'i had to connect to the VPN before the internal admin tools would even resolve.', 'ever notice an internal dashboard only loads after you connect to work? that''s a vpn making your laptop look like it''s inside the company network. it''s the word for why access can depend on where your traffic appears to come from.', ARRAY['net-gateway','net-tls','net-ip-address','sec-mfa']::text[], ARRAY['net-ip-address']::text[], 'net-tls', ARRAY['the encryption protocol that secures https sessions','a bridge that joins two different networks together','a service that maps domain names to addresses']::text[], 'i had to connect to the ___ before the internal admin tools would even resolve.', 'Use ''VPN'' in a sentence about an encrypted tunnel to another network.', 'curated', 'curator', '2026-05-25'),
('code-algorithm', 'algorithm', null, 'programming', 'coding', 2, 'A step-by-step procedure for solving a problem.', 'An algorithm is the method, not just the code syntax. Sorting a list, finding the shortest path, picking the next review term, ranking search results, and checking duplicates can all be algorithms. Different algorithms can solve the same problem with very different tradeoffs.', 'we changed the ranking algorithm so overdue items show up before brand-new ones.', 'an algorithm is the method, not the syntax — so when engineers debate "which algorithm," they''re arguing about the approach and its tradeoffs, not the language. catching that shift tells you they''ve stopped talking about code and started talking about strategy.', ARRAY['math-complexity','math-big-o','code-loop','math-optimization']::text[], ARRAY['code-loop','math-complexity']::text[], 'math-big-o', ARRAY['the source-code syntax that implements a method','a notation for how cost grows as input grows','a data structure that organizes values in memory']::text[], 'we changed the ranking ___ so overdue items show up before brand-new ones.', 'Use ''algorithm'' in a sentence about a step-by-step method for solving a problem.', 'curated', 'curator', '2026-05-26'),
('code-argument', 'argument', null, 'programming', 'coding', 1, 'The actual value passed into a function call.', 'An argument is the real value supplied when code calls a function. If sendInvite(email) defines the parameter, sendInvite("kevin@example.com") passes an argument. Parameter is the slot; argument is what goes into the slot.', 'when i called sendInvite("sam@example.com"), that email string was the argument.', 'when you actually call a function, the value you hand it is the argument — the real thing filling the slot the parameter named. catching this distinction keeps you from getting lost when a bug is "wrong value passed in" versus "function written wrong."', ARRAY['code-parameter','code-function','code-variable','code-type']::text[], ARRAY['code-function','code-parameter']::text[], 'code-type', ARRAY['the named input slot in a function''s definition','the output a function returns when it finishes','a fixed value that can''t be reassigned later']::text[], 'when i called sendInvite("sam@example.com"), that email string was the ___.', 'Use ''argument'' in a sentence about the value passed into a function call.', 'curated', 'curator', '2026-05-26'),
('code-array', 'array', null, 'programming', 'coding', 1, 'An ordered list of values accessed by position.', 'An array stores multiple values in order. The values might be quiz options, term IDs, messages, search results, or numbers. Arrays are useful when order matters or when code needs to loop over every item.', 'i stored the four answer choices in an array so the quiz could show them in order.', 'any time order matters or you need to do the same thing to every item — the search results, the menu options, the rows — you reach for an array. it''s the shape behind half the "loop over these" conversations you''ll hear.', ARRAY['code-object','code-loop','math-set','code-type']::text[], ARRAY['code-variable']::text[], 'code-loop', ARRAY['a structured value you look up by named key','a collection with no order and no duplicates','a fixed-size block of memory reserved up front']::text[], 'i stored the four answer choices in an ___ so the quiz could show them in order.', 'Use ''array'' in a sentence about an ordered list in code.', 'curated', 'curator', '2026-05-26'),
('code-conditional', 'conditional', null, 'programming', 'coding', 1, 'An if/else decision point in code.', 'A conditional chooses which path code should take. If the user is signed in, show the app. Otherwise, show sign-in. Conditionals are where booleans, comparisons, permissions, and feature flags turn into behavior.', 'i added a conditional so signed-in users see the dashboard and everyone else gets the login page.', 'a conditional is where code stops running straight down the page and starts making choices — signed in or not, allowed or blocked. it''s the exact spot where a true/false check turns into different behavior on screen.', ARRAY['math-boolean','code-loop','sec-permission','code-exception']::text[], ARRAY['math-boolean']::text[], 'code-exception', ARRAY['code that repeats a block until told to stop','a true-or-false value used inside a test','an error that interrupts the normal path']::text[], 'i added a ___ so signed-in users see the dashboard and everyone else gets the login page.', 'Use ''conditional'' in a sentence about if/else logic.', 'curated', 'curator', '2026-05-26'),
('code-exception', 'exception', null, 'programming', 'coding', 2, 'An error condition that interrupts normal code flow.', 'An exception is what many languages throw when something goes wrong: a missing file, bad input, failed network request, or impossible state. Code can catch exceptions and recover, or let them bubble up until the app shows an error.', 'the parser threw an exception the second the response came back as something other than valid json.', 'an exception is the difference between code politely returning "no" and code stopping cold because something broke — a missing file, bad input, a dead network call. when someone says "it threw," this is what they mean.', ARRAY['code-stack-trace','code-conditional','qa-regression-test','sys-json']::text[], ARRAY['code-conditional']::text[], 'code-stack-trace', ARRAY['the call path showing where an error came from','an if/else branch that handles a special case','a log message written out for later debugging']::text[], 'the parser threw an ___ the second the response came back as something other than valid json.', 'Use ''exception'' in a sentence about code interrupting normal flow after an error.', 'curated', 'curator', '2026-05-26'),
('code-function', 'function', null, 'programming', 'coding', 1, 'A reusable block of code that can receive inputs and return work.', 'A function packages a bit of behavior behind a name. It can take inputs, do work, and return an output. Good functions let engineers reuse logic, test it in isolation, and read code at a higher level than every individual line.', 'i wrote a function that takes an email and sends the welcome message, so i can call it from anywhere.', 'the moment you hear "let''s pull that into a function," someone is saying the same steps keep getting repeated and deserve one name. spot it and you can follow how a codebase stays out of copy-paste hell.', ARRAY['code-parameter','code-argument','code-variable','qa-unit-test']::text[], ARRAY['code-variable']::text[], 'code-parameter', ARRAY['a named place where code stores a single value','a structured value that groups fields under names','a file boundary that groups related code together']::text[], 'i wrote a ___ that takes an email and sends the welcome message, so i can call it from anywhere.', 'Use ''function'' in a sentence about reusable code behavior.', 'curated', 'curator', '2026-05-26'),
('code-import', 'import', null, 'programming', 'coding', 2, 'A statement that brings code from another module into scope.', 'An import lets one module use something another module exported. If a component imports a helper, that helper becomes available in the file. Imports are also how dependency chains form across a codebase.', 'i had to import the button component at the top of the file before i could use it.', 'an import is how one file borrows code from another without copying it — and the tangle of imports is what people mean by a project''s dependencies. spotting them shows you how the pieces of a codebase actually connect.', ARRAY['code-module','code-function','flow-repository','math-graph']::text[], ARRAY['code-module']::text[], 'code-recursion', ARRAY['a file or package boundary that groups code','a statement that makes a value available to other files','a third-party package a project depends on']::text[], 'i had to ___ the button component at the top of the file before i could use it.', 'Use ''import'' in a sentence about bringing code into a file.', 'curated', 'curator', '2026-05-26'),
('code-loop', 'loop', null, 'programming', 'coding', 1, 'Code that repeats while a condition or collection says to continue.', 'A loop runs the same block of code more than once. It might process every term in a list, retry a request, count down attempts, or keep reading results until there are no more. Loops are powerful, but a bad loop can run too long or never stop.', 'i used a loop to go through every file and check which one was missing.', 'a loop is how one small block of code handles a thousand items without you writing it a thousand times — and a loop that never stops is why an app sometimes hangs. recognizing one tells you where the repetition lives.', ARRAY['code-array','code-conditional','code-recursion','math-complexity']::text[], ARRAY['code-array','code-conditional']::text[], 'code-conditional', ARRAY['a function that calls itself on a smaller case','an if/else branch that picks one path to run','an ordered list of values you process one by one']::text[], 'i used a ___ to go through every file and check which one was missing.', 'Use ''loop'' in a sentence about code repeating over items or attempts.', 'curated', 'curator', '2026-05-26'),
('code-module', 'module', null, 'programming', 'coding', 2, 'A file or package boundary that groups related code.', 'A module is a boundary for organizing code. It may export functions, components, constants, or types, and other modules can import them. Modules keep code from becoming one giant file by giving related behavior a home.', 'i moved all the date helpers into their own module so the rest of the app could import them.', 'a module is why a codebase isn''t one ten-thousand-line file — related code gets its own home and exports what others need. when a teammate says "that belongs in the auth module," this is the boundary they mean.', ARRAY['code-import','code-function','arch-service-boundary','flow-repository']::text[], ARRAY['code-function']::text[], 'code-import', ARRAY['a statement that pulls code in from elsewhere','a reusable block of behavior behind a single name','a published bundle of code others install']::text[], 'i moved all the date helpers into their own ___ so the rest of the app could import them.', 'Use ''module'' in a sentence about a file or package boundary.', 'curated', 'curator', '2026-05-26'),
('code-object', 'object', null, 'programming', 'coding', 1, 'A structured value with named fields.', 'An object groups related values under field names. A term object might have id, term, definition, pronunciation, and difficulty. Objects let code pass around one coherent thing instead of many loose variables.', 'i passed the whole user object around instead of juggling the name, email, and id separately.', 'when a developer talks about a thing''s "fields" or "properties," they''re describing an object — one bundle holding related values instead of a dozen loose ones. you''ll see this shape everywhere data gets passed around.', ARRAY['code-type','code-array','data-row','sys-json']::text[], ARRAY['code-variable','code-type']::text[], 'code-array', ARRAY['an ordered list of values reached by index','a rule describing what kind of value is allowed','a named single value that holds no fields']::text[], 'i passed the whole user ___ around instead of juggling the name, email, and id separately.', 'Use ''object'' in a sentence about a structured value with named fields.', 'curated', 'curator', '2026-05-26'),
('code-parameter', 'parameter', null, 'programming', 'coding', 1, 'A named input a function expects to receive.', 'A parameter is the placeholder name in a function definition. If a function is written as sendInvite(email), email is the parameter. It says what kind of input the function expects before anyone calls it.', 'the function has one parameter called email, so it expects a string when you call it.', 'parameters are how you read a function''s signature before you ever run it — they tell you what it wants. when someone asks "what does this function take?", they''re asking about its parameters.', ARRAY['code-function','code-argument','code-type','code-variable']::text[], ARRAY['code-function']::text[], 'code-argument', ARRAY['the actual value passed in when a function is called','a value a function hands back to whoever called it','a named slot that stores a value for later use']::text[], 'the function has one ___ called email, so it expects a string when you call it.', 'Use ''parameter'' in a sentence about an input a function expects.', 'curated', 'curator', '2026-05-26'),
('code-recursion', 'recursion', null, 'programming', 'coding', 3, 'A function calling itself to solve a smaller version of a problem.', 'Recursion is when a function calls itself. It is useful for tree-shaped data, nested folders, comments, or problems that naturally break into smaller copies of themselves. Good recursion needs a base case so it eventually stops.', 'i used recursion to render the menu, so each section just renders its own children.', 'recursion sounds bizarre — a function calling itself — until you hit nested folders, threaded comments, or a tree of menu sections, and suddenly it''s the cleanest tool there is. and the first question to ask any recursion is: what stops it?', ARRAY['code-function','math-tree','code-loop','math-complexity']::text[], ARRAY['code-function','math-tree']::text[], 'code-algorithm', ARRAY['code that repeats by using a loop construct','a function defined inside another function','the base case that finally ends the repetition']::text[], 'i used ___ to render the menu, so each section just renders its own children.', 'Use ''recursion'' in a sentence about a function calling itself with a smaller case.', 'curated', 'curator', '2026-05-26'),
('code-stack-trace', 'stack trace', null, 'programming', 'coding', 2, 'The call path showing where an error came from.', 'A stack trace lists the chain of function calls active when an exception happened. It usually includes file names, line numbers, and function names. Reading it helps developers move from "the app crashed" to the exact path that caused the crash.', 'i read the stack trace and it pointed straight at the missing transcript lookup.', 'a stack trace is the receipt an error leaves behind — the chain of calls, with files and line numbers, that led to the crash. learning to read one is how you go from "the app broke" to "line 42 broke" in seconds.', ARRAY['code-exception','code-function','flow-debugger','qa-root-cause']::text[], ARRAY['code-exception','code-function']::text[], 'flow-debugger', ARRAY['an error that interrupts normal program flow','a single log line recording one event','the live chain of functions still waiting to return']::text[], 'i read the ___ and it pointed straight at the missing transcript lookup.', 'Use ''stack trace'' in a sentence about finding where an error came from.', 'curated', 'curator', '2026-05-26'),
('code-type', 'type', null, 'programming', 'coding', 1, 'A rule for what kind of value something can hold.', 'A type describes the shape or category of a value: string, number, boolean, array, object, or a custom structure such as Term. Types help tools catch mistakes before runtime, such as treating an email string like a number.', 'the type wouldn''t let me pass a number where a string was expected, so it flagged the bug instantly.', 'a type is why your editor underlines a mistake in red before you ever hit run — it knows you tried to treat a string like a number. when someone says "that''s a type error," this is what they caught.', ARRAY['code-variable','code-object','code-array','math-boolean']::text[], ARRAY['code-variable']::text[], 'code-object', ARRAY['a structured value that groups data under named fields','an ordered list of values reached by position','a value that stays constant once it''s set']::text[], 'the ___ wouldn''t let me pass a number where a string was expected, so it flagged the bug instantly.', 'Use ''type'' in a sentence about what kind of value code expects.', 'curated', 'curator', '2026-05-26'),
('code-variable', 'variable', null, 'programming', 'coding', 1, 'A named place where code stores a value.', 'A variable gives a value a name so code can refer to it later. The value might be an email address, a count, a user record, a setting, or the result of a function call. Variables make code readable because "currentUser" says more than a raw ID floating through the file.', 'i pulled the user''s email into a variable so i wouldn''t have to look it up three more times.', 'when a teammate says "just store that in a variable," they mean give the value a name so the rest of the code can refer back to it. knowing this is the difference between following a code walkthrough and nodding along blankly.', ARRAY['code-type','code-function','code-object','math-boolean']::text[], ARRAY[]::text[], 'code-type', ARRAY['a fixed value that never changes once set','a named, reusable block of code that runs on demand','a rule for what kind of value something can hold']::text[], 'i pulled the user''s email into a ___ so i wouldn''t have to look it up three more times.', 'Use ''variable'' in a sentence about naming a value in code.', 'curated', 'curator', '2026-05-26'),
('dev-contract-test', 'contract test', null, 'qa-reliability', 'coding', 2, 'A test that checks two pieces of software still agree on the shape they exchange.', 'A contract test protects the boundary between systems. If the frontend expects `{ terms: [...] }` and the API starts returning `{ data: [...] }`, the contract broke even if both sides still build. Contract tests are especially useful around APIs, generated types, webhooks, and shared packages.', 'add a contract test so the edge function''s response keeps matching the type the client is expecting.', 'when your frontend expects `{ terms: [...] }` and the api quietly starts sending `{ data: [...] }`, both sides still build but the app breaks. a contract test catches that boundary drift before your users do, handy anywhere there''s thin wiring between a client and an api.', ARRAY['dev-api','dev-typecheck','dev-test-harness','dev-codegen']::text[], ARRAY['dev-api']::text[], 'dev-codegen', ARRAY['a pixel-diff check comparing two rendered screenshots','a check of one isolated function with the app not running','a fake dependency swapped in to steer one test run']::text[], 'add a ___ so the edge function''s response keeps matching the type the client is expecting.', 'Use ''contract test'' in a sentence about two systems agreeing on a data shape.', 'curated', 'curator', '2026-05-25'),
('dev-fixture', 'fixture', null, 'qa-reliability', 'coding', 1, 'Prepared test data used to put code into a known state.', 'A fixture is a small, intentional chunk of fake or seeded data. It might be a user object, a term row, a transcript snippet, or a set of progress records. Tests use fixtures so they do not depend on whatever random data happens to exist in a live database.', 'i wrote a fixture with one user and three fake history rows so the streak test always starts from the same place.', 'when a test is hard to read, the fixture is usually the missing noun. it''s the little world the test is pretending to be in, so the test stops depending on whatever random rows happen to be in the database that day.', ARRAY['dev-test-harness','dev-mock','agile-regression-test']::text[], ARRAY[]::text[], 'dev-mock', ARRAY['a controlled fake standing in for a real outside service','a stable way for a test to locate one element on the page','a stored earlier output a test compares later runs against']::text[], 'i wrote a ___ with one user and three fake history rows so the streak test always starts from the same place.', 'Use ''fixture'' in a sentence about prepared data for a test.', 'curated', 'curator', '2026-05-25'),
('dev-hydration', 'hydration', null, 'qa-reliability', 'coding', 2, 'The browser step where JavaScript attaches behavior to HTML that was already rendered.', 'Hydration happens when a page arrives with HTML already on screen and the client-side JavaScript boots up, connects React to that markup, and makes buttons, forms, and stateful components interactive. Hydration bugs often look like "the page is visible but clicking does nothing" or "the server rendered one thing and the browser expected another."', 'the page looked ready but hydration hadn''t finished, so tapping the button did nothing for a second.', 'ever seen a page that''s clearly loaded but clicking does nothing for a beat? that gap between "i can see it" and "i can use it" is hydration finishing. knowing the word turns a confusing dead-button moment into something you can actually debug.', ARRAY['dev-framework','dev-build','sys-cache']::text[], ARRAY['dev-framework']::text[], 'dev-snapshot-test', ARRAY['bundling source files into one shippable build output','rendering the first html on the server before sending it','fetching json from an api after the page has loaded']::text[], 'the page looked ready but ___ hadn''t finished, so tapping the button did nothing for a second.', 'Use ''hydration'' in a sentence about JavaScript making already-rendered HTML interactive.', 'curated', 'curator', '2026-05-25'),
('dev-mock', 'mock', null, 'qa-reliability', 'coding', 1, 'A fake replacement for a real dependency, used so a test can control what happens.', 'A mock stands in for something outside the code under test: a network request, database call, clock, file system, or browser API. The test controls the mock so it can prove how the app behaves when the dependency succeeds, fails, or returns a specific shape.', 'let''s mock the email service in this test so signing up doesn''t actually fire an invite to a real address.', 'you mock something so a test can run a risky flow without real consequences: no live emails, no real charges, no touching production data. it also lets you force the failure case on purpose, like making an api pretend to return a 500.', ARRAY['dev-fixture','dev-test-harness','dev-api']::text[], ARRAY[]::text[], 'dev-contract-test', ARRAY['seeded input that puts a test into a known starting state','a controlled wrapper that runs one part of the app on its own','a stored baseline a later run gets compared against']::text[], 'let''s ___ the email service in this test so signing up doesn''t actually fire an invite to a real address.', 'Use ''mock'' in a sentence about replacing a real dependency in a test.', 'curated', 'curator', '2026-05-25'),
('dev-selector', 'selector', null, 'qa-reliability', 'coding', 1, 'A stable way for code or tests to find one element on a page.', 'A selector points at a specific element in the DOM. Tests can select by role, label, text, CSS, or data-testid. Good selectors match how a user understands the page when possible; brittle selectors depend on incidental layout or class names that change during polish.', 'use a role selector for the sign-in button instead of grabbing whatever the second button on the page happens to be.', 'most browser-test failures aren''t logic bugs, they''re selector bugs: the test clicked the wrong thing. when you pick one by role or label instead of "the second button," your test stops breaking every time someone tweaks the layout.', ARRAY['dev-test-harness','agile-visual-qa','dev-framework']::text[], ARRAY[]::text[], 'dev-snapshot-test', ARRAY['a stored baseline a later run is diffed against','a controlled fake swapped in for a real dependency','seeded data that puts a test into a known state']::text[], 'use a role ___ for the sign-in button instead of grabbing whatever the second button on the page happens to be.', 'Use ''selector'' in a sentence about finding a page element in a browser test.', 'curated', 'curator', '2026-05-25'),
('dev-snapshot-test', 'snapshot test', null, 'qa-reliability', 'coding', 2, 'A test that stores a previous output and fails when the new output changes.', 'A snapshot test saves the rendered output, serialized data, or generated text from one run, then compares future runs against it. It is useful for catching unexpected changes, but weak when the snapshot is huge or nobody reviews the diff. The test says "this changed"; a human still decides whether that change is good.', 'the snapshot test failed because the version label changed from 15 to 16, which was intentional this time.', 'snapshot tests are easy to approve blindly, since the diff is just green-or-red and you hit accept. the skill is asking the real question when one fails: did this output change because i meant it to, or did something quietly break?', ARRAY['dev-selector','agile-regression-test','dev-test-harness']::text[], ARRAY[]::text[], 'dev-contract-test', ARRAY['a selector that finds one element for a test to click','a full browser run that clicks through a user journey','a benchmark that times how fast a function returns']::text[], 'the ___ failed because the version label changed from 15 to 16, which was intentional this time.', 'Use ''snapshot test'' in a sentence about detecting changed output.', 'curated', 'curator', '2026-05-25'),
('dev-test-harness', 'test harness', null, 'qa-reliability', 'coding', 2, 'A controlled wrapper that lets you run one part of an app in isolation for testing.', 'A test harness sets up the conditions a test needs: fake data, mocked services, a mounted component, a dev-only route, or a helper that starts the app in a known state. The point is not the harness itself; the point is making a messy real workflow small enough to test repeatedly.', 'we built a dev-only route as a test harness so the browser tests could drive the lesson screen without signing in first.', 'when a bug report says "that screen feels broken," a harness is how you turn that into a button you can press every run. it lets you exercise one messy piece of the app on its own instead of clicking through the whole signed-in flow each time.', ARRAY['dev-fixture','dev-mock','agile-smoke-test','agile-regression-test']::text[], ARRAY[]::text[], 'dev-contract-test', ARRAY['a browser run that signs in and clicks through a real user journey','seeded fake rows a test loads to reach a known starting state','a fake stand-in for a real network or database call']::text[], 'we built a dev-only route as a ___ so the browser tests could drive the lesson screen without signing in first.', 'Use ''test harness'' in a sentence about isolating part of an app for repeatable testing.', 'curated', 'curator', '2026-05-25'),
('qa-e2e-test', 'E2E test', 'E-to-E', 'qa-reliability', 'coding', 2, 'End-to-end test: a test that exercises a full user flow through the app.', 'E2E means end-to-end. An E2E test drives the app like a user would: open the page, click, type, navigate, and verify the result. It is useful for proving critical workflows, but it can be slower and more brittle than lower-level tests.', 'the E2E test signed in, opened a lesson, answered a question, and confirmed the xp went up.', 'end-to-end is the real-flow word: it drives the app exactly like a user would and proves a critical path actually works, instead of trusting a screenshot or some isolated logic. the tradeoff is it''s slower and more brittle, so you save it for the workflows that really matter.', ARRAY['qa-smoke-test','qa-regression-test','qa-integration-test']::text[], ARRAY['qa-integration-test']::text[], 'qa-smoke-test', ARRAY['a test for one small piece of logic in isolation','a test that checks two modules cooperating at their boundary','a quick post-deploy sanity check of just the core path']::text[], 'the ___ signed in, opened a lesson, answered a question, and confirmed the xp went up.', 'Use ''E2E test'' in a sentence about exercising a full user flow.', 'curated', 'curator', '2026-05-26'),
('qa-error-budget', 'error budget', null, 'qa-reliability', 'coding', 2, 'The allowed amount of unreliability before teams slow risky changes.', 'An error budget is the gap between perfect reliability and the agreed target. If the service is allowed 0.1 percent downtime, that small allowance is the budget. Burning it too fast can mean pausing risky launches and investing in reliability.', 'we froze risky deploys because checkout had already burned most of its error budget this month.', 'this is the tradeoff word inside reliability: it''s the small slice of allowed downtime that lets a team move fast until they''ve spent it. once it''s burned, that''s the signal to freeze risky launches and go pay down reliability debt.', ARRAY['qa-slo','qa-sla','qa-mttr','cloud-alert']::text[], ARRAY['qa-slo']::text[], 'qa-mttr', ARRAY['the internal reliability target a team holds itself to','the average minutes needed to recover after an outage','the contractual uptime figure owed to paying customers']::text[], 'we froze risky deploys because checkout had already burned most of its ___ this month.', 'Use ''error budget'' in a sentence about the allowed amount of unreliability.', 'curated', 'curator', '2026-05-26'),
('qa-fixture', 'fixture', null, 'qa-reliability', 'coding', 1, 'Known test data or setup used to make a test repeatable.', 'A fixture is prepared input, database state, file content, or setup that a test uses. Fixtures make tests repeatable by controlling the world around the behavior being checked.', 'the test fixture created an allowlisted user first, so the sign-in check had something real to run against.', 'this is the controlled-setup word: it''s how a test creates a known world instead of leaning on whatever data happens to be lying around. without one, your test passes today and fails tomorrow for reasons that have nothing to do with the code.', ARRAY['qa-unit-test','qa-mock','sys-seed-data','qa-test-coverage']::text[], ARRAY['qa-unit-test']::text[], 'qa-mock', ARRAY['a controlled fake that imitates a real outside service','a fast test of one isolated function on its own','a measure of how much behavior the tests exercise']::text[], 'the test ___ created an allowlisted user first, so the sign-in check had something real to run against.', 'Use ''fixture'' in a sentence about prepared test data or setup.', 'curated', 'curator', '2026-05-26'),
('qa-flaky-test', 'flaky test', null, 'qa-reliability', 'coding', 2, 'A test that sometimes passes and sometimes fails without a code change.', 'A flaky test gives different results under the same code because of timing, network dependence, random ordering, shared state, or unstable selectors. Flakes are dangerous because they teach teams to ignore failing tests.', 'we called it a flaky test because it failed once, then passed three times in a row with no code change.', 'this is the false-alarm word, and it''s dangerous because it teaches a team to ignore red: "oh, that one always fails sometimes." the trap is that a flake can still be hiding a real bug like a race condition, so it usually needs a fix, not a shrug.', ARRAY['qa-regression-test','sys-race-condition','qa-e2e-test','qa-fixture']::text[], ARRAY['qa-regression-test']::text[], 'qa-test-coverage', ARRAY['a test that reliably fails until the underlying bug is fixed','a stored output a test is diffed against on each run','a measure of how much code the tests actually touch']::text[], 'we called it a ___ because it failed once, then passed three times in a row with no code change.', 'Use ''flaky test'' in a sentence about nondeterministic test results.', 'curated', 'curator', '2026-05-26'),
('qa-integration-test', 'integration test', null, 'qa-reliability', 'coding', 2, 'A test that checks multiple parts working together.', 'An integration test verifies that separate pieces cooperate: a route and store, an API and database, a component and data loader, or two services. It is usually slower than a unit test but catches boundary bugs that isolated tests miss.', 'the integration test caught a save bug sitting between the profile form and the database function.', 'this is the word for why every small test can pass while the app still breaks: the bug lives at the boundary where two pieces meet, not inside either one. it''s slower than a unit test but catches the form-talks-to-database kind of failure that isolated tests sail right past.', ARRAY['qa-unit-test','qa-e2e-test','arch-interface','data-transaction']::text[], ARRAY['qa-unit-test']::text[], 'qa-e2e-test', ARRAY['a check of one function alone with nothing else wired up','a full browser run that clicks through the app like a user','a saved prior output a later run gets compared against']::text[], 'the ___ caught a save bug sitting between the profile form and the database function.', 'Use ''integration test'' in a sentence about checking multiple parts together.', 'curated', 'curator', '2026-05-26'),
('qa-mock', 'mock', null, 'qa-reliability', 'coding', 1, 'A test double that imitates a dependency.', 'A mock replaces a real dependency with a controlled fake during a test. Teams use mocks for API clients, clocks, email senders, payment gateways, and expensive services. Good mocks keep tests fast and focused; bad mocks can drift away from reality.', 'the test used a mock email sender instead of actually firing off a real invite.', 'this is the fake-dependency word, and it''s worth hearing clearly: a test full of mocks proved your local logic but never touched the real outside service. great for keeping tests fast and focused, but mocks drift from reality, so they don''t replace one real integration check.', ARRAY['qa-fixture','arch-dependency-injection','qa-unit-test','dev-mock']::text[], ARRAY['qa-fixture','arch-dependency-injection']::text[], 'qa-integration-test', ARRAY['seeded data used to set up a known starting state','a browser run that drives the full app like a real user','a test that proves separate parts work together at a boundary']::text[], 'the test used a ___ email sender instead of actually firing off a real invite.', 'Use ''mock'' in a sentence about replacing a real dependency during a test.', 'curated', 'curator', '2026-05-26'),
('qa-mttr', 'MTTR', 'M-T-T-R', 'qa-reliability', 'coding', 2, 'Mean time to recovery: the average time it takes to restore service after a failure.', 'MTTR stands for mean time to recovery. It measures how quickly a team restores service after incidents. Shorter MTTR usually comes from better alerts, runbooks, observability, rollback paths, and practiced response.', 'better alerts brought our MTTR down because the team spotted the failure much faster.', 'this is the recovery-speed word: it turns "how fast did we bounce back?" into a number you can actually improve. a shorter one comes from better alerts, runbooks, and practiced rollback paths, which is why teams obsess over shaving it down.', ARRAY['cloud-alert','cloud-observability','qa-postmortem','qa-slo']::text[], ARRAY['cloud-alert','cloud-observability']::text[], 'qa-postmortem', ARRAY['an internal reliability target set for a service','the slice of allowed unreliability before slowing down','a written review done after an incident is over']::text[], 'better alerts brought our ___ down because the team spotted the failure much faster.', 'Use ''MTTR'' in a sentence about restoring service after an incident.', 'curated', 'curator', '2026-05-26'),
('qa-postmortem', 'postmortem', null, 'qa-reliability', 'coding', 2, 'A review of what happened after an incident.', 'A postmortem is a structured review after an incident. Good postmortems explain impact, timeline, detection, response, contributing factors, root cause when known, and follow-up actions. The best ones are blameless and useful.', 'the postmortem showed the outage dragged on because the alert was pointing at the wrong service.', 'this is the learning-after-failure word, and the best ones are blameless: they dig into timeline, detection, and contributing factors instead of hunting for someone to point at. done right it''s improvement work, done wrong it''s just blame theater.', ARRAY['qa-root-cause','qa-mttr','cloud-alert','se-fmea']::text[], ARRAY['qa-mttr','cloud-alert']::text[], 'qa-root-cause', ARRAY['the underlying condition that actually caused a failure','the average time it takes to recover from an outage','an internal reliability target set for the service']::text[], 'the ___ showed the outage dragged on because the alert was pointing at the wrong service.', 'Use ''postmortem'' in a sentence about reviewing an incident after it happens.', 'curated', 'curator', '2026-05-26'),
('qa-regression-test', 'regression test', null, 'qa-reliability', 'coding', 2, 'A test that proves an old bug or behavior stays fixed.', 'A regression test captures a bug or important behavior so it cannot quietly break again. The key discipline is proving the test would have failed before the fix and passes after the fix.', 'i added a regression test locking in the mobile spacing fix so the footer can''t crowd the bottom again.', 'this is the memory word for software quality: it turns a painful bug into a permanent guard so the same thing can''t quietly come back. the discipline that makes it real is proving the test would have failed before your fix and passes after.', ARRAY['qa-smoke-test','qa-flaky-test','qa-e2e-test']::text[], ARRAY['qa-smoke-test']::text[], 'qa-flaky-test', ARRAY['a quick sanity check that the core path still works','a test that sometimes passes and sometimes fails on its own','a browser run that drives the full app like a user']::text[], 'i added a ___ locking in the mobile spacing fix so the footer can''t crowd the bottom again.', 'Use ''regression test'' in a sentence about keeping a fixed bug fixed.', 'curated', 'curator', '2026-05-26'),
('qa-root-cause', 'root cause', null, 'qa-reliability', 'coding', 2, 'The underlying reason a failure happened.', 'A root cause is the deeper reason behind a visible failure. It is not always one thing, and good incident reviews often name contributing factors too. The point is to fix the system condition that allowed the failure, not just the symptom.', 'the root cause was a missing retry path, not the one request that happened to fail.', 'this is the deeper-why word: it pushes you past the first error message to the system condition that let the bug happen at all. it''s rarely just one thing, which is why good reviews name contributing factors instead of pinning everything on a single failed request.', ARRAY['qa-postmortem','se-fmea','sec-threat-model','qa-regression-test']::text[], ARRAY['qa-postmortem']::text[], 'se-fmea', ARRAY['a structured written review done after an incident','how quickly a team restores service after a failure','the slice of allowed downtime before slowing releases']::text[], 'the ___ was a missing retry path, not the one request that happened to fail.', 'Use ''root cause'' in a sentence about the underlying reason a failure happened.', 'curated', 'curator', '2026-05-26'),
('qa-sla', 'SLA', 'S-L-A', 'qa-reliability', 'coding', 2, 'Service-level agreement: a customer-facing reliability or response-time promise.', 'SLA stands for service-level agreement. An SLA is an external promise, often contractual, about uptime, response time, support response, or other service behavior. If a vendor misses an SLA, customers may receive credits or other remedies.', 'the vendor''s SLA promised 99.9 percent availability every month, with credits if they fell short.', 'this is the promise-to-customers word, usually a contract that says "99.9% uptime" with credits owed if you miss it. it''s why reliability isn''t just engineering pride: breach one and there are real business and legal consequences.', ARRAY['qa-slo','qa-error-budget','qa-mttr','prod-compliance']::text[], ARRAY['qa-slo']::text[], 'qa-slo', ARRAY['an internal reliability target a team sets for itself','the average time it takes to restore service after an outage','the slice of allowed downtime before a team slows releases']::text[], 'the vendor''s ___ promised 99.9 percent availability every month, with credits if they fell short.', 'Use ''SLA'' in a sentence about a customer-facing reliability promise.', 'curated', 'curator', '2026-05-26'),
('qa-slo', 'SLO', 'S-L-O', 'qa-reliability', 'coding', 2, 'Service-level objective: an internal reliability target.', 'SLO stands for service-level objective. An SLO is the team target for reliability or performance, often set tighter than an external SLA. SLOs guide engineering decisions before customers feel a breach.', 'the checkout SLO targeted 99.95 percent successful requests, a notch stricter than what we promise customers.', 'this is the internal-target word, usually set tighter than the customer-facing promise so the team feels a problem before any contract is breached. it''s the number that quietly guides engineering calls about how much risk is okay this week.', ARRAY['qa-sla','qa-error-budget','cloud-metric','qa-mttr']::text[], ARRAY['qa-sla','cloud-metric']::text[], 'qa-error-budget', ARRAY['the uptime figure promised to customers in a contract','the leftover unreliability allowance before freezing risk','the count of requests a service handles each second']::text[], 'the checkout ___ targeted 99.95 percent successful requests, a notch stricter than what we promise customers.', 'Use ''SLO'' in a sentence about an internal reliability target.', 'curated', 'curator', '2026-05-26'),
('qa-smoke-test', 'smoke test', null, 'qa-reliability', 'coding', 1, 'A quick check that the most important path is not obviously broken.', 'A smoke test is a small, fast check after a build or deploy to make sure the core path still works. It does not prove every edge case. It answers the first question: is the app basically alive?', 'after the deploy, the smoke test just opened the home screen and finished one practice round to confirm nothing was obviously broken.', 'right after a deploy, this answers the first question that matters: is the app even alive? it won''t catch every edge case, but it''s the quick sanity check that separates "basically working" from "we just shipped a brick."', ARRAY['qa-e2e-test','qa-regression-test','cloud-deploy','qa-test-coverage']::text[], ARRAY['cloud-deploy']::text[], 'qa-regression-test', ARRAY['a deep test proving every edge case is handled','a test that locks in a previously fixed bug so it can''t return','a fast test of one isolated unit of logic']::text[], 'after the deploy, the ___ just opened the home screen and finished one practice round to confirm nothing was obviously broken.', 'Use ''smoke test'' in a sentence about a quick post-build or post-deploy check.', 'curated', 'curator', '2026-05-26'),
('qa-test-coverage', 'test coverage', null, 'qa-reliability', 'coding', 1, 'How much code or behavior is exercised by tests.', 'Test coverage measures what parts of a codebase or behavior set are touched by tests. Line coverage can help find blind spots, but high coverage does not guarantee good tests. The useful question is whether important behavior has meaningful protection.', 'the version pill had decent test coverage for opening it, showing the notes, and closing it again.', 'this is the map word for confidence: it shows where the app is actually protected and where you''re still running on hope. just don''t read a high number as safety, since lots of lines can be touched by tests that don''t really check anything.', ARRAY['qa-unit-test','qa-integration-test','qa-regression-test','qa-fixture']::text[], ARRAY['qa-unit-test']::text[], 'qa-fixture', ARRAY['a browser run that exercises a full user journey end to end','seeded data a test uses to set up its starting state','a test that proves an old bug stays fixed for good']::text[], 'the version pill had decent ___ for opening it, showing the notes, and closing it again.', 'Use ''test coverage'' in a sentence about how much behavior tests exercise.', 'curated', 'curator', '2026-05-26'),
('qa-unit-test', 'unit test', null, 'qa-reliability', 'coding', 1, 'A small test for one isolated piece of logic.', 'A unit test checks a small unit of code, usually a function or module, without running the whole app. It should be fast, specific, and easy to understand when it fails. Unit tests are best for pure logic, validation rules, parsers, calculations, and small state transitions.', 'the unit test proved the streak counter still works correctly when someone misses a day.', 'this is the basic confidence word in code review. before the joined-up flow gets complicated, you want to know the small rule underneath is protected, and since these are fast and specific, a failure usually tells you exactly which piece of logic broke.', ARRAY['qa-integration-test','qa-fixture','qa-mock','qa-test-coverage']::text[], ARRAY['code-function','dev-test-harness']::text[], 'qa-integration-test', ARRAY['a test that exercises several parts cooperating across a boundary','a browser run that drives a full user journey through the app','a quick check that the core path isn''t obviously broken']::text[], 'the ___ proved the streak counter still works correctly when someone misses a day.', 'Use ''unit test'' in a sentence about testing one small piece of logic.', 'curated', 'curator', '2026-05-26'),
('sys-cache-invalidation', 'cache invalidation', null, 'qa-reliability', 'coding', 2, 'The act of clearing or refreshing stale cached data so users see the current truth.', 'Cache invalidation is how you tell a cache that its old answer is no longer safe. If a preview alias points to yesterday, a CDN serves old assets, or an API response keeps showing stale data, the cache needs to be busted, expired, or refreshed. It is hard because the whole point of a cache is to reuse old work.', 'the deploy was fine, but cache invalidation lagged, so my browser kept loading the old bundle.', 'this is the word behind every "i swear i already changed it" moment: the deploy was correct but a stale cache kept serving the old version. knowing it gives you a real next move instead of mashing refresh and hoping.', ARRAY['sys-cache','ent-deployment-alias','ent-preview-deployment']::text[], ARRAY['sys-cache']::text[], 'sys-rollback', ARRAY['restoring a system to its last working release','a deadline that stops an operation running too long','trying a failed request again after a short delay']::text[], 'the deploy was fine, but ___ lagged, so my browser kept loading the old bundle.', 'Use ''cache invalidation'' in a sentence about clearing stale cached data.', 'curated', 'curator', '2026-05-25'),
('sys-race-condition', 'race condition', null, 'qa-reliability', 'coding', 2, 'A bug where the result depends on which async operation finishes first.', 'A race condition happens when two things run at the same time and the app accidentally depends on their timing. It might pass locally and fail in production because one request, timer, tab, or render finished in a different order. The fix is usually to make the ordering explicit or make repeated events safe.', 'we had a race condition in the auth flow where the second render skipped the check before the first request finished.', 'this is the worst kind of bug: real, intermittent, passes locally and fails in production because two things finished in a different order. the moment a redirect or an effect "sometimes" misbehaves, this should be the first thing you suspect.', ARRAY['sys-retry','sys-idempotent','sys-event-driven','dev-bug']::text[], ARRAY['sys-event-driven']::text[], 'sys-idempotent', ARRAY['two tasks each waiting on a lock the other holds, stuck forever','making an operation safe to repeat without doubling its effect','a deadline that stops an operation that runs too long']::text[], 'we had a ___ in the auth flow where the second render skipped the check before the first request finished.', 'Use ''race condition'' in a sentence about timing-dependent async behavior.', 'curated', 'curator', '2026-05-25'),
('sys-rate-limit', 'rate limit', null, 'qa-reliability', 'coding', 1, 'A cap on how many requests a client can make in a time window.', 'A rate limit protects a service from being overwhelmed. An API might allow 100 requests per minute, then return 429 Too Many Requests until the window resets. Good clients slow down, batch work, or retry later instead of hammering the same endpoint harder.', 'we hit the github api''s rate limit, so the script had to wait a minute before pulling more pull requests.', 'when a script calling a hosted api in a loop suddenly stops working, this is usually why. you''ve hit the cap and the service returns 429 until the window resets, so "why did the tool just quit?" gets a lot less mysterious.', ARRAY['sys-api-gateway','dev-api','sys-retry','sys-timeout']::text[], ARRAY['dev-api']::text[], 'sys-retry', ARRAY['a deadline after which a slow request is abandoned','trying a failed call again after a short pause','making a repeated write safe so it can''t double up']::text[], 'we hit the github api''s ___, so the script had to wait a minute before pulling more pull requests.', 'Use ''rate limit'' in a sentence about a service slowing down too many requests.', 'curated', 'curator', '2026-05-25'),
('sys-retry', 'retry', null, 'qa-reliability', 'coding', 1, 'Trying the same operation again after a failure, usually with a delay or limit.', 'A retry is useful when a failure might be temporary: a network blip, a rate limit, a busy database, or a flaky third-party API. Good retry logic has limits and is paired with idempotency, because repeating an unsafe operation can create duplicates or double-charge someone.', 'let''s retry the fetch twice with a short delay, but make sure the write is idempotent first.', 'agents and scripts retry calls constantly, and the word helps you tell "try again safely" apart from "repeat the damage." the catch: retrying an unsafe write can double-charge someone or create duplicates, so it only belongs where the operation is idempotent.', ARRAY['sys-idempotent','sys-timeout','sys-rate-limit','sys-queue']::text[], ARRAY['sys-idempotent']::text[], 'sys-race-condition', ARRAY['a cap on how many requests fit in a time window','a deadline that aborts an operation running too long','restoring the last working release after a bad deploy']::text[], 'let''s ___ the fetch twice with a short delay, but make sure the write is idempotent first.', 'Use ''retry'' in a sentence about trying a temporary failure again safely.', 'curated', 'curator', '2026-05-25'),
('sys-rollback', 'rollback', null, 'qa-reliability', 'coding', 2, 'Returning a system to the last known-good version after a bad release.', 'A rollback is the emergency move when a new deploy, migration, or config change breaks something important. Instead of continuing forward, you restore the previous working version or undo the risky change. Feature flags can avoid some rollbacks because you can turn the feature off without redeploying.', 'the new release broke login, so we did a rollback to the previous deployment while we figured it out.', 'this is the emergency move when a release breaks something important: instead of pushing forward, you restore the last version that worked. it''s a sign the team planned for "what if this goes wrong?" before it actually did.', ARRAY['dev-deploy','dev-feature-flag','ent-preview-deployment','sys-cache-invalidation']::text[], ARRAY['dev-deploy']::text[], 'sys-cache-invalidation', ARRAY['clearing stale cached data so users see current truth','turning a feature off with a flag without redeploying','trying a failed operation again after a short delay']::text[], 'the new release broke login, so we did a ___ to the previous deployment while we figured it out.', 'Use ''rollback'' in a sentence about returning to the last known-good version.', 'curated', 'curator', '2026-05-25'),
('sys-timeout', 'timeout', null, 'qa-reliability', 'coding', 1, 'A deadline after which a slow operation is stopped instead of waiting forever.', 'A timeout is a safety cutoff. If a network request, model call, test, or browser action takes too long, the runtime gives up and reports a timeout. Timeouts can mean the system is down, the selector was wrong, the request is too slow, or the deadline is too aggressive.', 'the browser test hit a timeout waiting for the sign-in button because the page never finished loading.', 'a timeout is rarely the real bug, it''s the symptom that points you somewhere. when a request or a browser action hits one, it''s telling you the thing is down, too slow, or your selector was wrong, so that''s where you go look next.', ARRAY['sys-retry','sys-rate-limit','sys-monitoring']::text[], ARRAY['dev-api']::text[], 'sys-retry', ARRAY['trying the same operation again after it fails','a cap on how many requests are allowed per window','clearing stale cached data so users see the current truth']::text[], 'the browser test hit a ___ waiting for the sign-in button because the page never finished loading.', 'Use ''timeout'' in a sentence about stopping a slow operation after a deadline.', 'curated', 'curator', '2026-05-25'),
('sec-attack-surface', 'attack surface', null, 'security', 'coding', 2, 'The set of exposed places an attacker could try to exploit.', 'Attack surface is every entry point or behavior someone could probe: public routes, forms, uploads, webhooks, APIs, admin actions, dependencies, credentials, and network boundaries. Reducing attack surface means leaving fewer exposed places to abuse.', 'we killed the old webhook nobody used because it just sat there adding to our attack surface.', 'this is the word that explains why every new endpoint, integration, or login option isn''t free — each one is another door someone could try. once you think in these terms, deleting an unused webhook or feature stops feeling like cleanup and starts feeling like security.', ARRAY['sec-threat-model','sec-vulnerability','sys-webhook','dev-api']::text[], ARRAY['sec-threat-model']::text[], 'sec-vulnerability', ARRAY['a structured way to ask what could go wrong','a specific flaw that can be exploited','the set of permissions bundled into a role']::text[], 'we killed the old webhook nobody used because it just sat there adding to our ___.', 'Use ''attack surface'' in a sentence about exposed places an attacker could try.', 'curated', 'curator', '2026-05-25'),
('sec-encryption', 'encryption', null, 'security', 'coding', 1, 'Scrambling data so only someone with the right key can read it.', 'Encryption turns readable data into unreadable ciphertext using a key. It can protect data in transit, such as HTTPS, or data at rest, such as stored backups. Encryption is reversible only for someone with the right key.', 'even if someone steals the backup drive, encryption keeps the customer data unreadable without the key.', 'this is the difference between a stolen laptop being a real problem and being a non-event. when you hear that traffic is "protected in transit" or a backup is safe to store somewhere, this is the mechanism doing the work — and it''s also why losing the key can mean losing the data for good.', ARRAY['net-tls','net-certificate','sec-secret','sec-hash']::text[], ARRAY['net-tls']::text[], 'sec-hash', ARRAY['a one-way fingerprint you can''t reverse','a sensitive credential like an API key','a weakness an attacker could exploit']::text[], 'even if someone steals the backup drive, ___ keeps the customer data unreadable without the key.', 'Use ''encryption'' in a sentence about unreadable protected data.', 'curated', 'curator', '2026-05-25'),
('sec-hash', 'hash', null, 'security', 'coding', 2, 'A one-way fingerprint of data.', 'A hash function turns input data into a fixed-looking fingerprint. Good hashes are one-way: you can compare fingerprints without recovering the original input. Password systems store salted password hashes instead of plain passwords.', 'we never save the raw password — we store a salted hash and compare against that when you log in.', 'this is the one people constantly mix up with encryption, and the difference matters: a real login system never stores your actual password, it stores one of these and just compares fingerprints. once that clicks, "we can''t email you your password, only reset it" finally makes sense.', ARRAY['sec-encryption','sec-secret','data-primary-key','git-commit']::text[], ARRAY['sec-encryption']::text[], 'sec-secret', ARRAY['scrambling data that a key can later unlock','a sensitive value like a token or password','a named bundle of permissions for a user']::text[], 'we never save the raw password — we store a salted ___ and compare against that when you log in.', 'Use ''hash'' in a sentence about a one-way data fingerprint.', 'curated', 'curator', '2026-05-25'),
('sec-mfa', 'MFA', 'M-F-A', 'security', 'coding', 1, 'Multi-factor authentication, where login requires more than one proof.', 'MFA stands for multi-factor authentication. It asks for two or more kinds of proof, such as a password plus an authenticator code, hardware key, device prompt, or biometric check. MFA reduces the damage if one credential is stolen.', 'i turned on MFA for my email, so now i need both my password and a code from my phone to get in.', 'this is why your bank texts you a code after you already typed the right password. knowing the term tells you a system is asking for a second kind of proof on purpose — so if one credential leaks, the account still doesn''t fall over.', ARRAY['sys-authn','sec-secret','sec-zero-trust','sec-oauth']::text[], ARRAY['sys-authn']::text[], 'sec-zero-trust', ARRAY['signing in once to reach many apps','a protocol that delegates access between services','scrambling stored data so only a key can read it']::text[], 'i turned on ___ for my email, so now i need both my password and a code from my phone to get in.', 'Use ''MFA'' in a sentence about login needing more than one proof.', 'curated', 'curator', '2026-05-25'),
('sec-oauth', 'OAuth', 'oh-auth', 'security', 'coding', 2, 'A protocol for delegated sign-in or delegated access between services.', 'OAuth lets one service grant limited access to another service without sharing the user password with that app. In sign-in flows, the app sends the user to an identity provider such as Google, receives a callback, and exchanges proof for tokens.', 'instead of building our own login, we used OAuth so people can sign in with their existing google account.', 'every "continue with google" button is running this under the hood. when you''re debugging a login that bounces through a redirect and comes back with a token — or wondering why the app never sees your actual google password — this is the word that makes the whole dance make sense.', ARRAY['sys-authn','sys-session','sys-jwt','sys-redirect']::text[], ARRAY['sys-authn','sys-redirect']::text[], 'sys-jwt', ARRAY['signing in once to reach many different apps','asking for a second proof on top of the password','a protocol for encrypting traffic in transit']::text[], 'instead of building our own login, we used ___ so people can sign in with their existing google account.', 'Use ''OAuth'' in a sentence about delegated sign-in.', 'curated', 'curator', '2026-05-25'),
('sec-permission', 'permission', null, 'security', 'coding', 1, 'A specific allowed action on a resource.', 'A permission is one concrete thing an actor is allowed to do: read a row, edit a project, invite a user, deploy a function, or view billing. Authentication proves who the actor is; permissions decide which actions that actor can take.', 'i can see the project but i don''t have permission to delete it, so someone with admin access has to do it.', 'when you can log in fine but a button is greyed out or a page 403s, this is almost always the word for what''s missing. knowing it lets you tell the difference between "the system doesn''t know who i am" and "the system knows me but won''t let me do this one thing" — which points you at totally different fixes.', ARRAY['sys-authz','sec-role','sec-rbac','sys-rls']::text[], ARRAY['sys-authz']::text[], 'sec-role', ARRAY['a named bundle of allowed actions grouped together','the step that proves who a user actually is','a token a service uses to call another service']::text[], 'i can see the project but i don''t have ___ to delete it, so someone with admin access has to do it.', 'Use ''permission'' in a sentence about one allowed action.', 'curated', 'curator', '2026-05-25'),
('sec-rbac', 'RBAC', 'R-back', 'security', 'coding', 2, 'Role-based access control, where permissions are grouped by role.', 'RBAC stands for role-based access control. Instead of checking every user against every action manually, the system assigns roles and checks what each role allows. RBAC is common in admin tools, dashboards, enterprise software, and cloud consoles.', 'we set up RBAC so editors can publish posts and viewers can only read them, instead of toggling permissions per person.', 'when an access conversation is going in circles — who can do what, why is this person blocked — naming this is what gets everyone onto the same page. it''s the standard pattern in admin tools and cloud consoles, so once you hear it you know access is being handed out by role, not user by user.', ARRAY['sec-role','sec-permission','sys-authz','sec-zero-trust']::text[], ARRAY['sec-role','sec-permission']::text[], 'sec-zero-trust', ARRAY['checking each user against each action by hand','a model that verifies every single request','letting one app borrow access from another service']::text[], 'we set up ___ so editors can publish posts and viewers can only read them, instead of toggling permissions per person.', 'Use ''RBAC'' in a sentence about role-based permissions.', 'curated', 'curator', '2026-05-25'),
('sec-role', 'role', null, 'security', 'coding', 1, 'A named bundle of permissions for a kind of user or service.', 'A role groups permissions so access can be managed by job or responsibility instead of assigning every action one by one. An admin role might manage users, a viewer role might only read reports, and a service role might run backend tasks.', 'we gave the new hire the viewer role so they can read every report but can''t change anything.', 'when someone says "just give them the editor role" instead of listing out ten separate permissions, this is the shorthand they''re using. spotting it tells you they''re handing over a whole bundle of access at once, not one action — which matters a lot when you''re deciding who gets what.', ARRAY['sec-permission','sec-rbac','sys-authz','sys-rls']::text[], ARRAY['sec-permission']::text[], 'sec-rbac', ARRAY['a single allowed action like reading one row','the system that decides if you''re logged in','a one-way fingerprint stored instead of a password']::text[], 'we gave the new hire the viewer ___ so they can read every report but can''t change anything.', 'Use ''role'' in a sentence about grouped permissions.', 'curated', 'curator', '2026-05-25'),
('sec-secret', 'secret', null, 'security', 'coding', 1, 'A sensitive credential such as an API key, token, or password.', 'A secret is any value that gives access if someone has it. API keys, service-role keys, database passwords, signing keys, and webhook secrets belong in secret storage, not commits, logs, screenshots, or chat transcripts.', 'that database password is a secret, so keep it in the env file and out of the commit.', 'when someone says "don''t ever commit that" about an API key, this is the category they mean. learning to spot one keeps you from the classic mistake of pasting a key into a screenshot, a log line, or a public repo — anything that hands over access just by being seen.', ARRAY['cloud-environment','os-environment-variable','sys-jwt','sec-mfa']::text[], ARRAY['dev-api']::text[], 'sec-threat-model', ARRAY['a public route path anyone can reach','a one-way fingerprint of stored data','a named bundle of permissions for a role']::text[], 'that database password is a ___, so keep it in the env file and out of the commit.', 'Use ''secret'' in a sentence about a value that grants access.', 'curated', 'curator', '2026-05-25'),
('sec-sso', 'SSO', 'S-S-O', 'security', 'coding', 2, 'Single sign-on, where one trusted identity provider lets users access many apps.', 'SSO stands for single sign-on. With SSO, a user signs in through a trusted identity provider, and multiple apps rely on that provider instead of each app managing a separate password. SSO often sits beside OAuth, SAML, MFA, roles, and audit logs.', 'with SSO set up, employees log in once with their work account and reach every internal app from there.', 'this is why one work login gets you into email, the dashboard, and a dozen other tools without re-typing a password each time. when names like okta, microsoft entra, or "sign in with your company account" come up, this is the setup they''re describing — one trusted provider standing in for every app''s login.', ARRAY['sec-oauth','sec-mfa','sec-role','prod-sso']::text[], ARRAY['sec-oauth']::text[], 'prod-sso', ARRAY['a protocol for delegating access between services','requiring a second proof on top of the password','a named bundle of permissions for a user type']::text[], 'with ___ set up, employees log in once with their work account and reach every internal app from there.', 'Use ''SSO'' in a sentence about one identity provider signing users into many apps.', 'curated', 'curator', '2026-05-26'),
('sec-threat-model', 'threat model', null, 'security', 'coding', 2, 'A structured way to ask what could go wrong and who might attack.', 'A threat model identifies what the system protects, who might try to abuse it, which paths they could use, and which controls reduce the risk. It turns security from vague anxiety into specific scenarios the team can design against.', 'before we let strangers upload files, we wrote a threat model covering malware, abuse, and accidental data exposure.', 'this is how a team turns vague "is this safe?" worry into a list of specific things that could actually go wrong before a feature ships. when you''re about to open something up to the public — uploads, a new endpoint — sitting down to write one is what catches the obvious abuse paths early.', ARRAY['sec-attack-surface','sec-vulnerability','sec-zero-trust']::text[], ARRAY['sec-secret','sec-permission']::text[], 'sec-attack-surface', ARRAY['the set of exposed spots an attacker could probe','a specific weakness that can be exploited','verifying every request instead of trusting the network']::text[], 'before we let strangers upload files, we wrote a ___ covering malware, abuse, and accidental data exposure.', 'Use ''threat model'' in a sentence about naming risks before launch.', 'curated', 'curator', '2026-05-25'),
('sec-vulnerability', 'vulnerability', null, 'security', 'coding', 1, 'A weakness that can be exploited.', 'A vulnerability is a flaw that can be used to break confidentiality, integrity, availability, or trust. It might live in application code, dependencies, configuration, infrastructure, authentication, or business logic.', 'we shipped the patch the same day because the vulnerability could have leaked private user data.', 'when a dependency update is flagged as "security" or a scanner lights up red, this is what it found. knowing the word helps you tell apart a theoretical weakness, a known flaw with a patch waiting, and something actively being exploited right now — which decides how fast you need to move.', ARRAY['sec-attack-surface','sec-threat-model','hw-firmware']::text[], ARRAY['sec-attack-surface']::text[], 'sec-zero-trust', ARRAY['every exposed spot an attacker could try','a structured way to map what could go wrong','scrambling data so only a key can read it']::text[], 'we shipped the patch the same day because the ___ could have leaked private user data.', 'Use ''vulnerability'' in a sentence about an exploitable weakness.', 'curated', 'curator', '2026-05-25'),
('sec-zero-trust', 'zero trust', null, 'security', 'coding', 2, 'A security model that verifies every request instead of trusting the network.', 'Zero trust is the idea that being inside a network is not enough proof. Systems should verify identity, device posture, permission, and context for each request, then grant the least access needed.', 'we moved the internal dashboard to zero trust, so it re-checks your identity and permission on every request, VPN or not.', 'this is the idea behind companies dropping the old "if you''re on the VPN you''re trusted" model. when you hear talk of checking identity and permission on every single request, or replacing the network perimeter with least-privilege access, this is the name for that whole shift.', ARRAY['sec-rbac','sec-mfa','sec-permission','net-vpn']::text[], ARRAY['sec-permission','sec-mfa']::text[], 'sec-threat-model', ARRAY['grouping permissions into roles for access','requiring more than one proof at login','a single sensitive credential like an API key']::text[], 'we moved the internal dashboard to ___, so it re-checks your identity and permission on every request, VPN or not.', 'Use ''zero trust'' in a sentence about verifying access every time.', 'curated', 'curator', '2026-05-25'),
('sys-edge-function', 'Edge Function', null, 'systems', 'coding', 2, 'A small server-side function deployed close to users, often used for API endpoints, webhooks, or secure backend work.', 'An Edge Function is code that runs on the server at the network edge instead of inside the browser. Supabase and Vercel both use the phrase. It is a common place to handle secrets, call AI APIs, validate requests, send emails, or receive webhooks because the browser should not do those jobs directly.', 'the personalize-term Edge Function calls the model and writes the rendered explanation back to the database.', 'some work can''t happen in the browser — calling an ai model, handling secrets, receiving a webhook. an edge function is where that server-side trust lives, so knowing the term lets you tell "a frontend button got clicked" apart from "actual backend work happened."', ARRAY['sys-webhook','dev-api','sys-authz']::text[], ARRAY['dev-api','sys-server']::text[], 'sys-rls', ARRAY['a database policy that decides which rows a signed-in user sees','a static image handed to the browser straight from a cdn','a piece of ui rendered on the client inside the browser']::text[], 'the personalize-term ___ calls the model and writes the rendered explanation back to the database.', 'Use ''Edge Function'' in a sentence about secure backend work near the user.', 'curated', 'curator', '2026-05-25'),
('sys-idempotent', 'idempotent', null, 'systems', 'coding', 2, 'Safe to run more than once because the repeated run leaves the system in the same final state.', 'Idempotent is the word for "retry-safe." Creating the same settings row if it does not exist is idempotent; adding $10 to a balance every time is not. Migrations, webhook handlers, and retry jobs should often be idempotent so a timeout or second click does not duplicate work.', 'make the migration idempotent so rerunning it doesn''t create a second set of duplicate rows.', 'agent work repeats commands, webhooks retry, deploy scripts get pasted twice. making an operation idempotent is what keeps those repeats from doubling rows or charging someone twice — the second run just leaves things where the first one did.', ARRAY['sys-webhook','sys-edge-function','dev-build']::text[], ARRAY['sys-webhook']::text[], 'sys-rls', ARRAY['deployed near users so it answers with low latency','a handler that fires whenever an outside event arrives','a per-row policy that hides data from the wrong user']::text[], 'make the migration ___ so rerunning it doesn''t create a second set of duplicate rows.', 'Use ''idempotent'' in a sentence about a retry-safe operation.', 'curated', 'curator', '2026-05-25'),
('sys-preview-environment', 'preview environment', null, 'systems', 'coding', 1, 'A non-production environment built from a branch so changes can be tested before users get them.', 'A preview environment is the whole temporary setting around a preview deployment: the branch build, its URL, feature flags, environment variables, auth behavior, and sometimes preview-only data. It should feel close to production, but it is allowed to be safer, smaller, or gated.', 'the preview environment sits behind a protected URL, so a failing curl doesn''t necessarily mean the deploy is broken.', 'a preview environment is where you can review a change without touching production — but it''s allowed to be gated, smaller, or safer. knowing that distinction stops you from panicking when a protected preview url behaves differently than the live app.', ARRAY['ent-preview-deployment','ent-deployment-alias','dev-staging']::text[], ARRAY['ent-preview-deployment']::text[], 'ent-stack-preview', ARRAY['the single branch build plus its throwaway url','the live domain that main gets deployed to','a copy of the database saved right before a migration runs']::text[], 'the ___ sits behind a protected URL, so a failing curl doesn''t necessarily mean the deploy is broken.', 'Use ''preview environment'' in a sentence about testing a branch before production.', 'curated', 'curator', '2026-05-25'),
('sys-rls', 'RLS (row-level security)', 'R-L-S', 'systems', 'coding', 2, 'A database rule system that decides which rows a logged-in user can read or change.', 'Row-level security is authorization inside the database. Instead of trusting the app to filter rows correctly, the database checks a policy for each row: this user can see their own progress, but not anyone else''s; this user can insert their own report, but not edit someone else''s. Supabase relies heavily on RLS.', 'RLS (row-level security) is blocking the query — the user is signed in, but the policy is hiding every row from them.', 'when data clearly exists but the app shows you nothing, rls is often the reason — the user is signed in, but the per-row policy is hiding everything. knowing the term lets you debug the auth problem at the database layer instead of chasing it in the frontend.', ARRAY['sys-authz','sys-authn','sys-edge-function']::text[], ARRAY['sys-authz']::text[], 'sys-idempotent', ARRAY['server-side code that runs at the network edge near the user','the login step that confirms who a user actually is','a store that holds api responses keyed by their url']::text[], '___ is blocking the query — the user is signed in, but the policy is hiding every row from them.', 'Use ''RLS'' in a sentence about database policies hiding rows from the wrong user.', 'curated', 'curator', '2026-05-25'),
('se-constraint', 'constraint', null, 'systems-engineering', 'coding', 1, 'A limit the design must respect.', 'A constraint is a boundary condition on the solution: budget, timeline, latency, regulation, battery life, hardware, browser support, staffing, or existing integrations. Constraints do not say what the system should be; they narrow what designs are possible.', 'the mobile-first constraint ruled out that dense desktop-only dashboard before we even sketched it.', 'this is the word for reality pushing back. when a reviewer says the budget is fixed or it has to work on a three-year-old phone, knowing it''s a constraint helps you see why the technically nicer design is still the wrong one here.', ARRAY['se-tradeoff','math-constraint','se-requirement','se-system-boundary']::text[], ARRAY['se-requirement']::text[], 'se-tradeoff', ARRAY['a capability the customer is asking the system to provide','trading away response time to gain richer detail','the outer edge marking what the team is accountable for']::text[], 'the mobile-first ___ ruled out that dense desktop-only dashboard before we even sketched it.', 'Use ''constraint'' in a sentence about a limit a design must respect.', 'curated', 'curator', '2026-05-26'),
('se-control-loop', 'control loop', null, 'systems-engineering', 'coding', 2, 'A system that measures output and adjusts input.', 'A control loop observes what is happening, compares it with a target, and changes inputs to reduce the gap. Thermostats, autoscaling, recommendation tuning, and human-in-the-loop review flows all use control-loop logic.', 'autoscaling is just a control loop: measure the queue depth, add workers, then measure again.', 'once you see this pattern you see it everywhere: measure, compare to a target, adjust, repeat. autoscaling does it, a thermostat does it, even a review process that keeps tuning does it. spotting the loop tells you where the system corrects itself and where it can''t.', ARRAY['se-feedback','cloud-autoscaling','cloud-metric','math-state-machine']::text[], ARRAY['se-feedback','cloud-metric']::text[], 'se-feedback', ARRAY['the signal returned to shape the next adjustment','a structured scan for harmful states and their safeguards','evidence the design solved the real-world need it was for']::text[], 'autoscaling is just a ___: measure the queue depth, add workers, then measure again.', 'Use ''control loop'' in a sentence about measuring output and adjusting input.', 'curated', 'curator', '2026-05-26'),
('se-feedback', 'feedback', null, 'systems-engineering', 'coding', 1, 'Information returned to adjust future behavior.', 'Feedback is information from outputs, users, sensors, tests, metrics, or reviews that changes what the system or team does next. Feedback can stabilize a system, improve a product, or expose that the wrong thing is being optimized.', 'a wrong quiz answer is useful feedback — it tells you exactly which term to review next.', 'this is the signal that tells a system or a team what to do differently next time — from users, metrics, tests, or a failed result. without it you treat every outcome as a one-off; with it you can actually improve, or notice you''ve been optimizing the wrong thing.', ARRAY['se-control-loop','cloud-metric','prod-kpi']::text[], ARRAY['se-control-loop']::text[], 'se-lifecycle', ARRAY['an autoscaler-style loop that holds a metric at its setpoint','comments from a person on the receiving end of the system','confirming each spec item was built as written']::text[], 'a wrong quiz answer is useful ___ — it tells you exactly which term to review next.', 'Use ''feedback'' in a sentence about information used to adjust future behavior.', 'curated', 'curator', '2026-05-26'),
('se-fmea', 'FMEA', 'F-M-E-A', 'systems-engineering', 'coding', 3, 'Failure mode and effects analysis: a structured way to find what could break and what happens next.', 'FMEA stands for failure mode and effects analysis. It lists possible failure modes, their effects, severity, causes, likelihood, detection, and mitigations. The goal is to catch important failure paths before they become incidents.', 'running an FMEA is how we caught that a failed email send could strand an invited user with no way back in.', 'this turns anxious ''what could go wrong?'' into an actual method — you list each failure mode, what it causes, how bad it is, and how you''d catch it. it''s how a team spots that a failed email send could quietly strand an invited user, before it happens to a real one.', ARRAY['se-hazard-analysis','sec-threat-model','qa-postmortem','se-verification']::text[], ARRAY['se-requirement','se-hazard-analysis']::text[], 'se-hazard-analysis', ARRAY['spotting harmful conditions and the safeguards that contain them','a mapping from each goal to the evidence that confirms it','confirming the implementation matches the agreed spec items']::text[], 'running an ___ is how we caught that a failed email send could strand an invited user with no way back in.', 'Use ''FMEA'' in a sentence about analyzing failure modes and effects.', 'curated', 'curator', '2026-05-26'),
('se-hazard-analysis', 'hazard analysis', null, 'systems-engineering', 'coding', 3, 'Identifying unsafe states and how to control them.', 'Hazard analysis looks for conditions that could cause harm, loss, unsafe operation, or unacceptable risk. It asks what hazards exist, what causes them, what controls reduce them, and how the team will verify those controls.', 'our hazard analysis flagged that expired invite links needed a clear recovery path, not a dead end.', 'this is risk thinking with real consequences attached — what conditions could cause harm or an unsafe state, and what controls keep them in check. it''s how a careful team reasons about, say, expired invite links needing a recovery path, before anyone gets stuck.', ARRAY['se-fmea','se-control-loop','se-verification','sec-threat-model']::text[], ARRAY['se-fmea','se-requirement']::text[], 'se-control-loop', ARRAY['a severity-ranked table of failure modes and their effects','a thermostat-style cycle that holds output near a target','the perimeter marking what counts as inside the system']::text[], 'our ___ flagged that expired invite links needed a clear recovery path, not a dead end.', 'Use ''hazard analysis'' in a sentence about finding unsafe states and controls.', 'curated', 'curator', '2026-05-26'),
('se-interface-control', 'interface control document', null, 'systems-engineering', 'coding', 3, 'A formal description of how systems connect.', 'An interface control document records how two systems interact: inputs, outputs, data shapes, timing, responsibilities, assumptions, error behavior, versioning, and ownership. The point is to prevent both sides from silently changing the connection and breaking the whole system.', 'the payment team updated the interface control document before they touched the webhook payload, so nothing downstream broke.', 'when two teams own two sides of a connection, this is what stops one of them from quietly changing the payload and breaking everything downstream. if you''ve ever had an integration die because someone renamed a field without telling you, this is the fix.', ARRAY['arch-interface','arch-api','se-system-boundary','se-traceability']::text[], ARRAY['arch-interface','se-system-boundary']::text[], 'se-traceability', ARRAY['a diagram of which parts sit inside scope and which sit outside','a narrated walkthrough of one person reaching a goal','a matrix tying each goal to the test that confirms it']::text[], 'the payment team updated the ___ before they touched the webhook payload, so nothing downstream broke.', 'Use ''interface control document'' in a sentence about documenting how systems connect.', 'curated', 'curator', '2026-05-26'),
('se-lifecycle', 'lifecycle', null, 'systems-engineering', 'coding', 2, 'The full path from concept through design, operation, maintenance, and retirement.', 'A lifecycle is the whole journey of a system or product: idea, requirements, design, build, verification, validation, release, operation, maintenance, change, and retirement. Lifecycle thinking prevents teams from only optimizing the launch moment.', 'our lifecycle plan named who''d actually maintain the integration after launch, not just who built it.', 'this is the long-view word that keeps you from only optimizing launch day. the moment a feature works, lifecycle thinking makes you ask who maintains it, who handles the changes, and what happens when it''s eventually retired — the parts that outlast the demo.', ARRAY['se-requirement','se-validation','se-traceability','prod-roadmap']::text[], ARRAY['se-requirement','se-validation']::text[], 'se-traceability', ARRAY['a matrix tracing each goal down to its confirming test','everyone whose work is touched by what the system does','a regulator that watches a reading and tunes the input']::text[], 'our ___ plan named who''d actually maintain the integration after launch, not just who built it.', 'Use ''lifecycle'' in a sentence about a system from idea through operation and retirement.', 'curated', 'curator', '2026-05-26'),
('se-requirement', 'requirement', null, 'systems-engineering', 'coding', 1, 'A stated need the system must satisfy.', 'A requirement is a clear statement of what the system must do, support, prevent, or prove. Good requirements are specific enough to design against and test against. Vague wishes become better requirements when they name the actor, condition, behavior, and acceptance evidence.', 'before we touch the code, let''s nail down the requirement: the invite link has to expire after seven days, no exceptions.', 'when you write down ''invite links expire after seven days'' instead of ''links should be secure-ish,'' you''ve given everyone something they can actually design and test against. you''ll catch the difference between someone''s preference, a design idea, and a thing the system is actually obligated to do.', ARRAY['se-verification','se-traceability','prod-acceptance-criteria','se-stakeholder']::text[], ARRAY['prod-acceptance-criteria']::text[], 'se-traceability', ARRAY['a budget or latency ceiling the design has to stay under','the trigger-to-success flow of one actor doing a task','proof from tests that the build matches what was asked']::text[], 'before we touch the code, let''s nail down the ___: the invite link has to expire after seven days, no exceptions.', 'Use ''requirement'' in a sentence about a need the system must satisfy.', 'curated', 'curator', '2026-05-26'),
('se-stakeholder', 'stakeholder', null, 'systems-engineering', 'coding', 1, 'A person or group affected by the system outcome.', 'A stakeholder is anyone who cares about or is affected by the system: users, operators, support teams, customers, compliance, finance, engineering, leadership, or external partners. Stakeholders create requirements and constraints even when they never touch the UI.', 'support turned out to be a stakeholder here, because the new error states changed every ticket they''d get.', 'this is the reminder that technical choices land on actual people. the support team is a stakeholder even though they never open the codebase — change the error states and you change the tickets they have to answer. naming them early is how you avoid surprising someone downstream.', ARRAY['se-requirement','se-tradeoff','prod-acceptance-criteria','se-validation']::text[], ARRAY['se-requirement']::text[], 'se-validation', ARRAY['a documented thing the finished system is obligated to do','the entry condition and steps of one task scenario','a regulatory or hardware limit narrowing the design']::text[], 'support turned out to be a ___ here, because the new error states changed every ticket they''d get.', 'Use ''stakeholder'' in a sentence about a person or group affected by a system.', 'curated', 'curator', '2026-05-26'),
('se-system-boundary', 'system boundary', null, 'systems-engineering', 'coding', 2, 'The line between what the system owns and what it interacts with.', 'A system boundary defines what is inside the system and what is outside it. It clarifies owned behavior, external dependencies, users, inputs, outputs, data flows, and failure responsibilities. Without a boundary, scope and accountability drift.', 'we drew the system boundary around the app, database, and edge functions, but left the email provider outside it.', 'when a big-system conversation starts sprawling, drawing the boundary is how you keep it sane — it pins down what you actually own versus what you just depend on. it''s the difference between ''we''ll handle email failures'' and ''that''s the email provider''s problem.''', ARRAY['arch-service-boundary','se-interface-control','se-stakeholder','se-use-case']::text[], ARRAY['arch-service-boundary']::text[], 'se-interface-control', ARRAY['a signed agreement on payload shape and error behavior between teams','the support rep whose ticket volume shifts after a change','the cradle-to-grave arc of a system over its life']::text[], 'we drew the ___ around the app, database, and edge functions, but left the email provider outside it.', 'Use ''system boundary'' in a sentence about what a system owns versus interacts with.', 'curated', 'curator', '2026-05-26'),
('se-traceability', 'traceability', null, 'systems-engineering', 'coding', 3, 'Linking requirements to design, tests, and evidence.', 'Traceability means you can follow a requirement through design decisions, implementation, tests, verification evidence, and change history. It helps teams prove coverage, manage risk, and understand what breaks when a requirement changes.', 'our release checklist keeps traceability from each requirement straight to its test evidence.', 'this is the paper trail that lets you follow a requirement all the way to the test that proves it. when someone asks ''are we sure feature X is covered?'' or ''what breaks if we change this requirement?'', traceability is how you answer instead of guessing.', ARRAY['se-requirement','se-verification','se-interface-control','prod-audit-log']::text[], ARRAY['se-requirement','se-verification']::text[], 'se-lifecycle', ARRAY['a contract describing how two components pass data','confirming the implementation honors every written spec item','the end-to-end arc from concept to decommission']::text[], 'our release checklist keeps ___ from each requirement straight to its test evidence.', 'Use ''traceability'' in a sentence about linking requirements to proof.', 'curated', 'curator', '2026-05-26'),
('se-tradeoff', 'tradeoff', null, 'systems-engineering', 'coding', 1, 'Choosing one benefit while accepting another cost.', 'A tradeoff is a decision where improving one quality can hurt another. You might trade speed for accuracy, flexibility for simplicity, privacy for personalization, or cost for reliability. Systems engineering treats tradeoffs as explicit decisions, not hidden accidents.', 'we made a tradeoff: sign-in is faster now, but you see less profile detail on the first screen.', 'every real decision costs something. when someone says ''we made a tradeoff,'' it''s your cue to ask what got better, what got worse, and who''s on the losing end — so the cost is a choice you made on purpose, not an accident you discover later.', ARRAY['se-constraint','se-stakeholder','qa-slo','prod-kpi']::text[], ARRAY['se-constraint']::text[], 'se-validation', ARRAY['a fixed budget or deadline the design cannot exceed','the actor, trigger, and steps of one task flow','anyone whose work changes when the system changes']::text[], 'we made a ___: sign-in is faster now, but you see less profile detail on the first screen.', 'Use ''tradeoff'' in a sentence about choosing one benefit while accepting a cost.', 'curated', 'curator', '2026-05-26'),
('se-use-case', 'use case', null, 'systems-engineering', 'coding', 1, 'A scenario describing how someone uses the system.', 'A use case describes a real interaction between an actor and the system: what the actor wants, what triggers the flow, what the system does, and what outcome counts as success. Use cases turn abstract requirements into concrete behavior.', 'the invite use case starts when someone fills out a profile and ends when the recipient lands in the app.', 'this is how you turn a fuzzy feature idea into something a person can actually test. spell out who''s acting, what kicks it off, what the system does, and what counts as success — and suddenly ''add invites'' becomes a concrete flow you can walk through end to end.', ARRAY['se-requirement','prod-story','prod-acceptance-criteria','se-validation']::text[], ARRAY['se-requirement','prod-story']::text[], 'se-verification', ARRAY['a single obligation the delivered system must meet','the fence drawn around what is in scope versus external','evidence that the design tackled the right real-world need']::text[], 'the invite ___ starts when someone fills out a profile and ends when the recipient lands in the app.', 'Use ''use case'' in a sentence about a scenario where someone uses a system.', 'curated', 'curator', '2026-05-26'),
('se-validation', 'validation', null, 'systems-engineering', 'coding', 2, 'Checking that the system solves the right real-world problem.', 'Validation asks whether the requirements and design actually meet the user or stakeholder need. A system can be verified against the spec and still fail validation if the spec solved the wrong problem. It is often summarized as "did we build the right thing?"', 'watching new users gave us validation that the onboarding flow actually helped people start learning.', 'this answers ''did we build the right thing?'' you can pass every test and still ship something nobody needed. watching real people use onboarding and seeing it actually help them start — that''s validation, and it''s the check that the spec solved a real problem.', ARRAY['se-verification','se-stakeholder','se-use-case','prod-acceptance-criteria']::text[], ARRAY['se-verification','se-stakeholder']::text[], 'se-traceability', ARRAY['evidence each line of the spec was implemented faithfully','a link table from each requirement to its passing test','a study of harmful states and the safeguards against them']::text[], 'watching new users gave us ___ that the onboarding flow actually helped people start learning.', 'Use ''validation'' in a sentence about proving a system solves the right problem.', 'curated', 'curator', '2026-05-26'),
('se-verification', 'verification', null, 'systems-engineering', 'coding', 2, 'Checking that the system was built correctly against requirements.', 'Verification asks whether the implementation satisfies the stated requirements. Tests, inspections, reviews, simulations, and traceability checks can all provide verification evidence. It is often summarized as "did we build the thing right?"', 'the end-to-end test gave us verification that the invite flow actually met the requirement.', 'this answers ''did we build the thing right?'' — does the code actually do what the requirement said. when your end-to-end test goes green, that''s verification evidence. just don''t confuse it with proof that the requirement was the right one to begin with.', ARRAY['se-validation','se-requirement','se-traceability','qa-e2e-test']::text[], ARRAY['se-requirement','qa-e2e-test']::text[], 'se-validation', ARRAY['evidence that the spec itself addressed the real need','a cross-reference matrix from goals to confirming tests','a ranked study of failure modes and their downstream effects']::text[], 'the end-to-end test gave us ___ that the invite flow actually met the requirement.', 'Use ''verification'' in a sentence about proving implementation matches requirements.', 'curated', 'curator', '2026-05-26'),
('cloud-vercel', 'Vercel', 'ver-SELL', 'tech-stack', 'coding', 1, 'A hosting platform for frontend apps, previews, serverless functions, and web deployments.', 'Vercel builds and hosts web apps, especially React and Next.js projects. It creates preview deployments for branches, serves static assets, runs serverless or edge functions, and connects GitHub changes to visible URLs.', 'Vercel created a preview deployment for my branch, so I could share a live link before merging.', 'vercel is one of the main "see it online" words in a web workflow — push a branch and it spins up a preview url. knowing it makes previews, production domains, builds, and deployment status feel like one connected system instead of scattered magic.', ARRAY['fw-nextjs','ent-preview-deployment','cloud-deploy','tool-vite']::text[], ARRAY['cloud-deploy','flow-branch']::text[], 'ent-preview-deployment', ARRAY['a version-control host where the source repo lives','a container registry that stores built docker images','a dns provider that maps a domain to an address']::text[], '___ created a preview deployment for my branch, so I could share a live link before merging.', 'Use ''Vercel'' in a sentence about hosting or preview deployments.', 'curated', 'curator', '2026-05-28'),
('data-postgres', 'Postgres', 'POST-gres', 'tech-stack', 'coding', 1, 'A popular relational database used to store structured app data.', 'Postgres, formally PostgreSQL, stores data in tables and supports SQL, transactions, indexes, constraints, JSON fields, extensions, and strong reliability features. Supabase uses Postgres as its database layer.', 'The terms table lives in Postgres, so every row I''m querying is sitting in there.', 'postgres is the actual database sitting behind supabase and a lot of serious apps. when rows, migrations, sql, and policies start flying around, knowing they all land in one real engine gives you something concrete to picture instead of a vague "the database."', ARRAY['lang-sql','data-table','data-index','data-supabase']::text[], ARRAY['lang-sql','data-table']::text[], 'data-supabase', ARRAY['a fast in-memory store used for caching and queues','the query language used to ask this database for data','a backend service bundling auth and storage around it']::text[], 'The terms table lives in ___, so every row I''m querying is sitting in there.', 'Use ''Postgres'' in a sentence about relational app data.', 'curated', 'curator', '2026-05-28'),
('data-redis', 'Redis', 'RED-iss', 'tech-stack', 'coding', 2, 'A fast in-memory data store often used for caching, queues, counters, and short-lived state.', 'Redis keeps data in memory so reads and writes can be very fast. Teams use it for caches, rate limits, background job queues, locks, pub/sub messages, and session-like data. It is not a replacement for a durable relational database in every case.', 'We stashed the rate-limit counter in Redis since it changes constantly and doesn''t need to survive a restart.', 'when engineers talk about caches, queues, or fast throwaway state as something separate from the main database, they usually mean redis. knowing it keeps memory and durable storage clear in your head — redis is fast but not where you keep the data you can''t lose.', ARRAY['cloud-cache','sys-rate-limit','arch-message-bus','data-postgres']::text[], ARRAY['cloud-cache','data-postgres']::text[], 'cloud-cache', ARRAY['a document database that persists json to disk','a message broker built only for ordered event streams','a search engine that indexes text for full-text queries']::text[], 'We stashed the rate-limit counter in ___ since it changes constantly and doesn''t need to survive a restart.', 'Use ''Redis'' in a sentence about fast cache or queue storage.', 'curated', 'curator', '2026-05-28'),
('data-supabase', 'Supabase', 'SOO-puh-base', 'tech-stack', 'coding', 1, 'A backend platform built around Postgres, authentication, storage, and edge functions.', 'Supabase gives apps a managed Postgres database, Auth, Storage, Edge Functions, generated client APIs, and dashboard tooling. In this repo, Supabase handles sign-in, term data, progress rows, migrations, and server-side functions.', 'Supabase Auth sent me the magic link, and the same project holds all our term data.', 'supabase shows up all over apps like this — it''s the bundle that ties together your postgres database, auth, storage, and edge functions. knowing the name lets you connect sign-in, term data, migrations, and server functions to a single backend instead of treating each as its own mystery.', ARRAY['data-postgres','sec-sso','sys-edge-function','sys-rls']::text[], ARRAY['data-postgres']::text[], 'sys-rls', ARRAY['the relational database engine this backend is built on','an in-memory store for short-lived cached data','a host that builds and serves frontend deployments']::text[], '___ Auth sent me the magic link, and the same project holds all our term data.', 'Use ''Supabase'' in a sentence about backend data, auth, or edge functions.', 'curated', 'curator', '2026-05-28'),
('fw-nextjs', 'Next.js', 'next J-S', 'tech-stack', 'coding', 2, 'A React framework for routing, server rendering, API routes, and production web apps.', 'Next.js builds on React by adding application structure: file-based routing, server-side rendering, server components, API handlers, static generation, and deployment conventions. It is common when teams want React plus a full web-app framework.', 'The marketing site uses Next.js so the pages render on the server and load fast.', 'react gives you the ui pieces; next.js decides the rest — routing, server rendering, api routes, how it deploys. knowing the difference keeps you from blaming react for behavior that''s actually the framework wrapped around it, especially when pages render on the server.', ARRAY['fw-react','web-ssr','sys-route','cloud-vercel']::text[], ARRAY['fw-react','sys-route']::text[], 'web-ssr', ARRAY['the UI library this framework is built on top of','a local-only tool that bundles and serves frontend code','a hosting service that runs your deployed web app']::text[], 'The marketing site uses ___ so the pages render on the server and load fast.', 'Use ''Next.js'' in a sentence about a React framework for full web apps.', 'curated', 'curator', '2026-05-28'),
('fw-react', 'React', 'REE-act', 'tech-stack', 'coding', 1, 'A JavaScript library for building user interfaces from components.', 'React lets developers build UI as components that render from props and state. It is not the whole app by itself; it usually sits with routing, styling, build tools, data fetching, and backend services. React code often appears in `.tsx` or `.jsx` files.', 'The sign-in screen is just a React component that renders from props and a bit of state.', 'react is the frontend backbone of most modern web apps you''ll touch. once you know it, all the talk of components, props, state, and hooks stops sounding like jargon and starts mapping to actual pieces of the ui you''re looking at.', ARRAY['dev-component','dev-props','dev-state','dev-hook']::text[], ARRAY['lang-javascript','dev-component']::text[], 'fw-nextjs', ARRAY['a framework that compiles templates away at build time','a state manager bolted onto a UI library separately','a CSS toolkit that styles components with utility classes']::text[], 'The sign-in screen is just a ___ component that renders from props and a bit of state.', 'Use ''React'' in a sentence about building UI from components.', 'curated', 'curator', '2026-05-28'),
('fw-svelte', 'Svelte', 'svelt', 'tech-stack', 'coding', 2, 'A frontend framework that compiles components into efficient browser JavaScript.', 'Svelte is a UI framework that does more work at build time than React or Vue. Instead of shipping a large runtime model, Svelte compiles components into JavaScript that updates the page directly. Teams pick it for concise syntax and fast interactive apps.', 'We used Svelte for a small interactive widget because it compiles down to lean JavaScript.', 'svelte makes the point that frontend frameworks aren''t all the same — it does its work at build time and ships less runtime than react or vue. knowing that helps you hear "different tradeoffs" instead of "yet another framework" when people compare them.', ARRAY['fw-react','fw-vue','tool-vite','dev-bundler']::text[], ARRAY['lang-javascript','dev-component']::text[], 'tool-vite', ARRAY['a library that re-renders through a virtual dom diff','a templating engine that renders pages only on the server','a runtime that ships a large framework bundle to the browser']::text[], 'We used ___ for a small interactive widget because it compiles down to lean JavaScript.', 'Use ''Svelte'' in a sentence about a compiled frontend framework.', 'curated', 'curator', '2026-05-28'),
('fw-vue', 'Vue', 'vyoo', 'tech-stack', 'coding', 1, 'A JavaScript framework for building user interfaces and single-page apps.', 'Vue is another major frontend framework. Like React, it helps teams build interactive interfaces from components, state, and templates. A repo using Vue will look different from a React repo, but the broad job is similar: manage UI behavior in the browser.', 'The admin dashboard was written in Vue, so the component setup looks a little different from our React app.', 'vue is another major way to build interactive frontends. when docs line up react, vue, and svelte side by side, hearing them as alternative ui frameworks — not random names — makes the comparison actually mean something.', ARRAY['fw-react','fw-svelte','lang-javascript','web-spa']::text[], ARRAY['lang-javascript','dev-component']::text[], 'fw-svelte', ARRAY['a UI library that uses JSX instead of HTML-style templates','a UI framework that compiles away and ships almost no runtime','a hosting service for deployed frontend apps']::text[], 'The admin dashboard was written in ___, so the component setup looks a little different from our React app.', 'Use ''Vue'' in a sentence about a JavaScript UI framework.', 'curated', 'curator', '2026-05-28'),
('lang-bash', 'Bash', 'bash', 'tech-stack', 'coding', 1, 'A common shell language for terminal commands and scripts.', 'Bash is both a command shell and a scripting language. It runs many terminal commands, setup scripts, deploy helpers, and automation snippets. When a file ends in `.sh` or a README says to run a command block, Bash or a similar shell is often involved.', 'The deploy helper turned out to be a Bash script that just stitched a few commands together.', 'that block of commands a readme tells you to paste? that''s usually bash. understanding it means one line can create files, run tests, set variables, or kick off other tools — and you''ll know what you''re actually about to run instead of pasting on faith.', ARRAY['cli-bash','os-shell','os-environment-variable','flow-ci']::text[], ARRAY['os-shell','cli-terminal']::text[], 'os-shell', ARRAY['a general-purpose language used for data and automation scripts','a markup language for formatting terminal output','a compiled language for building command-line binaries']::text[], 'The deploy helper turned out to be a ___ script that just stitched a few commands together.', 'Use ''Bash'' in a sentence about terminal automation.', 'curated', 'curator', '2026-05-28'),
('lang-c', 'C', 'C', 'tech-stack', 'coding', 2, 'A low-level programming language close to operating systems and hardware.', 'C is one of the foundational languages behind operating systems, embedded software, runtimes, and performance-critical libraries. It gives programmers direct control over memory and machine-level details, which also means fewer safety rails. Many newer languages and tools still compare themselves to C.', 'The operating-system library only exposed a tiny C API, so I had to call it carefully.', 'c is the granddad behind a huge amount of systems talk — operating systems, drivers, runtimes. when an engineer separates "the low-level part" from "the app part," the low-level part is often written in or descended from c, and now you know why that line gets drawn.', ARRAY['lang-cpp','lang-rust','os-kernel','hw-instruction-set']::text[], ARRAY['os-memory','code-function']::text[], 'lang-rust', ARRAY['a newer systems language that adds memory safety on top','a language that extends this one with classes and objects','a high-level language used mostly for quick scripting']::text[], 'The operating-system library only exposed a tiny ___ API, so I had to call it carefully.', 'Use ''C'' in a sentence about low-level code or system libraries.', 'curated', 'curator', '2026-05-28'),
('lang-cpp', 'C++', 'C-plus-plus', 'tech-stack', 'coding', 2, 'A compiled systems language that extends C with objects and higher-level features.', 'C++ is used for performance-heavy software such as game engines, browsers, databases, desktop apps, graphics systems, and trading systems. It gives teams deep control and speed, but the language is large and can be hard to use safely.', 'The rendering engine had a C++ module just for the parts that needed raw speed.', 'when a codebase feels heavier and more complex than ordinary web code — game engines, browsers, graphics, trading systems — c++ is often why. it buys deep control and speed at the cost of being a big, easy-to-misuse language, which explains the steeper learning curve people warn you about.', ARRAY['lang-c','lang-rust','hw-gpu','os-memory']::text[], ARRAY['lang-c','os-memory']::text[], 'lang-rust', ARRAY['the older language this one was built on top of','a newer language that adds ownership rules for memory safety','a language used mainly for browser UI behavior']::text[], 'The rendering engine had a ___ module just for the parts that needed raw speed.', 'Use ''C++'' in a sentence about high-performance native code.', 'curated', 'curator', '2026-05-28'),
('lang-csharp', 'C#', 'C-sharp', 'tech-stack', 'coding', 1, 'A Microsoft-backed programming language common in enterprise apps, .NET services, and game development.', 'C# is the main language of the .NET ecosystem. It is common in Windows-heavy companies, backend services, internal enterprise tools, and Unity games. If someone says "dotnet" or mentions a `.cs` file, C# is probably nearby.', 'Our internal claims service was written in C#, so it slots right into the .NET stack.', 'if you ever land in a microsoft-heavy shop and hear "dotnet" or see a .cs file, that''s c#. it''s worth recognizing as a major enterprise language rather than just another symbol-heavy file extension, because a lot of big internal systems and unity games run on it.', ARRAY['lang-java','prod-erp','arch-service','ent-azure']::text[], ARRAY['arch-service']::text[], 'lang-java', ARRAY['an enterprise language that runs on the Java Virtual Machine','a Microsoft markup language for laying out web pages','a scripting language for browser-side behavior']::text[], 'Our internal claims service was written in ___, so it slots right into the .NET stack.', 'Use ''C#'' in a sentence about a .NET or Microsoft-backed service.', 'curated', 'curator', '2026-05-28'),
('lang-css', 'CSS', 'C-S-S', 'tech-stack', 'coding', 1, 'The stylesheet language that controls how web pages look.', 'CSS stands for Cascading Style Sheets. It controls layout, spacing, colors, typography, responsive breakpoints, hover states, and visual presentation. HTML says what is on the page; CSS says how it is arranged and styled.', 'The mobile layout was overflowing, but it was just a CSS fix — nothing in the logic changed.', 'css is the whole look-and-feel layer — spacing, color, layout, the way things reflow on a phone. when something''s misaligned or the mobile view breaks, knowing it''s a css problem keeps you from hunting through react state or the backend for a bug that was never there.', ARRAY['lang-html','fw-react','agile-visual-qa']::text[], ARRAY['lang-html']::text[], 'fw-tailwind', ARRAY['the markup language that gives a page its structure','the scripting language that adds interactive behavior','a language for querying relational databases']::text[], 'The mobile layout was overflowing, but it was just a ___ fix — nothing in the logic changed.', 'Use ''CSS'' in a sentence about page styling or layout.', 'curated', 'curator', '2026-05-28'),
('lang-go', 'Go', 'goh', 'tech-stack', 'coding', 2, 'A compiled programming language often used for cloud services, CLIs, and infrastructure tools.', 'Go, also called Golang, is designed for simple syntax, fast builds, concurrency, and deployable server binaries. It shows up in cloud infrastructure, command-line tools, Kubernetes-related projects, and backend services.', 'We wrote the deployment CLI in Go so it ships as a single binary with no runtime to install.', 'when a cloud tool ships as one small fast binary and people praise how simple it is to deploy, that''s usually go. recognizing it helps you understand why so much infrastructure and command-line tooling feels lightweight and self-contained.', ARRAY['cloud-kubernetes','arch-service','lang-rust']::text[], ARRAY['code-function','arch-service']::text[], 'cloud-kubernetes', ARRAY['a systems language with strict ownership rules for memory','a markup language for page structure','a scripting language used for data and automation']::text[], 'We wrote the deployment CLI in ___ so it ships as a single binary with no runtime to install.', 'Use ''Go'' in a sentence about cloud infrastructure or command-line tooling.', 'curated', 'curator', '2026-05-28'),
('lang-html', 'HTML', 'H-T-M-L', 'tech-stack', 'coding', 1, 'The markup language that gives web pages their structure.', 'HTML stands for HyperText Markup Language. It describes the structure of a page: headings, paragraphs, links, forms, buttons, images, and sections. HTML is not the styling layer and not the behavior layer; CSS styles it, and JavaScript makes it interactive.', 'The modal already had the right HTML — the structure was fine, the click handler was just broken.', 'html is the skeleton the browser gets before anything makes it pretty or interactive. when a button looks fine but does nothing, knowing the markup is already there points you at the behavior code instead of the structure — a real time-saver when you''re debugging.', ARRAY['lang-css','lang-javascript','fw-react','web-ssr']::text[], ARRAY[]::text[], 'lang-css', ARRAY['the stylesheet language that controls how the page looks','the scripting language that makes a page interactive','a language for querying relational tables']::text[], 'The modal already had the right ___ — the structure was fine, the click handler was just broken.', 'Use ''HTML'' in a sentence about web page structure.', 'curated', 'curator', '2026-05-28'),
('lang-java', 'Java', 'JAH-vuh', 'tech-stack', 'coding', 1, 'A long-running enterprise programming language used for backend services, Android apps, and large systems.', 'Java is a compiled language that runs on the Java Virtual Machine. It is common in banks, healthcare, insurance, government, Android, and older enterprise platforms. Java is different from JavaScript despite the similar name.', 'The batch-processing service is written in Java — different beast entirely from the JavaScript on the frontend.', 'java and javascript share a name and almost nothing else — mixing them up is a classic beginner trip. once you can tell them apart, the older, larger, more formal feel of bank, healthcare, and android systems makes sense, because that''s where java tends to live.', ARRAY['lang-csharp','lang-kotlin','arch-service','prod-compliance']::text[], ARRAY['arch-service']::text[], 'lang-kotlin', ARRAY['a browser scripting language with a confusingly similar name','a newer JVM language often used for Android apps','a Microsoft-backed language for the .NET stack']::text[], 'The batch-processing service is written in ___ — different beast entirely from the JavaScript on the frontend.', 'Use ''Java'' in a sentence about enterprise backend code.', 'curated', 'curator', '2026-05-28'),
('lang-javascript', 'JavaScript', 'JAH-vuh-script', 'tech-stack', 'coding', 1, 'The programming language that runs in browsers and many web backends.', 'JavaScript is the main language of the web. Browsers run it to make pages interactive, and Node.js lets teams run JavaScript on servers and local tools too. React, Vite, npm packages, browser events, and many Copilot examples assume JavaScript is the baseline.', 'I wired up the button click handler in JavaScript so the menu opens when you tap it.', 'when you open a web project and a file is doing things — responding to clicks, fetching data, changing the page — it''s almost always javascript. knowing that lets you tell behavior code apart from the markup and styles around it, instead of treating every file as the same soup.', ARRAY['lang-typescript','runtime-nodejs','fw-react','tool-vite']::text[], ARRAY['code-function','code-object']::text[], 'lang-typescript', ARRAY['a stylesheet language that controls how pages look','a markup language that structures page content','a query language for reading rows from a database']::text[], 'I wired up the button click handler in ___ so the menu opens when you tap it.', 'Use ''JavaScript'' in a sentence about code that makes a web page interactive.', 'curated', 'curator', '2026-05-28'),
('lang-kotlin', 'Kotlin', 'KOT-lin', 'tech-stack', 'coding', 1, 'A programming language common in Android apps and JVM backend services.', 'Kotlin is a modern language that works well with Java and is the preferred language for many Android apps. Teams also use it for backend services on the JVM. It often appears where Java ecosystems want a cleaner newer syntax.', 'We wrote the new Android screen in Kotlin since the rest of the JVM backend already uses it.', 'kotlin is what a lot of modern android work and cleaner jvm backends are written in. spotting it tells you you''re on the android side of mobile, or the newer-syntax side of a java ecosystem that wanted to move on.', ARRAY['lang-java','lang-swift','arch-service','code-type']::text[], ARRAY['lang-java','code-function']::text[], 'lang-java', ARRAY['the older JVM language this one interoperates with','Apple''s main language for building iPhone apps','a systems language focused on memory ownership']::text[], 'We wrote the new Android screen in ___ since the rest of the JVM backend already uses it.', 'Use ''Kotlin'' in a sentence about Android or JVM code.', 'curated', 'curator', '2026-05-28'),
('lang-python', 'Python', 'PIE-thon', 'tech-stack', 'coding', 1, 'A general-purpose programming language often used for scripts, automation, data, AI, and backend services.', 'Python is known for readable syntax and a large ecosystem. Teams use it for data science, machine learning, automation scripts, APIs, notebooks, and backend jobs. When a repo has `.py` files, a `requirements.txt`, or a virtual environment, Python is probably involved.', 'I wrote the data cleanup script in Python because it''s quick to read and the libraries were already there.', 'if you ever poke at a repo full of .py files, a requirements.txt, or anything touching data, scripts, or ai, you''re in python territory. it gives you a clean place to file all the examples that clearly aren''t web javascript or shell commands.', ARRAY['ai-evals','code-function','lang-javascript']::text[], ARRAY['code-function','code-variable']::text[], 'ml-model', ARRAY['a compiled language built for low-level systems work','a language for asking a database for rows','a markup language for structuring documents']::text[], 'I wrote the data cleanup script in ___ because it''s quick to read and the libraries were already there.', 'Use ''Python'' in a sentence about automation, data, or AI code.', 'curated', 'curator', '2026-05-28'),
('lang-rust', 'Rust', null, 'tech-stack', 'coding', 2, 'A systems programming language focused on speed and memory safety.', 'Rust is used when teams want low-level performance without many classic memory bugs. It shows up in command-line tools, infrastructure, browser engines, crypto libraries, and newer backend systems. Rust code is compiled before it runs, and its ownership rules are famous for being strict.', 'We rewrote the slow parser in Rust and it stopped being the bottleneck.', 'when someone says a tool got rewritten to be faster and safer, odds are they mean rust. knowing the word helps you understand why some tools are compiled and strict instead of loose scripting code — and why people complain so much about its ownership rules while still loving the speed.', ARRAY['lang-cpp','os-memory','tool-vite']::text[], ARRAY['code-type','os-memory']::text[], 'lang-cpp', ARRAY['an older systems language with manual memory and few guardrails','a garbage-collected language built mainly for cloud services','a scripting language used for automation and data work']::text[], 'We rewrote the slow parser in ___ and it stopped being the bottleneck.', 'Use ''Rust'' in a sentence about fast compiled systems code.', 'curated', 'curator', '2026-05-28'),
('lang-sql', 'SQL', 'sequel or S-Q-L', 'tech-stack', 'coding', 1, 'Structured Query Language, the language used to ask relational databases for data.', 'SQL stands for Structured Query Language. It is used to select, insert, update, delete, join, filter, and aggregate rows in relational databases such as Postgres. Many app bugs eventually become SQL questions because the app has to read or write stored data.', 'I used SQL to pull the matching rows and join them against the term names for the dashboard.', 'a surprising number of bugs end up being sql questions, because eventually the app has to read or write stored data. once you recognize it, you can tell when an agent shifts from reading code to actually asking the database for rows — a different kind of problem with different answers.', ARRAY['data-postgres','data-join','data-table','sys-sql']::text[], ARRAY['data-table','data-row']::text[], 'data-postgres', ARRAY['a language for styling and laying out web pages','a markup language for structuring page content','the engine that executes javascript on a server']::text[], 'I used ___ to pull the matching rows and join them against the term names for the dashboard.', 'Use ''SQL'' in a sentence about querying rows from a relational database.', 'curated', 'curator', '2026-05-28'),
('lang-swift', 'Swift', null, 'tech-stack', 'coding', 1, 'Apple''s programming language for iOS, macOS, watchOS, and other Apple-platform apps.', 'Swift is the main modern language for Apple-platform development. It is used with SwiftUI and Apple SDKs to build iPhone, iPad, Mac, watch, and visionOS apps. Older Apple apps may still use Objective-C.', 'I built the iPhone prototype in Swift using SwiftUI for the screens.', 'the moment a conversation turns to xcode, iphone apps, or swiftui, swift is the language doing the work. it''s the clean line between apple app work and web app work, so knowing it keeps you from lumping native development in with everything else.', ARRAY['lang-kotlin','hw-arm','code-type']::text[], ARRAY['code-function','code-type']::text[], 'fw-swiftui', ARRAY['the main language used for native Android apps','Apple''s older app language that predates this one','a JavaScript framework for mobile-style UIs']::text[], 'I built the iPhone prototype in ___ using SwiftUI for the screens.', 'Use ''Swift'' in a sentence about an Apple-platform app.', 'curated', 'curator', '2026-05-28'),
('lang-typescript', 'TypeScript', 'TYPE-script', 'tech-stack', 'coding', 1, 'JavaScript with a type system added so tools can catch shape mistakes earlier.', 'TypeScript is a language that builds on JavaScript by adding types: declared shapes for values, functions, objects, and component props. The browser does not run TypeScript directly; build tools turn it into JavaScript. TypeScript helps editors, agents, and CI catch mismatches before runtime.', 'TypeScript flagged it right in my editor — the component expected a string and I passed a number.', 'when an agent says "typecheck failed" or a teammate mentions interfaces and prop types, that''s typescript talking. it''s the layer that catches a string-where-a-number-should-be mistake in your editor instead of letting it blow up at runtime, which is most modern react and node work.', ARRAY['lang-javascript','code-type','dev-typecheck','tool-vite']::text[], ARRAY['lang-javascript','code-type']::text[], 'dev-typecheck', ARRAY['plain javascript with no type annotations at all','a linter that only flags style and formatting issues','a compiler that turns source into machine binaries']::text[], '___ flagged it right in my editor — the component expected a string and I passed a number.', 'Use ''TypeScript'' in a sentence about catching value-shape mistakes before runtime.', 'curated', 'curator', '2026-05-28'),
('runtime-nodejs', 'Node.js', 'node J-S', 'tech-stack', 'coding', 1, 'A JavaScript runtime that lets JavaScript run outside the browser.', 'Node.js is a JavaScript runtime for servers, scripts, CLIs, build tools, and local development. npm, Vite, many test runners, and lots of backend services run on Node.js. If a project has `package.json`, it probably expects Node.js somewhere.', 'The local dev server runs on Node.js, which is why I had to bump my version to get it to start.', 'node is the reason javascript isn''t stuck in the browser. it''s why a frontend project still talks about server versions and process errors — your dev server, npm, and most build tools are all running on it behind the scenes. see a package.json and node is almost certainly expected somewhere.', ARRAY['lang-javascript','tool-npm','tool-vite','os-process']::text[], ARRAY['lang-javascript','os-process']::text[], 'tool-npm', ARRAY['a package manager that installs javascript dependencies','a frontend library for building UI components','the browser engine that renders and paints web pages']::text[], 'The local dev server runs on ___, which is why I had to bump my version to get it to start.', 'Use ''Node.js'' in a sentence about JavaScript running outside the browser.', 'curated', 'curator', '2026-05-28'),
('tool-copilot', 'Copilot', 'CO-pilot', 'tech-stack', 'coding', 1, 'An AI coding assistant that suggests, edits, and explains code inside developer tools.', 'Copilot usually means GitHub Copilot or a similar coding assistant embedded in an editor. It can autocomplete code, explain files, propose changes, and answer questions using surrounding code context. It is helpful, but its suggestions still need review.', 'Copilot suggested a React hook for the component, but I checked it before keeping it.', 'copilot is often where you first bump into a tech name you don''t recognize, since it suggests and explains code right in your editor. knowing what it''s doing helps you keep "a suggestion," "an explanation," and "verified code" separate — because its guesses still need a human eye.', ARRAY['ai-agent','ai-tool-call','fw-react']::text[], ARRAY['ai-llm']::text[], 'ai-agent', ARRAY['a tool that drives a browser through end-to-end tests','a runner that executes unit tests in the terminal','a system for tracking versions of source code']::text[], '___ suggested a React hook for the component, but I checked it before keeping it.', 'Use ''Copilot'' in a sentence about an AI coding assistant.', 'curated', 'curator', '2026-05-28'),
('tool-npm', 'npm', 'N-P-M', 'tech-stack', 'coding', 1, 'The default package manager and package registry for Node.js projects.', 'npm installs JavaScript packages, runs scripts from `package.json`, and connects projects to the npm registry. Commands like `npm install`, `npm run dev`, and `npm test` are npm commands. It is both a tool on the machine and the name of the package ecosystem.', 'Run npm install first, then start the Vite dev server.', 'npm is one of the first things you meet in nearly every web repo. knowing it tells you whether a command is installing packages, running a script from package.json, or reaching into the wider javascript ecosystem — three different things that all start with the same three letters.', ARRAY['runtime-nodejs','tool-pnpm','dev-package-manager','dev-node-modules']::text[], ARRAY['runtime-nodejs','dev-package-manager']::text[], 'tool-pnpm', ARRAY['the server runtime that npm scripts actually execute on','an online registry of ready-made UI components','a bundler that turns source files into browser assets']::text[], 'Run ___ install first, then start the Vite dev server.', 'Use ''npm'' in a sentence about installing packages or running package scripts.', 'curated', 'curator', '2026-05-28'),
('tool-playwright', 'Playwright', 'PLAY-wright', 'tech-stack', 'coding', 2, 'A browser automation tool used for end-to-end tests and visual checks.', 'Playwright can open a browser, click buttons, type into fields, inspect pages, take screenshots, and run tests across browsers. Teams use it to verify real user flows and visual behavior, not only isolated functions.', 'Playwright opened the mobile preview and caught the overflow before it shipped.', 'playwright is what actually runs when someone says "the end-to-end tests" or "visual qa." it drives a real browser — clicking, typing, screenshotting — so knowing it tells you a test is checking a whole user flow, not just one isolated function.', ARRAY['qa-e2e-test','agile-visual-qa','dev-test-runner','tool-vitest']::text[], ARRAY['qa-e2e-test','sys-route']::text[], 'agile-visual-qa', ARRAY['a terminal runner that executes logic tests with no browser','a load tester that floods an endpoint with fake traffic','a linter that flags risky patterns in source files']::text[], '___ opened the mobile preview and caught the overflow before it shipped.', 'Use ''Playwright'' in a sentence about browser automation or visual QA.', 'curated', 'curator', '2026-05-28'),
('tool-pnpm', 'pnpm', 'P-N-P-M', 'tech-stack', 'coding', 1, 'A fast package manager for Node.js projects that stores dependencies efficiently.', 'pnpm does the same broad job as npm: install packages and run scripts. Its main difference is how it stores dependencies, avoiding many duplicated package copies across projects. Some repos require pnpm because their lockfile and workspace setup are built around it.', 'The monorepo uses pnpm instead of npm, so I had to install it before anything would resolve.', 'when one project says npm install and the next insists on pnpm install, that''s not a typo — the package manager is part of the repo''s setup. knowing pnpm exists, and that it stores dependencies more efficiently, saves you from fighting a lockfile that was built around it.', ARRAY['tool-npm','runtime-nodejs','dev-lockfile','dev-monorepo']::text[], ARRAY['runtime-nodejs','dev-package-manager']::text[], 'dev-lockfile', ARRAY['the default Node package manager pnpm is an alternative to','a bundler that compiles frontend assets for the browser','the server runtime that executes javascript']::text[], 'The monorepo uses ___ instead of npm, so I had to install it before anything would resolve.', 'Use ''pnpm'' in a sentence about installing JavaScript dependencies.', 'curated', 'curator', '2026-05-28'),
('tool-vite', 'Vite', 'veet', 'tech-stack', 'coding', 1, 'A fast frontend build tool and dev server used by many React apps.', 'Vite starts a local dev server, handles hot reload, and builds browser-ready assets for production. In this app, Vite is why localhost can show a React app quickly while source files are transformed behind the scenes.', 'Vite served the app on localhost:5173 and reloaded the second I saved a file.', 'vite is the name scrolling past in your terminal when a react app boots fast on localhost. recognizing it connects the dots between your local preview url, hot reload, and the build errors you see — all of that is vite doing its job.', ARRAY['fw-react','lang-typescript','dev-bundler','dev-hot-reload']::text[], ARRAY['lang-javascript','dev-bundler']::text[], 'fw-react', ARRAY['a code formatter that rewrites spacing on save','a type checker that flags mismatched types before running','a hosting service that serves the finished build to users']::text[], '___ served the app on localhost:5173 and reloaded the second I saved a file.', 'Use ''Vite'' in a sentence about a frontend dev server or build.', 'curated', 'curator', '2026-05-28'),
('tool-vitest', 'Vitest', 'VITE-test', 'tech-stack', 'coding', 1, 'A JavaScript and TypeScript test runner commonly used with Vite projects.', 'Vitest finds test files, runs assertions, reports failures, and integrates well with Vite. It is usually used for unit tests and component-adjacent tests, while Playwright covers full browser behavior.', 'Vitest ran the content-integrity suite and pointed me straight at the assertion that broke.', 'vitest is the test runner you''ll see in vite-based repos, mostly for unit and component-level checks. knowing it helps you read a red test and figure out fast whether the failure is in your logic, your setup, or somewhere in browser-level qa entirely.', ARRAY['tool-vite','dev-test-runner','qa-unit-test','tool-playwright']::text[], ARRAY['dev-test-runner','lang-typescript']::text[], 'tool-playwright', ARRAY['an assertion helper that only describes expected values','a coverage reporter that tallies which lines tests hit','a mocking library that fakes one dependency in a test']::text[], '___ ran the content-integrity suite and pointed me straight at the assertion that broke.', 'Use ''Vitest'' in a sentence about running JavaScript or TypeScript tests.', 'curated', 'curator', '2026-05-28'),
('sys-cookie', 'cookie', null, 'web-api', 'coding', 1, 'A small value the browser stores for a site and sends with later requests.', 'A cookie is a browser-side storage mechanism tied to a site. Servers use cookies to remember sessions, preferences, or tracking IDs. Because cookies are automatically sent back to matching sites, they are useful for login but need careful security settings.', 'the browser sends a session cookie with every request, so the server knows it''s still me.', 'a cookie is how the browser stays signed in after you refresh the page — the site stored a small value and sends it back on every request. it''s tiny and powerful, which is also why it shows up in so many login bugs and privacy settings.', ARRAY['sys-session','sys-http-header','sys-origin','sys-cors']::text[], ARRAY['sys-http-request']::text[], 'sys-session', ARRAY['the longer-lived server record that remembers a logged-in user','the signed token packed with identity claims','the request line that ferries it up on each call']::text[], 'the browser sends a session ___ with every request, so the server knows it''s still me.', 'Use ''cookie'' in a sentence about browser storage sent with requests.', 'curated', 'curator', '2026-05-25'),
('sys-cors', 'CORS', 'cores', 'web-api', 'coding', 2, 'Browser security rules that control which origins can call which servers.', 'CORS stands for Cross-Origin Resource Sharing. Browsers use it to stop a page from one origin from freely reading responses from another origin unless the server allows it. CORS errors often mean the server response is missing the right access-control headers for the site that made the request.', 'it works fine in curl, but the browser blocks it with CORS because the preview origin isn''t on the allowlist.', 'CORS is the classic ''works from a script, fails in the browser'' problem. it''s not random — the browser is enforcing an origin rule, and the fix is almost always the server adding the right access-control headers for the site that made the call.', ARRAY['sys-origin','sys-http-header','sys-http-request','ent-preview-deployment']::text[], ARRAY['sys-origin','sys-http-header']::text[], 'sys-origin', ARRAY['the scheme-plus-host-plus-port a page was loaded from','the access-control lines the server returns to permit the call','the 30x bounce that sends a browser to a different URL']::text[], 'it works fine in curl, but the browser blocks it with ___ because the preview origin isn''t on the allowlist.', 'Use ''CORS'' in a sentence about browser cross-origin request rules.', 'curated', 'curator', '2026-05-25'),
('sys-http-header', 'HTTP header', 'H-T-T-P header', 'web-api', 'coding', 1, 'Metadata attached to a request or response.', 'An HTTP header is extra information sent alongside the main request or response body. Headers can say what format the client accepts, which origin made the request, what auth token is present, whether a response can be cached, or what cookie should be set.', 'i set the authorization HTTP header on the request so the function knows which user is calling.', 'a ton of invisible web behavior lives in headers: which auth token you''re sending, what content type you accept, whether a response can be cached, which origin you came from. when something works in one place and breaks in another, a missing or wrong header is often the reason.', ARRAY['sys-http-request','sys-http-response','sys-jwt','sys-cors']::text[], ARRAY['sys-http-request']::text[], 'sys-cors', ARRAY['the actual JSON or form data the message is delivering','the three-digit number that sums up how it went','the GET-or-POST verb chosen for the request']::text[], 'i set the authorization ___ on the request so the function knows which user is calling.', 'Use ''HTTP header'' in a sentence about metadata sent with a web request.', 'curated', 'curator', '2026-05-25'),
('sys-http-method', 'HTTP method', 'H-T-T-P method', 'web-api', 'coding', 1, 'The verb of an HTTP request, like GET, POST, PUT, PATCH, or DELETE.', 'An HTTP method tells the server what kind of action the request wants. GET usually reads data. POST creates or submits something. PUT and PATCH update. DELETE removes. Good APIs use methods so the same endpoint can be understood by its action, not just its URL.', 'use the POST HTTP method for the invite endpoint, since it''s sending data and creating something on the server.', 'the method tells the server whether you''re reading or changing something. GET just reads; POST creates work. when you''re reading API code, the method is how you know what an endpoint is actually about to do, not just what URL it lives at.', ARRAY['sys-http-request','dev-endpoint','sys-idempotent']::text[], ARRAY['sys-http-request']::text[], 'sys-idempotent', ARRAY['the three-digit result the server replies with','the slash-separated path that decides which handler runs','the content-type line describing how to read the body']::text[], 'use the POST ___ for the invite endpoint, since it''s sending data and creating something on the server.', 'Use ''HTTP method'' in a sentence about GET or POST on an API request.', 'curated', 'curator', '2026-05-25'),
('sys-http-request', 'HTTP request', 'H-T-T-P request', 'web-api', 'coding', 1, 'A message a client sends to a server asking for something.', 'An HTTP request is the browser or app saying "please do this" to a server. It has a method, URL, headers, and sometimes a body. Loading a page, submitting a form, checking an allowlist, and calling an Edge Function are all request moments.', 'open the network tab and you''ll see the HTTP request the browser fired off the second you hit submit.', 'almost every web bug starts here. when a page won''t load or a login won''t go through, the first thing you ask is what request went out, where it went, and what it carried. name the request and you can actually start debugging instead of just saying ''it''s broken''.', ARRAY['sys-http-response','sys-http-method','sys-http-header','dev-client']::text[], ARRAY['dev-client','dev-server']::text[], 'sys-payload', ARRAY['the reply the server hands back once it has read the request','the three-digit verdict like 200 or 404 in the reply','the GET-or-POST verb that says what action you want']::text[], 'open the network tab and you''ll see the ___ the browser fired off the second you hit submit.', 'Use ''HTTP request'' in a sentence about a browser asking a server for something.', 'curated', 'curator', '2026-05-25'),
('sys-http-response', 'HTTP response', 'H-T-T-P response', 'web-api', 'coding', 1, 'The message a server sends back after it receives a request.', 'An HTTP response is the server answering the request. It includes a status code, headers, and often a body: HTML, JSON, an image, or an error message. When the frontend says "the API returned 401," it is talking about the response.', 'the call went through but the HTTP response came back with a 403, so the user got bounced.', 'when a teammate says ''the API returned 401,'' they mean the response. it''s where the server tells you what actually happened: yes, no, not allowed, not found, try again. reading it is how you stop guessing why a call failed.', ARRAY['sys-http-request','web-status-code','sys-http-header','sys-json']::text[], ARRAY['sys-http-request']::text[], 'sys-status-code', ARRAY['the outbound call the client makes to ask for something','the GET-or-POST verb that names the action being asked for','the authorization line riding above the returned data']::text[], 'the call went through but the ___ came back with a 403, so the user got bounced.', 'Use ''HTTP response'' in a sentence about what a server sends back.', 'curated', 'curator', '2026-05-25'),
('sys-json', 'JSON', 'jay-sawn', 'web-api', 'coding', 1, 'A text format for structured data that apps and APIs can exchange.', 'JSON is a simple way to write structured data using objects, arrays, strings, numbers, booleans, and null. Most web APIs send and receive JSON because it is easy for JavaScript to parse and easy enough for humans to read. It is data shape, not prose.', 'the endpoint returns JSON like { "allowed": true }, so the frontend just checks that one field.', 'JSON is the default language of web plumbing. once you can recognize it, API responses stop looking like secret code and start looking like plain key-value data you can read line by line. nearly every endpoint you touch will send it back.', ARRAY['sys-payload','sys-http-response','ai-structured-output']::text[], ARRAY['sys-payload']::text[], 'ai-structured-output', ARRAY['the descriptive lines wrapped around the data while it travels','the tag-based markup a browser paints into a page','the SELECT-style language used to pull rows from a database']::text[], 'the endpoint returns ___ like { "allowed": true }, so the frontend just checks that one field.', 'Use ''JSON'' in a sentence about structured data sent by an API.', 'curated', 'curator', '2026-05-25'),
('sys-jwt', 'JWT', 'J-W-T', 'web-api', 'coding', 2, 'A signed token that carries identity or permission claims.', 'JWT stands for JSON Web Token. It is a compact signed string with claims inside, often used to prove who a user is when calling an API. The signature lets the server detect tampering. A JWT is not automatically safe just because it is encoded; it still needs correct expiry, storage, and verification.', 'the edge function decodes the JWT to pull out the signed-in user''s id.', 'JWTs turn up all over auth logs, edge functions, and Supabase docs. knowing the term makes that plumbing less mystical — and reminds you that being encoded isn''t the same as being safe, so it still needs proper expiry and verification.', ARRAY['sys-session','sys-http-header','sys-authn','sys-authz']::text[], ARRAY['sys-session','sys-json']::text[], 'sys-rls', ARRAY['the tiny value the browser saves and resends each call','the server-side record that tracks an active login','the request line that carries the encoded token up']::text[], 'the edge function decodes the ___ to pull out the signed-in user''s id.', 'Use ''JWT'' in a sentence about a signed auth token.', 'curated', 'curator', '2026-05-25'),
('sys-middleware', 'middleware', null, 'web-api', 'coding', 2, 'Code that runs between a request arriving and the final handler responding.', 'Middleware sits in the middle of the request path. It can check auth, add headers, log a request, rewrite a URL, block traffic, or attach user info before the route handler runs. Middleware is powerful because one small layer can affect many routes.', 'we put the auth check in middleware so it runs before any protected route renders.', 'when one rule somehow affects every page — auth checks, logging, an added header — middleware is usually why. it''s the layer cross-cutting behavior hides in, so knowing the word saves you from hunting through every route handler one at a time.', ARRAY['sys-route','sys-http-request','sys-http-header','sys-session']::text[], ARRAY['sys-route','sys-http-request']::text[], 'sys-cors', ARRAY['the single mapping that ties one path to one handler','the content-type and auth lines attached to a request','the last function in the chain that builds the reply']::text[], 'we put the auth check in ___ so it runs before any protected route renders.', 'Use ''middleware'' in a sentence about code that runs before route handlers.', 'curated', 'curator', '2026-05-25'),
('sys-origin', 'origin', null, 'web-api', 'coding', 2, 'The scheme, host, and port that define where a web page or request comes from.', 'In browser security, an origin is the combination of protocol, domain, and port: `https://example.com`, `http://localhost:5173`, and `https://example.com:8443` are different origins. CORS, cookies, and redirect allowlists often depend on origin matching exactly.', 'the preview origin has to be on the allowlist before the browser will let it call the edge function.', 'origin is why a URL that looks almost identical can behave differently — one missing port or a swapped http/https makes it a different origin, and that alone can break CORS, cookies, or an auth allowlist. it''s the detail behind a lot of ''but it''s the same site'' confusion.', ARRAY['sys-cors','sys-cookie','sys-redirect','ent-preview-deployment']::text[], ARRAY['sys-http-request']::text[], 'sys-cors', ARRAY['just the bare host name with nothing else attached','the browser policy weighing which sites may call which servers','the tiny value the browser stores and resends each call']::text[], 'the preview ___ has to be on the allowlist before the browser will let it call the edge function.', 'Use ''origin'' in a sentence about browser security matching protocol, host, and port.', 'curated', 'curator', '2026-05-25'),
('sys-payload', 'payload', null, 'web-api', 'coding', 1, 'The main data carried inside a request, response, event, or token.', 'A payload is the useful contents being transported. In an API request it might be a JSON object. In a webhook it is the event data. In a JWT it is the claims. The envelope is how the data travels; the payload is what the receiver actually needs to read.', 'the webhook payload had the order id and the amount, so we could match it to the right customer.', 'payload is the compact word for ''the actual data inside the thing.'' it shows up in API bodies, webhook events, tokens, and logs. once you have it, you can stop saying ''the data part'' and just point at what the receiver actually needs to read.', ARRAY['sys-json','sys-http-request','sys-http-response','sys-jwt']::text[], ARRAY['sys-http-request']::text[], 'sys-json', ARRAY['the descriptive lines telling the receiver how to parse the data','the web address the message was delivered to','the three-digit result the server reported back']::text[], 'the webhook ___ had the order id and the amount, so we could match it to the right customer.', 'Use ''payload'' in a sentence about the data carried by a request or event.', 'curated', 'curator', '2026-05-25'),
('sys-query-param', 'query parameter', null, 'web-api', 'coding', 1, 'A key-value value added after `?` in a URL.', 'A query parameter carries small bits of information in the URL after a question mark, like `?type=match` or `?invite=abc`. Multiple params are joined with `&`. They are useful for filters, modes, tracking, and shareable state, but they are visible in the URL and should not hold secrets.', 'i added ?mode=plain as a query parameter to the URL to force the simpler view.', 'query params show up everywhere in previews and debugging, and they explain why tacking a tiny suffix onto a URL can change the whole screen. handy mental note: they''re visible in the address bar, so they''re never the place for a secret.', ARRAY['sys-route','dev-endpoint','sys-http-request']::text[], ARRAY['sys-http-request']::text[], 'sys-route', ARRAY['the slash-separated path before the question mark that picks a screen','a bearer token tucked into a request header','the readable host name sitting at the front of the address']::text[], 'i added ?mode=plain as a ___ to the URL to force the simpler view.', 'Use ''query parameter'' in a sentence about a value after `?` in a URL.', 'curated', 'curator', '2026-05-25'),
('sys-redirect', 'redirect', null, 'web-api', 'coding', 1, 'Sending a browser or client from one URL to another.', 'A redirect is a response that tells the client to go somewhere else. Login flows use redirects constantly: leave the app for OAuth, come back to a callback URL, then move to the home route. Redirect bugs can look like loops, blank screens, or landing on the wrong page.', 'after Google sign-in, Supabase issues a redirect that sends the browser back to our callback URL.', 'redirects are the choreography behind auth: leave the app for the sign-in provider, come back to a callback URL, then land on home. knowing the word helps you follow that hop — and spot why a broken one shows up as a loop or a blank screen.', ARRAY['web-status-code','sys-route','sys-origin','sys-session']::text[], ARRAY['sys-http-response','sys-route']::text[], 'sys-cors', ARRAY['a saved bookmark the browser stores for a site','a proxy that forwards a request on the user''s behalf','a cached page the browser shows instead of refetching']::text[], 'after Google sign-in, Supabase issues a ___ that sends the browser back to our callback URL.', 'Use ''redirect'' in a sentence about sending a browser to another URL.', 'curated', 'curator', '2026-05-25'),
('sys-route', 'route', null, 'web-api', 'coding', 1, 'A URL path that an app or server knows how to handle.', 'A route maps a path like `/home`, `/term/:id`, or `/api/cron/ingest-terms` to code that should run. Frontend routes choose screens. Backend routes choose handlers. If a route is missing, the app may show a 404 even though the server is alive.', 'i added a /settings route so that path actually renders a screen instead of 404ing.', 'a route is the bridge between a URL and a piece of behavior. when navigation breaks, knowing the word lets you say ''that route isn''t defined'' instead of ''the page is blank'' — and a missing route is usually why you get a 404 even though the server is alive.', ARRAY['sys-query-param','dev-endpoint','dev-frontend','dev-backend']::text[], ARRAY['dev-frontend','dev-backend']::text[], 'sys-middleware', ARRAY['the key-value pairs hung after a ? on the address','the auth-and-logging layer that runs ahead of the handler','the three-digit number the server hands back']::text[], 'i added a /settings ___ so that path actually renders a screen instead of 404ing.', 'Use ''route'' in a sentence about a URL path handled by an app.', 'curated', 'curator', '2026-05-25'),
('sys-session', 'session', null, 'web-api', 'coding', 1, 'The server or app state that remembers a signed-in user across requests.', 'A session is the ongoing relationship between a user and an app after login. The browser may hold a cookie or token, and the server or auth provider uses it to know who the next request belongs to. Sessions can expire, refresh, or be revoked.', 'once the session exists, the app shows me the home screen without asking for another magic link.', 'session is the clean word for ''the app still knows it''s me.'' it sits underneath magic links, OAuth, and cookies — so when someone keeps getting logged out, you can ask whether the session expired or got revoked instead of blaming the login button.', ARRAY['sys-cookie','sys-jwt','sys-authn','sys-authz']::text[], ARRAY['sys-authn']::text[], 'sys-jwt', ARRAY['the tiny value the browser tucks away and resends each call','the signed token that bundles up who you are','the bounce back to your page after sign-in finishes']::text[], 'once the ___ exists, the app shows me the home screen without asking for another magic link.', 'Use ''session'' in a sentence about staying signed in across requests.', 'curated', 'curator', '2026-05-25'),
('web-domain', 'domain name', null, 'web-api', 'coding', 1, 'The human-readable site name that points to an internet address.', 'A domain name is the readable name in a URL, such as example.com. DNS translates the domain into an IP address so computers know where to send the request. Domains can point at production sites, preview environments, docs, dashboards, and APIs.', 'our production domain name stayed the same while the preview URL changed for every branch.', 'the domain name is the part of an address that stays recognizable even when paths, query strings, and per-branch preview URLs keep changing. knowing it helps you tell apart ''the site moved'' from ''just the route changed'' when you''re chasing a link.', ARRAY['web-url','net-dns','net-ip-address','cloud-environment']::text[], ARRAY['web-url']::text[], 'net-dns', ARRAY['the entire address with path and query string included','the slash path inside the address that picks a screen','the numeric IP that the name eventually resolves to']::text[], 'our production ___ stayed the same while the preview URL changed for every branch.', 'Use ''domain name'' in a sentence about the readable name of a site.', 'curated', 'curator', '2026-05-26'),
('web-spa', 'single-page app', 'S-P-A', 'web-api', 'coding', 2, 'A web app that changes screens without full page reloads.', 'SPA stands for single-page app. In a SPA, the browser loads the application shell and JavaScript handles navigation between screens. The URL can still change, but the browser often avoids a full document reload for every route.', 'the lesson app works like a single-page app when you jump from home to a term detail screen.', 'a single-page app is why a website can feel app-like — you move between screens without the whole page reloading each time. knowing the term helps you tell modern client-side navigation apart from old page-by-page sites.', ARRAY['sys-route','web-url','web-ssr','dev-component']::text[], ARRAY['sys-route','web-url']::text[], 'web-ssr', ARRAY['a site that fetches a brand-new html document per click','an app installed from a store onto the phone itself','a static site whose pages are prebuilt at deploy time']::text[], 'the lesson app works like a ___ when you jump from home to a term detail screen.', 'Use ''single-page app'' in a sentence about browser-side navigation.', 'curated', 'curator', '2026-05-26'),
('web-ssr', 'server-side rendering', 'S-S-R', 'web-api', 'coding', 2, 'Rendering page HTML on the server before the browser runs JavaScript.', 'SSR stands for server-side rendering. With SSR, the server prepares HTML for a page before it reaches the browser. This can help first load, previews, search indexing, and sharing links. Client-side JavaScript can still take over afterward.', 'the marketing page uses server-side rendering so the first view shows up quickly.', 'server-side rendering is why some pages show up fast and look right when shared, before the browser app has fully woken up — the server prepared the HTML first. it''s worth knowing when you care about first-load speed, link previews, or search indexing.', ARRAY['web-spa','sys-http-response','cloud-edge','dev-hydration']::text[], ARRAY['sys-http-response','sys-route']::text[], 'dev-hydration', ARRAY['an app that swaps screens in the browser with no full reload','the reply the server returns to a single call','the browser policy guarding calls across different sites']::text[], 'the marketing page uses ___ so the first view shows up quickly.', 'Use ''server-side rendering'' in a sentence about HTML prepared on the server.', 'curated', 'curator', '2026-05-26'),
('web-status-code', 'status code', 'H-T-T-P status code', 'web-api', 'coding', 1, 'The numeric summary of how an HTTP request turned out.', 'HTTP stands for Hypertext Transfer Protocol. A status code is the number in an HTTP response that summarizes the result. 200 usually means success, 301 or 302 means redirect, 401 means unauthenticated, 403 means forbidden, 404 means not found, and 500 means the server failed.', 'the preview came back with a 404 status code because that route didn''t exist.', 'the status code is the fast read on how a call went, and you''ll lean on it constantly in network panels, deploy logs, and error reports. 404 means the thing isn''t there; 500 means the server fell over — different problems, spotted at a glance.', ARRAY['sys-http-response','sys-http-request','sys-route']::text[], ARRAY['sys-http-response']::text[], 'web-header', ARRAY['the whole reply body the server sends back','the tiny value the browser sends along each call','the slash path that maps a URL to a handler']::text[], 'the preview came back with a 404 ___ because that route didn''t exist.', 'Use ''status code'' in a sentence about how an HTTP request turned out.', 'curated', 'curator', '2026-05-26'),
('web-url', 'URL', 'U-R-L', 'web-api', 'coding', 1, 'Uniform Resource Locator: the address that tells a browser where to go.', 'URL stands for Uniform Resource Locator. A URL is the full address for a web resource: protocol, domain, path, and sometimes query parameters or a fragment. In https://example.com/terms?mode=plain, the URL tells the browser exactly which place to request.', 'i pasted the preview URL into Chrome to check the latest branch.', 'the URL is the whole address, and being able to break it into its parts pays off fast — you can point at the domain, the route, and the query string separately when something''s wrong instead of squinting at one long string in the address bar.', ARRAY['web-domain','sys-route','sys-query-param','net-dns']::text[], ARRAY[]::text[], 'web-domain', ARRAY['just the host name portion standing on its own','the slash path inside it that maps to a screen','the key-value bits trailing after the ? in the address']::text[], 'i pasted the preview ___ into Chrome to check the latest branch.', 'Use ''URL'' in a sentence about a browser address.', 'curated', 'curator', '2026-05-26'),
('web-webhook', 'webhook', null, 'web-api', 'coding', 2, 'An HTTP callback sent when something happens elsewhere.', 'A webhook is an event notification sent over HTTP from one system to another. Instead of polling for changes, one app posts to another app when something happens: a payment succeeds, a build finishes, an invite is accepted, or a form is submitted.', 'the deploy service fired a webhook the moment the preview build finished.', 'a webhook is how one system tells another that something happened — a payment cleared, a build finished — instead of you constantly polling and asking ''done yet?''. it''s the backbone of integrations that push updates the moment they occur.', ARRAY['sys-http-request','sys-http-response','arch-event-driven','cloud-alert']::text[], ARRAY['sys-http-request']::text[], 'arch-event-driven', ARRAY['the call your client makes to pull data when it wants it','the tiny value the browser saves for login','the reply a server returns to a single outbound call']::text[], 'the deploy service fired a ___ the moment the preview build finished.', 'Use ''webhook'' in a sentence about one system notifying another over HTTP.', 'curated', 'curator', '2026-05-26')
on conflict (id) do update set
