-- 3. Drop the exact-duplicate concept rows (sys-/web- + sys-/data- twins).
delete from terms where id in ('web-request', 'web-response', 'web-header', 'web-body', 'web-route', 'web-cookie', 'web-session', 'web-cors', 'web-origin', 'sys-status-code', 'sys-table', 'sys-row', 'sys-column', 'sys-primary-key', 'sys-foreign-key', 'sys-join', 'sys-transaction', 'sys-backfill');

commit;
